/* Girounivers · textos por defecto del catálogo (descripción, información, historia). Lo que escribas tú en una ficha tiene prioridad. */
window.G = window.G || {};
G.TEXTS = {"sol":{"es":{"desc":"La estrella que ilumina la Tierra: una esfera de gas blanco-amarillenta, de largo el objeto más brillante del cielo. Nunca debe mirarse directamente ni con instrumentos sin filtro solar.","info":"Enana amarilla de tipo G2V con 1 392 700 km de diámetro (unas 109 veces el de la Tierra) que concentra cerca del 99,9 % de la masa del Sistema Solar. Su superficie ronda los 5 500 °C y su edad es de aprox. 4 600 millones de años. Su luz tarda unos 8 min 20 s en llegar a la Tierra.","myth":"Helios para los griegos, Sol para los romanos y Ra para los egipcios: casi todas las culturas lo veneraron como una deidad. Su nombre latino sigue vivo en el adjetivo «solar» y en el Sistema Solar."},"en":{"desc":"The star that lights our world: a whitish-yellow ball of gas and by far the brightest object in the sky. Never look at it directly, or through instruments without a proper solar filter.","info":"A G2V yellow dwarf 1,392,700 km across (about 109 times Earth's diameter) holding roughly 99.9% of the Solar System's mass. Its surface is around 5,500 °C and it is about 4.6 billion years old. Its light takes about 8 min 20 s to reach Earth.","myth":"Helios to the Greeks, Sol to the Romans and Ra to the Egyptians: nearly every culture revered it as a deity. Its Latin name survives in the word 'solar' and in the Solar System."}},"sirius":{"es":{"desc":"La estrella más brillante del cielo nocturno, de un blanco azulado intenso que centellea con destellos de colores cerca del horizonte. Se encuentra prolongando hacia abajo el cinturón de Orión.","info":"Estrella blanca de tipo A1V, con magnitud aprox. −1,46, a 8,6 años luz. Tiene el doble de masa del Sol y brilla unas 25 veces más. Es un sistema binario: su compañera, Sirius B, es una enana blanca que la orbita en aprox. 50 años.","myth":"Su nombre viene del griego «seirios», «abrasador». Es la «Estrella del Perro» de la constelación del Can Mayor, y los antiguos egipcios la llamaban Sopdet (Sothis): su reaparición al amanecer anunciaba la crecida anual del Nilo."},"en":{"desc":"The brightest star in the night sky, an intense bluish-white that twinkles in flashes of colour near the horizon. Find it by extending Orion's Belt downward.","info":"A white A1V star of magnitude about −1.46, 8.6 light-years away. It has twice the Sun's mass and shines about 25 times brighter. It is a binary: its companion, Sirius B, is a white dwarf orbiting it in about 50 years.","myth":"The name comes from the Greek 'seirios', 'scorching'. It is the 'Dog Star' of Canis Major, and the ancient Egyptians called it Sopdet (Sothis): its reappearance at dawn announced the yearly flooding of the Nile."}},"canopus":{"es":{"desc":"La segunda estrella más brillante del cielo, blanca con un leve matiz amarillento. Solo se ve desde el sur y latitudes bajas del norte: en la península es casi inalcanzable, pero sí se ve desde Canarias.","info":"Supergigante de tipo F0, unas 70 veces mayor que el Sol y con más de 10 000 veces su luminosidad. Su distancia es de varios cientos de años luz. Su brillo constante y su posición la hacen útil como referencia de orientación para sondas espaciales.","myth":"Los griegos la asociaron con Canopo, piloto de la flota de Menelao. Pertenecía a la gran constelación Argo Navis, el navío de los argonautas, que hoy se divide en Quilla, Vela y Popa; Canopus es la estrella principal de la Quilla."},"en":{"desc":"The second brightest star in the sky, white with a faint yellowish tint. It is visible only from the south and low northern latitudes: almost out of reach from mainland Spain, but seen from the Canaries.","info":"An F0 supergiant about 70 times the Sun's radius and more than 10,000 times as luminous. It lies several hundred light-years away. Its steady brightness and position make it a handy reference point for spacecraft navigation.","myth":"The Greeks linked it to Canopus, helmsman of Menelaus's fleet. It belonged to the great constellation Argo Navis, the ship of the Argonauts, now split into Carina, Vela and Puppis; Canopus is the brightest star of Carina."}},"arcturus":{"es":{"desc":"La estrella más brillante del hemisferio norte celeste, de un intenso color naranja. Se halla siguiendo hacia el sur la curva del mango de la Osa Mayor («sigue el arco hasta Arturo»).","info":"Gigante naranja de tipo K1,5 III, a 37 años luz, con unas 25 veces el diámetro del Sol y aprox. 170 veces su luminosidad. Es una estrella vieja con un movimiento propio notable respecto a las estrellas vecinas.","myth":"Del griego «Arktouros», «guardián de la Osa», porque parece seguir a la Osa Mayor. Es la estrella principal del Boyero, el pastor o labrador que en el mito conduce los bueyes alrededor del polo."},"en":{"desc":"The brightest star of the northern celestial hemisphere, a deep orange. Find it by following the curve of the Big Dipper's handle southward ('arc to Arcturus').","info":"A K1.5 III orange giant 37 light-years away, about 25 times the Sun's diameter and roughly 170 times as luminous. It is an old star with a notable proper motion relative to its neighbours.","myth":"From the Greek 'Arktouros', 'guardian of the Bear', because it seems to follow the Great Bear around the sky. It is the main star of Boötes, the herdsman who drives the oxen around the pole."}},"rigil-kent":{"es":{"desc":"Alfa Centauri: la tercera estrella más brillante del cielo, visible solo desde el hemisferio sur y latitudes tropicales. A simple vista parece una sola estrella amarillenta; es un sistema múltiple.","info":"Sistema triple a 4,4 años luz, el más cercano al Sol. Lo forman dos estrellas similares al Sol (A, de tipo G2V, y B, más naranja) y la débil enana roja Próxima, aún más próxima a nosotros. Próxima tiene al menos un planeta.","myth":"Su nombre viene del árabe «Rijl Qentaurus», «el pie del centauro». Junto con Hadar señala la Cruz del Sur: la línea que las une apunta hacia ella, por lo que son las «Guardas» del cielo austral."},"en":{"desc":"Alpha Centauri: the third brightest star in the sky, visible only from the southern hemisphere and tropical latitudes. To the naked eye it looks like one yellowish star, but it is a multiple system.","info":"A triple system 4.4 light-years away, the nearest to the Sun. It consists of two Sun-like stars (A, type G2V, and the more orange B) and the faint red dwarf Proxima, which is slightly closer to us still. Proxima has at least one planet.","myth":"The name comes from the Arabic 'Rijl Qentaurus', 'the foot of the centaur'. Together with Hadar it points to the Southern Cross: the line joining them leads toward it, which is why they are known as the 'Pointers'."}},"vega":{"es":{"desc":"Estrella blanco-azulada muy brillante, una de las más luminosas del cielo de verano en el hemisferio norte. Casi en el cénit en las noches de verano de España; vértice del Triángulo de Verano.","info":"Estrella de tipo A0V, a 25 años luz, con unas 40 veces la luminosidad del Sol. Gira muy rápido y está rodeada por un disco de polvo. Hace unos 12 000 años fue estrella polar, y volverá a serlo dentro de milenios por la precesión.","myth":"Del árabe «al-nasr al-waqi», «el águila que cae». En la tradición china es Zhinü, la tejedora, separada por la Vía Láctea de su amado, el boyero Niulang (Altair), a quien solo ve una noche al año."},"en":{"desc":"A very bright blue-white star, one of the brightest of the northern summer sky. It sits almost overhead on summer nights in Spain and forms one corner of the Summer Triangle.","info":"A type A0V star 25 light-years away, about 40 times the Sun's luminosity. It spins very fast and is surrounded by a dusty disc. It was the pole star roughly 12,000 years ago and will be again, thousands of years from now, thanks to precession.","myth":"From the Arabic 'al-nasr al-waqi', 'the falling eagle'. In Chinese tradition it is Zhinü, the weaver girl, separated by the Milky Way from her beloved, the cowherd Niulang (Altair), whom she meets only one night a year."}},"capella":{"es":{"desc":"Estrella amarillenta muy brillante, la sexta del cielo. En invierno se ve muy alta, hacia el cénit al anochecer, y desde España está muchas horas sobre el horizonte.","info":"Sistema de cuatro estrellas a aprox. 43 años luz. Lo dominan dos gigantes amarillas muy próximas entre sí, cada una de unas 10 veces el radio del Sol, acompañadas de una pareja lejana de enanas rojas.","myth":"Su nombre latino significa «cabrita». Se identifica con la cabra Amaltea, que según el mito amamantó a Zeus niño. En la constelación del Auriga, el cochero, se representa llevando a la cabra en el hombro."},"en":{"desc":"A very bright yellowish star, the sixth brightest in the sky. In winter it rides very high, near the zenith in the evening, and stays above the horizon for many hours from Spain.","info":"A four-star system about 43 light-years away. It is dominated by two yellow giants very close together, each about 10 times the Sun's radius, accompanied by a distant pair of red dwarfs.","myth":"Its Latin name means 'little she-goat'. It is identified with the goat Amalthea, who in myth nursed the infant Zeus. In the constellation Auriga, the charioteer, it is drawn as the goat he carries on his shoulder."}},"rigel":{"es":{"desc":"Estrella blanco-azulada muy brillante en el pie izquierdo de Orión, la más luminosa de la constelación a pesar de llevar la letra beta. Brilla frente al tono rojizo de Betelgeuse.","info":"Supergigante azul de tipo B8 Ia, a aprox. 860 años luz, con unas 120 000 veces la luminosidad del Sol y un radio de unas 70 veces el solar. Es un sistema múltiple, con compañeras más débiles visibles con telescopio.","myth":"Su nombre viene del árabe «Rijl Jauzah al-Yusra», «el pie izquierdo del Gigante». Es Beta Orionis y marca la pierna del cazador Orión, que en la mitología griega persigue a las Pléyades."},"en":{"desc":"A brilliant blue-white star at Orion's left foot, the most luminous in the constellation despite carrying the letter beta. It shines in contrast with the reddish glow of Betelgeuse.","info":"A B8 Ia blue supergiant about 860 light-years away, roughly 120,000 times the Sun's luminosity and about 70 times its radius. It is a multiple system, with fainter companions visible in a telescope.","myth":"The name comes from the Arabic 'Rijl Jauzah al-Yusra', 'the left foot of the Giant'. It is Beta Orionis and marks the leg of Orion the hunter, who in Greek myth chases the Pleiades."}},"procyon":{"es":{"desc":"Estrella blanco-amarillenta brillante, la octava del cielo, en el vértice del Triángulo de Invierno junto a Sirius y Betelgeuse. Se localiza al este de Orión.","info":"Estrella de tipo F5 IV-V a 11,5 años luz, una de las más cercanas al Sol, con aprox. 7 veces su luminosidad. Es binaria: su compañera, Procyon B, es una enana blanca con un periodo de unos 40 años.","myth":"Del griego «prokyon», «antes del perro»: sale por el horizonte poco antes que Sirius, la Estrella del Perro. Es la estrella principal del Can Menor, el pequeño can del cazador Orión."},"en":{"desc":"A bright yellowish-white star, the eighth brightest in the sky, at a corner of the Winter Triangle alongside Sirius and Betelgeuse. Look for it east of Orion.","info":"An F5 IV-V star 11.5 light-years away, one of the Sun's nearest neighbours, with about 7 times its luminosity. It is a binary: its companion, Procyon B, is a white dwarf with an orbital period of about 40 years.","myth":"From the Greek 'prokyon', 'before the dog': it rises just before Sirius, the Dog Star. It is the main star of Canis Minor, the little dog of Orion the hunter."}},"betelgeuse":{"es":{"desc":"Supergigante roja en el hombro de Orión, de un naranja-rojizo inconfundible. Su brillo varía de forma irregular y es una de las estrellas más fáciles de reconocer en el cielo de invierno.","info":"Supergigante roja de tipo M1-M2, variable semirregular cuya magnitud oscila aprox. entre 0 y 1,6. Su radio equivale a cientos de veces el del Sol. Entre 2019 y 2020 sufrió una caída de brillo sin precedentes. Acabará como supernova.","myth":"Su nombre deriva del árabe «yad al-Jauzah», «la mano del Gigante», con una deformación posterior en la transcripción. Marca el hombro (o la axila) de Orión, el cazador gigante de la mitología griega."},"en":{"desc":"A red supergiant on Orion's shoulder, an unmistakable orange-red. Its brightness varies irregularly, and it is one of the easiest stars to recognise in the winter sky.","info":"An M1-M2 red supergiant and semi-regular variable whose magnitude ranges roughly from 0 to 1.6. Its radius is hundreds of times the Sun's. In 2019-2020 it underwent an unprecedented dimming. It will end its life as a supernova.","myth":"The name derives from the Arabic 'yad al-Jauzah', 'the hand of the Giant', later garbled in transcription. It marks the shoulder (or armpit) of Orion, the giant hunter of Greek mythology."}},"achernar":{"es":{"desc":"Estrella blanco-azulada brillante en el extremo sur de la constelación de Erídano, la novena del cielo. Desde la península ibérica queda por debajo del horizonte.","info":"Estrella caliente de tipo B6, a aprox. 140 años luz. Gira tan deprisa que está muy achatada, con un diámetro ecuatorial bastante mayor que el polar: una de las estrellas menos esféricas conocidas.","myth":"Del árabe «Akhir an-Nahr», «el final del río». Erídano es el río celeste que se asocia con la caída de Faetón en la mitología griega, y Achernar señala su desembocadura austral."},"en":{"desc":"A bright blue-white star at the southern end of the constellation Eridanus, the ninth brightest in the sky. It lies below the horizon as seen from the Iberian Peninsula.","info":"A hot B6-type star about 140 light-years away. It spins so fast that it is strongly flattened, with an equatorial diameter much larger than its polar one: one of the least spherical stars known.","myth":"From the Arabic 'Akhir an-Nahr', 'the end of the river'. Eridanus is the celestial river associated with Phaethon's fall in Greek mythology, and Achernar marks its southern mouth."}},"hadar":{"es":{"desc":"Beta Centauri, una estrella azul-blanca muy brillante en el sur del cielo, una de las dos «guardas» de la Cruz del Sur. Brilla junto a Rigil Kent, a pocos grados de ella.","info":"Gigante azul de tipo B1 III, a aprox. 390 años luz, decenas de miles de veces más luminosa que el Sol. Es un sistema múltiple: la componente principal es a su vez binaria y hay una tercera estrella más débil.","myth":"Su nombre procede del árabe. También se la llama Agena. Con Rigil Kent forma el par de «Guardas» que señalan la Cruz del Sur, y marca una de las patas delanteras del centauro."},"en":{"desc":"Beta Centauri, a very bright blue-white star in the southern sky and one of the two 'Pointers' to the Southern Cross. It shines a few degrees from Rigil Kent.","info":"A B1 III blue giant about 390 light-years away, tens of thousands of times more luminous than the Sun. It is a multiple system: the main component is itself a binary, and there is a fainter third star.","myth":"Its name comes from Arabic. It is also called Agena. With Rigil Kent it forms the pair of 'Pointers' that lead to the Southern Cross, and it marks one of the centaur's forelegs."}},"altair":{"es":{"desc":"Estrella blanca brillante, la más meridional del Triángulo de Verano, flanqueada por dos estrellas más débiles en la constelación del Águila. Alta en el cielo de las noches de verano.","info":"Estrella de tipo A7V, a 17 años luz, con aprox. 11 veces la luminosidad del Sol. Rota en unas 9 horas, por lo que está notablemente achatada.","myth":"Del árabe «al-nasr al-ta'ir», «el águila voladora». En la constelación del Águila, el ave que en la mitología griega llevaba los rayos de Zeus. En China es el boyero Niulang, enamorado de la tejedora Vega."},"en":{"desc":"A bright white star, the southernmost of the Summer Triangle, flanked by two fainter stars in the constellation Aquila. It stands high in the sky on summer nights.","info":"An A7V star 17 light-years away, with about 11 times the Sun's luminosity. It rotates in roughly 9 hours, so it is noticeably flattened.","myth":"From the Arabic 'al-nasr al-ta'ir', 'the flying eagle'. It lies in Aquila, the bird that carried Zeus's thunderbolts in Greek mythology. In China it is the cowherd Niulang, in love with the weaver girl Vega."}},"acrux":{"es":{"desc":"Alfa Crucis, la estrella más meridional de la Cruz del Sur y la más brillante de la constelación; blanco-azulada. Prolongando el eje largo de la cruz se llega hacia el polo sur celeste.","info":"Sistema múltiple de estrellas muy calientes y azuladas, a aprox. 320 años luz. Con un telescopio pequeño se separan en dos componentes brillantes de tipo B, y existen otras más débiles asociadas.","myth":"El nombre es una contracción moderna de «Alfa Crucis». La Cruz del Sur fue guía de navegantes del hemisferio sur y aparece en las banderas de Australia, Nueva Zelanda, Brasil y otros países."},"en":{"desc":"Alpha Crucis, the southernmost star of the Southern Cross and its brightest, a blue-white. Extending the cross's long axis leads toward the south celestial pole.","info":"A multiple system of very hot, bluish stars about 320 light-years away. A small telescope splits it into two bright B-type components, and there are fainter associated stars.","myth":"The name is a modern contraction of 'Alpha Crucis'. The Southern Cross has long guided southern-hemisphere navigators and appears on the flags of Australia, New Zealand, Brazil and other countries."}},"aldebaran":{"es":{"desc":"El ojo rojizo del Toro: una estrella naranja muy brillante, fácil de hallar prolongando hacia el oeste el cinturón de Orión. Parece la más brillante de las Híades, aunque no pertenece al cúmulo.","info":"Gigante naranja de tipo K5 III, a aprox. 65 años luz, con unas 44 veces el diámetro del Sol y varios cientos de veces su luminosidad. Es una estrella situada por delante del cúmulo de las Híades, sin pertenecer a él.","myth":"Del árabe «al-dabaran», «el seguidor», porque sigue a las Pléyades en su recorrido nocturno. Es el ojo del Toro, la constelación que la mitología griega vincula con Zeus transformado en toro."},"en":{"desc":"The reddish eye of the Bull: a very bright orange star, easy to find by extending Orion's Belt toward the west. It looks like the brightest member of the Hyades, though it does not belong to the cluster.","info":"A K5 III orange giant about 65 light-years away, roughly 44 times the Sun's diameter and several hundred times as luminous. It lies in front of the Hyades cluster without being part of it.","myth":"From the Arabic 'al-dabaran', 'the follower', because it follows the Pleiades across the night sky. It is the eye of the Bull, the constellation that Greek mythology links with Zeus transformed into a bull."}},"antares":{"es":{"desc":"Supergigante roja de intenso color rojizo, el corazón del Escorpión. Se ve bajo en el sur en las noches de verano desde España y destaca por su color.","info":"Supergigante roja de tipo M1,5 Ib, a aprox. 550 años luz, con un radio de varios cientos de veces el del Sol. Tiene una compañera azulada débil, difícil de ver por el resplandor de la principal.","myth":"Del griego «Antares», «rival de Ares» (Marte), por su parecido de color con el planeta rojo. Marca el corazón de Escorpio, el escorpión que en el mito mató a Orión; por eso ambas constelaciones no coinciden en el cielo."},"en":{"desc":"A red supergiant of intense reddish colour, the heart of the Scorpion. It hangs low in the south on summer nights from Spain and stands out for its colour.","info":"An M1.5 Ib red supergiant about 550 light-years away, with a radius several hundred times the Sun's. It has a faint bluish companion that is hard to see in the glare of the primary.","myth":"From the Greek 'Antares', 'rival of Ares' (Mars), for its resemblance in colour to the red planet. It marks the heart of Scorpius, the scorpion that in myth killed Orion, which is why the two constellations are never in the sky together."}},"spica":{"es":{"desc":"La estrella más brillante de Virgo, de color blanco-azulado. Se encuentra siguiendo la curva del mango de la Osa Mayor pasando por Arturo (arco a Arturo, «sigue hasta Spica»).","info":"Sistema binario muy cerrado de dos estrellas azules calientes, a aprox. 250 años luz, que giran en pocos días y se deforman mutuamente. La principal es unas 12 000 veces más luminosa que el Sol.","myth":"Del latín «spica», «espiga de trigo», la que sostiene en la mano Virgo, a menudo asociada con Deméter y la cosecha. Su posición sirvió a Hiparco para descubrir la precesión de los equinoccios."},"en":{"desc":"The brightest star of Virgo, bluish-white. Find it by following the curve of the Big Dipper's handle through Arcturus ('arc to Arcturus, then speed on to Spica').","info":"A very tight binary of two hot blue stars about 250 light-years away, orbiting in a few days and distorting each other. The primary is about 12,000 times as luminous as the Sun.","myth":"From the Latin 'spica', 'ear of wheat', held in Virgo's hand and often linked with Demeter and the harvest. Its position helped Hipparchus discover the precession of the equinoxes."}},"pollux":{"es":{"desc":"Estrella naranja brillante, la más luminosa de Géminis. Junto a Castor forma la pareja de «cabezas» de los gemelos, con Pollux algo más brillante y de color más cálido.","info":"Gigante naranja de tipo K0 III, a 34 años luz, con unas 9 veces el diámetro del Sol. Es la estrella gigante más cercana al Sol y tiene un planeta confirmado, con masa de unas 2 veces la de Júpiter.","myth":"Forma latina del griego Polideuces. Los Dioscuros, Cástor y Pólux, eran hermanos gemelos: según el mito, Pólux era inmortal, hijo de Zeus, y Cástor mortal. Compartieron la inmortalidad cuando Zeus los colocó en el cielo."},"en":{"desc":"A bright orange star, the most luminous in Gemini. With Castor it forms the pair of 'heads' of the twins, Pollux being a little brighter and warmer in colour.","info":"A K0 III orange giant 34 light-years away, about 9 times the Sun's diameter. It is the nearest giant star to the Sun and has a confirmed planet with a mass around twice that of Jupiter.","myth":"The Latin form of the Greek Polydeuces. The Dioscuri, Castor and Pollux, were twin brothers: in myth Pollux was immortal, a son of Zeus, while Castor was mortal. They shared immortality when Zeus placed them in the sky."}},"fomalhaut":{"es":{"desc":"Estrella blanca brillante y solitaria, baja en el sur en las noches de otoño desde España, sin otras estrellas brillantes cerca. Es la principal del Pez Austral.","info":"Estrella blanca de tipo A3V, a 25 años luz, rodeada por un amplio anillo de polvo y restos de planetesimales. Es una estrella joven, de unos cientos de millones de años.","myth":"Del árabe «fam al-hut», «la boca del pez» (o de la ballena), por su posición en el Pez Austral. Se le llama a veces «la solitaria del otoño» por quedar sola en una zona sin estrellas brillantes."},"en":{"desc":"A bright, lonely white star, low in the south on autumn nights from Spain with no other bright stars nearby. It is the main star of the Southern Fish.","info":"An A3V white star 25 light-years away, surrounded by a broad ring of dust and planetesimal debris. It is a young star, a few hundred million years old.","myth":"From the Arabic 'fam al-hut', 'the mouth of the fish' (or whale), for its position in the Southern Fish. It is sometimes called the 'Lonely One of autumn' because it stands alone in a region with no bright stars."}},"deneb":{"es":{"desc":"Estrella blanca muy brillante en la cola del Cisne, el vértice norte del Triángulo de Verano. Se ve alta en las noches de verano y brilla pese a estar muy lejos.","info":"Supergigante blanca de tipo A2 Ia, entre las estrellas más luminosas visibles a simple vista: decenas de miles de veces el Sol. Está a más de mil años luz; las estimaciones varían, aprox. 2 600.","myth":"Del árabe «dhanab», «cola»: es la cola de la gallina o del Cisne. La constelación del Cisne evoca a Zeus transformado en cisne, o a Orfeo convertido en cisne tras su muerte según otras versiones."},"en":{"desc":"A very bright white star at the tail of the Swan, the northern corner of the Summer Triangle. It rides high on summer nights and shines brightly despite being very far away.","info":"An A2 Ia white supergiant, among the most luminous stars visible to the naked eye: tens of thousands of times the Sun. It lies more than a thousand light-years away; estimates vary, about 2,600.","myth":"From the Arabic 'dhanab', 'tail': it is the tail of the hen, or Swan. The constellation Cygnus recalls Zeus transformed into a swan, or in other versions Orpheus turned into a swan after his death."}},"mimosa":{"es":{"desc":"Beta Crucis, la estrella azul del brazo izquierdo de la Cruz del Sur, muy brillante y de un blanco-azulado intenso. Invisible desde España peninsular.","info":"Gigante azul de tipo B0.5 III, a aprox. 300 años luz, miles de veces más luminosa que el Sol. Es una variable de tipo Beta Cephei, con pulsaciones leves.","myth":"El nombre Mimosa es de uso moderno y su origen es incierto. También se la conoce como Becrux. La Cruz del Sur fue en la antigüedad clásica parte de Centauro, y su estrella Mimosa marca el brazo izquierdo de la cruz."},"en":{"desc":"Beta Crucis, the blue star at the left arm of the Southern Cross, very bright and an intense blue-white. It is invisible from mainland Spain.","info":"A B0.5 III blue giant about 300 light-years away, thousands of times more luminous than the Sun. It is a Beta Cephei variable with slight pulsations.","myth":"The name Mimosa is modern and its origin is uncertain. It is also known as Becrux. In classical antiquity the Southern Cross was part of Centaurus, and Mimosa marks the left arm of the cross."}},"regulus":{"es":{"desc":"Estrella azul-blanca brillante, el corazón de Leo, en el extremo inferior de la «hoz» que dibuja la cabeza del león. Se ve en las noches de primavera, alta hacia el sur.","info":"Sistema múltiple de cuatro estrellas a aprox. 79 años luz; la principal, de tipo B8 IV, gira en menos de 16 horas y está achatada. Se halla muy cerca de la eclíptica, por lo que la Luna y los planetas la ocultan o pasan junto a ella.","myth":"Del latín «regulus», «reyezuelo» o «pequeño rey». Es Alfa Leonis, el corazón del león de Nemea, la fiera que según el mito Heracles estranguló como el primero de sus doce trabajos."},"en":{"desc":"A bright blue-white star, the heart of Leo, at the bottom of the 'Sickle' that outlines the lion's head. It is seen high in the south on spring evenings.","info":"A four-star system about 79 light-years away; the main star, of type B8 IV, rotates in under 16 hours and is flattened. It lies very close to the ecliptic, so the Moon and planets pass near it or occult it.","myth":"From the Latin 'regulus', 'little king'. It is Alpha Leonis, the heart of the Nemean lion, the beast that in myth Heracles strangled as the first of his twelve labours."}},"adhara":{"es":{"desc":"Épsilon del Can Mayor, una estrella blanco-azulada brillante al sur de Sirius, en la zona de las patas del can. Desde España queda baja en el horizonte sur, en invierno.","info":"Gigante azul de tipo B2 II, a aprox. 430 años luz, miles de veces más luminosa que el Sol. Es una de las fuentes de radiación ultravioleta extrema más intensas del cielo. Tiene una compañera más débil.","myth":"Del árabe «al-adhara», «las vírgenes». Forma parte de la constelación del Can Mayor, el perro de caza del cazador Orión, junto con Sirius, Wezen y Mirzam."},"en":{"desc":"Epsilon Canis Majoris, a bright blue-white star south of Sirius, in the dog's hind legs. From Spain it sits low on the southern horizon in winter.","info":"A B2 II blue giant about 430 light-years away, thousands of times more luminous than the Sun. It is one of the strongest sources of extreme ultraviolet radiation in the sky. It has a fainter companion.","myth":"From the Arabic 'al-adhara', 'the virgins'. It belongs to Canis Major, the hunting dog of Orion the hunter, along with Sirius, Wezen and Mirzam."}},"castor":{"es":{"desc":"Estrella blanca brillante, la compañera de Pollux en los gemelos de Géminis, ligeramente menos luminosa. A simple vista parece una sola estrella, pero con telescopio se desdobla.","info":"Sistema sextuple a aprox. 51 años luz: tres pares de estrellas. Con un telescopio pequeño se resuelven dos componentes blanco-azuladas brillantes, y cada una es a su vez binaria, además de una pareja de enanas rojas más lejana.","myth":"Cástor, el gemelo mortal, domador de caballos, hermano de Pólux. Los Dioscuros fueron protectores de los navegantes. Cuando Cástor murió, Pólux compartió con él la inmortalidad y Zeus los colocó juntos en el cielo."},"en":{"desc":"A bright white star, Pollux's partner among the twins of Gemini and slightly less luminous. To the naked eye it looks like a single star, but a telescope splits it.","info":"A sextuple system about 51 light-years away: three pairs of stars. A small telescope resolves two bright bluish-white components, each itself a binary, plus a more distant pair of red dwarfs.","myth":"Castor, the mortal twin and horse tamer, brother of Pollux. The Dioscuri were protectors of sailors. When Castor died, Pollux shared his immortality and Zeus placed them together in the sky."}},"gacrux":{"es":{"desc":"Gamma Crucis, la estrella roja en el extremo superior de la Cruz del Sur, que contrasta con las azules del resto de la cruz. Invisible desde España peninsular.","info":"Gigante roja de tipo M3.5 III, a aprox. 90 años luz, con un radio de unas 80 veces el del Sol. Tiene una compañera débil visible con telescopio pequeño.","myth":"El nombre es una contracción moderna de «Gamma Crucis». La Cruz del Sur es una constelación pequeña pero muy conocida; Gacrux señala el extremo superior de su eje largo, que apunta hacia el polo sur celeste."},"en":{"desc":"Gamma Crucis, the red star at the top of the Southern Cross, contrasting with the blue stars of the rest of the cross. It is invisible from mainland Spain.","info":"An M3.5 III red giant about 90 light-years away, with a radius about 80 times the Sun's. It has a faint companion visible in a small telescope.","myth":"The name is a modern contraction of 'Gamma Crucis'. The Southern Cross is a small but well-known constellation; Gacrux marks the top end of its long axis, which points toward the south celestial pole."}},"shaula":{"es":{"desc":"Lambda Scorpii, la estrella del aguijón del Escorpión, blanco-azulada y brillante. Es la segunda más brillante de su constelación y forma pareja con la vecina Lesath.","info":"Sistema múltiple de estrellas azules muy calientes, a aprox. 570 años luz, con una luminosidad de miles de veces la del Sol. La componente principal es a su vez binaria.","myth":"Del árabe «al-shaulah», «la (cola) levantada», el aguijón del Escorpión que en el mito mató a Orión. Shaula y su vecina Lesath marcan la punta de la cola de la constelación."},"en":{"desc":"Lambda Scorpii, the star of the Scorpion's stinger, bright and blue-white. It is the second brightest in its constellation and forms a pair with neighbouring Lesath.","info":"A multiple system of very hot blue stars about 570 light-years away, thousands of times the Sun's luminosity. The main component is itself a binary.","myth":"From the Arabic 'al-shaulah', 'the raised (tail)', the stinger of the Scorpion that in myth killed Orion. Shaula and its neighbour Lesath mark the tip of the constellation's tail."}},"bellatrix":{"es":{"desc":"Estrella blanco-azulada en el hombro izquierdo de Orión, brillante pero algo más discreta que Rigel y Betelgeuse. Tercera más brillante de su constelación.","info":"Gigante azul de tipo B2 III, a aprox. 250 años luz, con unas 6 veces el radio del Sol y miles de veces su luminosidad. Es una estrella caliente y masiva.","myth":"Del latín «bellatrix», «guerrera» o «amazona». Marca el hombro izquierdo de Orión, el cazador gigante de la mitología griega. El nombre se difundió en la Edad Media a través de los catálogos latinos."},"en":{"desc":"A blue-white star on Orion's left shoulder, bright but a little more discreet than Rigel and Betelgeuse. It is the third brightest in its constellation.","info":"A B2 III blue giant about 250 light-years away, roughly 6 times the Sun's radius and thousands of times its luminosity. It is a hot, massive star.","myth":"From the Latin 'bellatrix', 'female warrior' or 'Amazon'. It marks the left shoulder of Orion, the giant hunter of Greek mythology. The name spread in the Middle Ages through Latin star catalogues."}},"elnath":{"es":{"desc":"Estrella blanco-azulada brillante en la punta del cuerno norte del Toro, cerca de los límites con Auriga. Se ve en invierno, alta en el cielo.","info":"Gigante de tipo B7 III, a aprox. 130 años luz, con unas 700 veces la luminosidad del Sol. Tiene una composición química peculiar rica en mercurio y manganeso.","myth":"Del árabe «an-nath», «la que embiste», por marcar la punta del cuerno del Toro. Antiguamente también se consideraba parte de Auriga, el cochero, bajo el nombre de Gamma Aurigae."},"en":{"desc":"A bright blue-white star at the tip of the Bull's northern horn, near the border with Auriga. It is seen high in the sky in winter.","info":"A B7 III giant about 130 light-years away, with roughly 700 times the Sun's luminosity. It has a peculiar chemical composition rich in mercury and manganese.","myth":"From the Arabic 'an-nath', 'the butting one', for marking the tip of the Bull's horn. It was formerly also counted as part of Auriga, the charioteer, under the name Gamma Aurigae."}},"miaplacidus":{"es":{"desc":"Beta Carinae, una estrella blanca brillante de la Quilla, la segunda más brillante de su constelación tras Canopus. Visible solo desde el hemisferio sur y latitudes tropicales.","info":"Estrella blanca de tipo A2, a aprox. 110 años luz, con unas 200 veces la luminosidad del Sol. Es la segunda estrella más brillante de la Quilla.","myth":"El nombre, de origen incierto, se interpreta a veces como mezcla del árabe «mā'» (agua) y el latín «placidus» (tranquilo): «aguas tranquilas». La Quilla formaba parte de la antigua Argo Navis, la nave de los argonautas."},"en":{"desc":"Beta Carinae, a bright white star in Carina and its second brightest after Canopus. It is visible only from the southern hemisphere and tropical latitudes.","info":"A white A2-type star about 110 light-years away, with roughly 200 times the Sun's luminosity. It is the second brightest star in Carina.","myth":"The name, of uncertain origin, is sometimes interpreted as a mix of Arabic 'ma'' (water) and Latin 'placidus' (calm): 'calm waters'. Carina was part of the ancient Argo Navis, the ship of the Argonauts."}},"alnilam":{"es":{"desc":"La estrella central del Cinturón de Orión, azul-blanca muy brillante. Es la más luminosa de las tres y apunta, con las otras dos, hacia Sirius y Aldebarán.","info":"Supergigante azul de tipo B0 Ia, a más de mil años luz, con cientos de miles de veces la luminosidad del Sol. Es una de las estrellas más luminosas que se ven a simple vista y pierde masa por un intenso viento estelar.","myth":"Del árabe «an-nitham», «la sarta de perlas», el collar o cinturón de Orión. En España el cinturón de Orión se conoce popularmente como las Tres Marías o los Tres Reyes Magos."},"en":{"desc":"The central star of Orion's Belt, very bright and blue-white. It is the most luminous of the three, and with the other two points toward Sirius and Aldebaran.","info":"A B0 Ia blue supergiant over a thousand light-years away, with hundreds of thousands of times the Sun's luminosity. It is one of the most luminous stars visible to the naked eye and loses mass through an intense stellar wind.","myth":"From the Arabic 'an-nitham', 'the string of pearls', Orion's necklace or belt. In Spain Orion's Belt is popularly known as the Three Marys or the Three Wise Men."}},"alnair":{"es":{"desc":"Alfa Gruis, la estrella azul-blanca más brillante de la Grulla, constelación del sur. Desde casi toda España es invisible; desde Canarias se ve muy baja en otoño.","info":"Estrella caliente de tipo B6 V, a aprox. 100 años luz, con unas 400 veces la luminosidad del Sol. Gira muy rápido, por lo que está achatada.","myth":"Del árabe «al-nayyir», «la brillante» (de la cola del pez). La Grulla es una constelación moderna, introducida en el siglo XVI por navegantes neerlandeses a partir de observaciones del cielo austral."},"en":{"desc":"Alpha Gruis, the brightest blue-white star of Grus, a southern constellation. It is invisible from almost all of Spain; from the Canary Islands it can be seen very low in autumn.","info":"A hot B6 V star about 100 light-years away, with roughly 400 times the Sun's luminosity. It spins very fast and is therefore flattened.","myth":"From the Arabic 'al-nayyir', 'the bright one' (of the fish's tail). Grus is a modern constellation, introduced in the 16th century by Dutch navigators from observations of the southern sky."}},"alnitak":{"es":{"desc":"La estrella más oriental del Cinturón de Orión, azul-blanca brillante. Está junto a la Nebulosa de la Llama y cerca de la Cabeza de Caballo.","info":"Supergigante azul de tipo O9.5 Ib, a aprox. 1 200 años luz, con unas 100 000 veces la luminosidad del Sol. Es un sistema múltiple con al menos tres componentes.","myth":"Del árabe «an-nitaq», «el cinto». Es la estrella que se halla en el extremo oriental del cinturón de Orión, el cazador gigante de la mitología griega. Las Tres Marías españolas son Alnitak, Alnilam y Mintaka."},"en":{"desc":"The easternmost star of Orion's Belt, bright and blue-white. It lies next to the Flame Nebula and near the Horsehead Nebula.","info":"An O9.5 Ib blue supergiant about 1,200 light-years away, roughly 100,000 times the Sun's luminosity. It is a multiple system with at least three components.","myth":"From the Arabic 'an-nitaq', 'the girdle'. It is the star at the eastern end of the belt of Orion, the giant hunter of Greek mythology. Spain's Three Marys are Alnitak, Alnilam and Mintaka."}},"alioth":{"es":{"desc":"Épsilon de la Osa Mayor, la estrella más brillante del Carro, la más próxima al cuerpo del carro. Es blanca y se ve todo el año desde España, ya que es circumpolar.","info":"Estrella blanca de tipo A1p, a aprox. 80 años luz, con unas 100 veces la luminosidad del Sol. Es una estrella peculiar con un fuerte campo magnético y una composición química inusual.","myth":"Su nombre es de origen árabe. Forma parte del Carro, el cuerpo de la Osa Mayor, que en el mito griego es la ninfa Calisto convertida en osa. Alioth, Mizar y Alkaid dibujan el mango del carro."},"en":{"desc":"Epsilon Ursae Majoris, the brightest star of the Big Dipper, the one closest to the bowl. It is white and visible all year from Spain because it is circumpolar.","info":"An A1p white star about 80 light-years away, with roughly 100 times the Sun's luminosity. It is a peculiar star with a strong magnetic field and an unusual chemical composition.","myth":"Its name is of Arabic origin. It is part of the Big Dipper, the body of the Great Bear, who in Greek myth is the nymph Callisto turned into a bear. Alioth, Mizar and Alkaid trace the handle."}},"dubhe":{"es":{"desc":"Alfa de la Osa Mayor, una estrella naranja-amarillenta en el borde del cuenco del Carro. Junto a Merak sirve de «guarda» para hallar la estrella Polar. Circumpolar en España.","info":"Gigante naranja de tipo K0 III, a aprox. 120 años luz, con unas 300 veces la luminosidad del Sol. Es un sistema binario con una compañera más débil.","myth":"Del árabe «thahr ad-dubb al-akbar», «el lomo del Oso Mayor». Dubhe y Merak son las «Guardas» o «Apuntadoras» que marcan el camino a la estrella Polar."},"en":{"desc":"Alpha Ursae Majoris, an orange-yellow star on the rim of the Big Dipper's bowl. With Merak it serves as a 'pointer' to find Polaris. It is circumpolar in Spain.","info":"A K0 III orange giant about 120 light-years away, with roughly 300 times the Sun's luminosity. It is a binary with a fainter companion.","myth":"From the Arabic 'thahr ad-dubb al-akbar', 'the back of the Greater Bear'. Dubhe and Merak are the 'Pointers' that mark the way to Polaris."}},"mirfak":{"es":{"desc":"Alfa Persei, una estrella blanco-amarillenta brillante en medio de un cúmulo de estrellas jóvenes, visible muy bien con prismáticos. Se ve alta en otoño e invierno.","info":"Supergigante de tipo F5 Ib, a aprox. 500 años luz, con unas 5 000 veces la luminosidad del Sol. Es la estrella principal del cúmulo de Alfa Persei, un grupo de estrellas jóvenes visible con prismáticos.","myth":"Del árabe «mirfaq», «el codo»: marca el brazo de Perseo, el héroe que en el mito griego decapitó a Medusa y rescató a Andrómeda. Es la estrella más brillante de la constelación."},"en":{"desc":"Alpha Persei, a bright yellowish-white star amid a cluster of young stars, best seen with binoculars. It rides high in autumn and winter.","info":"An F5 Ib supergiant about 500 light-years away, with roughly 5,000 times the Sun's luminosity. It is the leading star of the Alpha Persei cluster, a group of young stars visible in binoculars.","myth":"From the Arabic 'mirfaq', 'the elbow': it marks the arm of Perseus, the hero who in Greek myth beheaded Medusa and rescued Andromeda. It is the brightest star in the constellation."}},"wezen":{"es":{"desc":"Delta del Can Mayor, una estrella blanco-amarillenta brillante en el cuerpo del can, al sur de Sirius. Desde España queda baja en el horizonte sur.","info":"Supergigante amarillo-blanca de tipo F8 Ia, a aprox. 1 600 años luz, con decenas de miles de veces la luminosidad del Sol. Es una estrella masiva y evolucionada, destinada a acabar como supernova.","myth":"Del árabe «al-wazn», «el peso», probablemente por su posición en la constelación. Forma parte del Can Mayor, el perro de caza de Orión, junto con Sirius, Adhara y Mirzam."},"en":{"desc":"Delta Canis Majoris, a bright yellowish-white star in the dog's body, south of Sirius. From Spain it sits low on the southern horizon.","info":"An F8 Ia yellow-white supergiant about 1,600 light-years away, with tens of thousands of times the Sun's luminosity. It is a massive, evolved star destined to end as a supernova.","myth":"From the Arabic 'al-wazn', 'the weight', probably for its position in the constellation. It belongs to Canis Major, the hunting dog of Orion, along with Sirius, Adhara and Mirzam."}},"sargas":{"es":{"desc":"Theta Scorpii, una estrella blanco-amarillenta brillante en la cola del Escorpión, cerca del aguijón. Muy baja o invisible desde la península ibérica.","info":"Gigante luminosa de tipo F0 II, a aprox. 300 años luz. Es una de las estrellas más brillantes de la cola del Escorpión, tras Shaula y Lesath.","myth":"Su nombre es de origen incierto, posiblemente mesopotámico. Marca la parte inferior de la cola del Escorpión, el animal que en la mitología griega mató a Orión."},"en":{"desc":"Theta Scorpii, a bright yellowish-white star in the Scorpion's tail, near the stinger. It is very low or invisible from the Iberian Peninsula.","info":"A luminous F0 II giant about 300 light-years away. It is among the brightest stars of the Scorpion's tail, after Shaula and Lesath.","myth":"Its name is of uncertain origin, possibly Mesopotamian. It marks the lower part of the tail of the Scorpion, the animal that in Greek mythology killed Orion."}},"kaus-australis":{"es":{"desc":"Épsilon Sagittarii, la estrella más brillante de Sagitario, blanco-azulada, en la base del asterismo de la Tetera. Baja en el horizonte sur de España en verano.","info":"Estrella de tipo B9.5 III, a aprox. 140 años luz, con unas 375 veces la luminosidad del Sol. Es la más brillante de Sagitario.","myth":"Del árabe «qaws» (arco) y del latín «australis» (meridional): «la parte sur del arco». Sagitario es el arquero, un centauro de la mitología griega, quizá Quirón, y Kaus Australis marca el arco."},"en":{"desc":"Epsilon Sagittarii, the brightest star in Sagittarius, blue-white, at the base of the Teapot asterism. It sits low on Spain's southern horizon in summer.","info":"A B9.5 III star about 140 light-years away, with roughly 375 times the Sun's luminosity. It is the brightest star in Sagittarius.","myth":"From the Arabic 'qaws' (bow) and the Latin 'australis' (southern): 'the southern part of the bow'. Sagittarius is the archer, a centaur of Greek mythology, perhaps Chiron, and Kaus Australis marks the bow."}},"avior":{"es":{"desc":"Épsilon Carinae, una estrella naranja-amarillenta brillante de la Quilla, parte de la «Falsa Cruz». Visible solo desde el hemisferio sur y latitudes tropicales.","info":"Sistema binario formado por una gigante naranja de tipo K3 y una estrella azul más caliente, a aprox. 600 años luz. Su brillo conjunto es de miles de veces el del Sol.","myth":"Avior es un nombre moderno, no tradicional: se acuñó en el siglo XX para la navegación aérea. Forma la «Falsa Cruz» con Aspidiske y dos estrellas de la Vela, asterismo que a veces se confunde con la Cruz del Sur."},"en":{"desc":"Epsilon Carinae, a bright orange-yellow star in Carina and part of the 'False Cross'. It is visible only from the southern hemisphere and tropical latitudes.","info":"A binary system made up of a K3 orange giant and a hotter blue star, about 600 light-years away. Their combined brightness is thousands of times the Sun's.","myth":"Avior is a modern name, not a traditional one: it was coined in the 20th century for air navigation. It forms the 'False Cross' with Aspidiske and two stars of Vela, an asterism sometimes mistaken for the real Southern Cross."}},"alkaid":{"es":{"desc":"Eta de la Osa Mayor, la estrella del extremo del mango del Carro, azul-blanca. Desde el sur de España no es circumpolar.","info":"Estrella de tipo B3 V, a aprox. 100 años luz, con cientos de veces la luminosidad del Sol. Junto con Dubhe, no pertenece al grupo móvil de la Osa Mayor, a diferencia de las otras cinco estrellas del Carro.","myth":"Del árabe «qa'id banat na'ash», «el jefe de las plañideras»: en la imagen árabe, el cuenco era un féretro (na'sh) y las estrellas del mango, las plañideras que lo siguen."},"en":{"desc":"Eta Ursae Majoris, the star at the tip of the Big Dipper's handle, blue-white. It is not circumpolar from southern Spain.","info":"A B3 V star about 100 light-years away, with hundreds of times the Sun's luminosity. Together with Dubhe, it is not part of the Ursa Major moving group, unlike the other five Dipper stars.","myth":"From the Arabic 'qa'id banat na'ash', 'the chief of the mourners': in the Arabic image the bowl was a bier (na'sh) and the handle stars were the mourners following it."}},"menkalinan":{"es":{"desc":"Beta Aurigae, una estrella blanca brillante en el hombro derecho del Cochero, cerca de Capella. Se ve alta en invierno.","info":"Binaria eclipsante formada por dos estrellas blancas de tipo A casi idénticas, a aprox. 80 años luz, que se eclipsan mutuamente cada aprox. 4 días, por lo que su brillo oscila ligeramente.","myth":"Del árabe «mankib dhi al-inan», «el hombro del que sujeta las riendas». Marca el hombro del Auriga, el cochero, constelación asociada a Erictonio, inventor del carro en algunas versiones del mito."},"en":{"desc":"Beta Aurigae, a bright white star on the Charioteer's right shoulder, near Capella. It rides high in winter.","info":"An eclipsing binary of two nearly identical white A-type stars, about 80 light-years away, which eclipse each other every roughly 4 days, so its brightness varies slightly.","myth":"From the Arabic 'mankib dhi al-inan', 'the shoulder of the rein-holder'. It marks the shoulder of Auriga, the charioteer, a constellation linked with Erichthonius, inventor of the chariot in some versions of the myth."}},"atria":{"es":{"desc":"Alfa Trianguli Australis, la estrella naranja brillante del Triángulo Austral, una constelación pequeña del hemisferio sur. Invisible desde España.","info":"Gigante naranja de tipo K2 Ib-IIa, a aprox. 415 años luz, con miles de veces la luminosidad del Sol. Es la estrella más brillante del Triángulo Austral.","myth":"Atria es una contracción moderna de «Alfa Trianguli Australis», nombre adoptado en el siglo XX. El Triángulo Austral es una constelación pequeña y distintiva descrita por navegantes del siglo XVI."},"en":{"desc":"Alpha Trianguli Australis, the bright orange star of Triangulum Australe, a small southern-hemisphere constellation. It is invisible from Spain.","info":"A K2 Ib-IIa orange giant about 415 light-years away, with thousands of times the Sun's luminosity. It is the brightest star in Triangulum Australe.","myth":"Atria is a modern contraction of 'Alpha Trianguli Australis', a name adopted in the 20th century. Triangulum Australe is a small, distinctive constellation described by 16th-century navigators."}},"alhena":{"es":{"desc":"Gamma Geminorum, una estrella blanca brillante a los pies de los gemelos, cerca de la Vía Láctea. Se ve en invierno hacia el este de Orión.","info":"Estrella de tipo A0 IV, a aprox. 105 años luz, con unas 100 veces la luminosidad del Sol. Es una binaria espectroscópica con una compañera más débil.","myth":"Del árabe «al-han'ah», la «marca» de un camello. Marca el pie de Pólux, uno de los gemelos Dioscuros hijos de Zeus, en la constelación de Géminis."},"en":{"desc":"Gamma Geminorum, a bright white star at the feet of the twins, near the Milky Way. It is seen in winter, east of Orion.","info":"An A0 IV star about 105 light-years away, with roughly 100 times the Sun's luminosity. It is a spectroscopic binary with a fainter companion.","myth":"From the Arabic 'al-han'ah', the 'brand mark' of a camel. It marks the foot of Pollux, one of the Dioscuri twins, sons of Zeus, in the constellation Gemini."}},"peacock":{"es":{"desc":"Alfa Pavonis, una estrella azul-blanca brillante, la más brillante del Pavo, una constelación del sur. Invisible desde España.","info":"Estrella caliente de tipo B2 IV, a aprox. 180 años luz, miles de veces más luminosa que el Sol. Es una binaria espectroscópica de dos estrellas muy cercanas entre sí.","myth":"Peacock (en inglés, «pavo real») es un nombre moderno, de siglo XX, que describe la constelación. El Pavo es una de las constelaciones introducidas a finales del siglo XVI por navegantes neerlandeses."},"en":{"desc":"Alpha Pavonis, a bright blue-white star, the brightest in Pavo, a southern constellation. It is invisible from Spain.","info":"A hot B2 IV star about 180 light-years away, thousands of times more luminous than the Sun. It is a spectroscopic binary of two stars very close together.","myth":"Peacock is a modern 20th-century name that simply describes the constellation. Pavo is one of the constellations introduced in the late 16th century by Dutch navigators."}},"mirzam":{"es":{"desc":"Beta del Can Mayor, una estrella azul-blanca brillante que sale justo antes que Sirius. Visible en invierno bajo en el horizonte sur de España.","info":"Gigante azul de tipo B1 II-III, a aprox. 500 años luz, con decenas de miles de veces la luminosidad del Sol. Es una variable de tipo Beta Cephei, de pulsaciones pequeñas.","myth":"Del árabe «al-murzim», «el anunciador»: sale poco antes de Sirius y la «anuncia». Forma parte del Can Mayor, el perro de caza de Orión en la mitología griega."},"en":{"desc":"Beta Canis Majoris, a bright blue-white star that rises just before Sirius. It is visible low on Spain's southern horizon in winter.","info":"A B1 II-III blue giant about 500 light-years away, with tens of thousands of times the Sun's luminosity. It is a Beta Cephei variable with small pulsations.","myth":"From the Arabic 'al-murzim', 'the announcer': it rises just before Sirius and 'announces' it. It belongs to Canis Major, the hunting dog of Orion in Greek mythology."}},"alphard":{"es":{"desc":"Alfa Hydrae, una estrella naranja aislada en un rincón del cielo sin estrellas brillantes; destaca por ello. Es el «corazón de la Hidra», la constelación más extensa. Se ve en primavera al sur.","info":"Gigante naranja de tipo K3 II-III, a aprox. 180 años luz, con unas 400 veces la luminosidad del Sol y un radio de unas 50 veces el solar.","myth":"Del árabe «al-fard al-shuja'», «el solitario de la serpiente». Es el corazón de la Hidra, la serpiente de muchas cabezas que mató Heracles en el segundo de sus doce trabajos."},"en":{"desc":"Alpha Hydrae, an isolated orange star in a corner of the sky with no other bright stars, which makes it stand out. It is the 'heart of Hydra', the largest constellation. It is seen low in the south in spring.","info":"A K3 II-III orange giant about 180 light-years away, with roughly 400 times the Sun's luminosity and a radius about 50 times the Sun's.","myth":"From the Arabic 'al-fard al-shuja'', 'the solitary one of the serpent'. It is the heart of Hydra, the many-headed serpent that Heracles slew as the second of his twelve labours."}},"polaris":{"es":{"desc":"La estrella Polar: una estrella amarillenta de brillo moderado que apenas se mueve en el cielo porque está casi sobre el polo norte celeste. Se halla prolongando la línea de las Guardas del Carro (Dubhe-Merak).","info":"Supergigante amarillenta de tipo F7 Ib, variable cefeida de pequeña amplitud, a aprox. 430 años luz, con aprox. 2 000 veces la luminosidad del Sol. Es un sistema triple y está a menos de 1° del polo norte celeste.","myth":"Su nombre viene del latín «stella polaris». Sirve de guía para localizar el norte, pero el eje terrestre se desplaza por precesión: no siempre ha sido la estrella polar ni lo será en el futuro. Es la cola de la Osa Menor."},"en":{"desc":"The North Star: a yellowish star of moderate brightness that barely moves in the sky because it sits almost on the north celestial pole. Find it by extending the line of the Big Dipper's Pointers (Dubhe-Merak).","info":"A yellowish F7 Ib supergiant, a low-amplitude Cepheid variable about 430 light-years away, with about 2,000 times the Sun's luminosity. It is a triple system and lies less than 1° from the north celestial pole.","myth":"Its name comes from the Latin 'stella polaris'. It is a guide for finding north, but Earth's axis shifts through precession: it has not always been the pole star and will not be in the future. It is the tail tip of the Little Bear."}},"hamal":{"es":{"desc":"Alfa Arietis, una estrella naranja moderadamente brillante, la más luminosa de Aries, una constelación débil. Se ve en otoño y principios de invierno, alta en el cielo hacia el sur.","info":"Gigante naranja de tipo K2 III, a aprox. 66 años luz, con unas 90 veces la luminosidad del Sol y unas 15 veces su diámetro. Tiene un planeta candidato.","myth":"Del árabe «ra's al-hamal», «la cabeza del carnero». Aries es el carnero del vellocino de oro de la mitología griega, que persiguieron Jasón y los argonautas."},"en":{"desc":"Alpha Arietis, a moderately bright orange star, the most luminous in Aries, a faint constellation. It is seen in autumn and early winter, high in the south.","info":"A K2 III orange giant about 66 light-years away, with roughly 90 times the Sun's luminosity and about 15 times its diameter. It has a candidate planet.","myth":"From the Arabic 'ra's al-hamal', 'the head of the ram'. Aries is the ram with the Golden Fleece of Greek mythology, which Jason and the Argonauts sought."}},"algieba":{"es":{"desc":"Gamma Leonis, una estrella naranja-dorada en la «hoz» del León, que con telescopio se desdobla en una hermosa pareja de estrellas amarillentas. Se ve en primavera, alta al sur.","info":"Binaria formada por dos gigantes naranja-amarillas, a aprox. 130 años luz, con un periodo orbital de aprox. 500 años. Es una de las dobles más bonitas del cielo, accesible a telescopios pequeños.","myth":"Del árabe «al-jabhah», «la frente (del león)». Forma parte de la «hoz», el grupo de estrellas que dibuja la cabeza y la melena de Leo, el león de Nemea muerto por Heracles."},"en":{"desc":"Gamma Leonis, an orange-golden star in the 'Sickle' of Leo, which a telescope splits into a lovely pair of yellowish stars. It is seen high in the south in spring.","info":"A binary of two orange-yellow giants about 130 light-years away, with an orbital period of about 500 years. It is one of the finest double stars in the sky, within reach of small telescopes.","myth":"From the Arabic 'al-jabhah', 'the forehead (of the lion)'. It is part of the 'Sickle', the group of stars outlining the head and mane of Leo, the Nemean lion slain by Heracles."}},"diphda":{"es":{"desc":"Beta Ceti, una estrella naranja brillante, la más brillante de la Ballena, aislada en una zona del cielo austral otoñal con pocas estrellas. También se llama Deneb Kaitos.","info":"Gigante naranja de tipo K0 III, a aprox. 100 años luz, con unas 150 veces la luminosidad del Sol. Es una estrella que ha agotado el hidrógeno de su núcleo y ahora fusiona helio.","myth":"Del árabe «ad-difda' ath-thani», «la segunda rana». Cetus es el monstruo marino que, en el mito griego, enviaba Poseidón contra Andrómeda y fue vencido por Perseo."},"en":{"desc":"Beta Ceti, a bright orange star, the brightest in Cetus, isolated in a sparse area of the autumn southern sky. It is also called Deneb Kaitos.","info":"A K0 III orange giant about 100 light-years away, with roughly 150 times the Sun's luminosity. It has exhausted the hydrogen in its core and now fuses helium.","myth":"From the Arabic 'ad-difda' ath-thani', 'the second frog'. Cetus is the sea monster that in Greek myth Poseidon sent against Andromeda and that Perseus defeated."}},"mizar":{"es":{"desc":"Zeta de la Osa Mayor, la estrella blanca del medio del mango del Carro, con la débil Alcor a su lado. Es una prueba clásica de vista a simple vista.","info":"Sistema sextuple a aprox. 83 años luz. Con un telescopio pequeño se ve doble (Mizar A y B), y cada componente es a su vez binaria espectroscópica. Fue la primera doble descubierta con telescopio, en el siglo XVII.","myth":"Del árabe «mi'zar», «cinturón» o «faja». Mizar y Alcor eran una prueba de agudeza visual en la antigüedad. Forma parte del Carro, la Osa Mayor de la mitología griega, que se asocia con Calisto."},"en":{"desc":"Zeta Ursae Majoris, the white star in the middle of the Big Dipper's handle, with faint Alcor beside it. It is a classic naked-eye test.","info":"A sextuple system about 83 light-years away. A small telescope shows it double (Mizar A and B), and each component is itself a spectroscopic binary. It was the first double star discovered with a telescope, in the 17th century.","myth":"From the Arabic 'mi'zar', 'girdle' or 'sash'. Mizar and Alcor were a test of eyesight in antiquity. It is part of the Big Dipper, the Great Bear of Greek mythology, associated with Callisto."}},"nunki":{"es":{"desc":"Sigma Sagittarii, una estrella azul-blanca brillante en el asterismo de la Tetera de Sagitario, hacia el centro de la Vía Láctea. Baja en el sur en verano desde España.","info":"Estrella caliente de tipo B2.5 V, a aprox. 230 años luz, con cientos de veces la luminosidad del Sol. Es una estrella de la secuencia principal, relativamente joven.","myth":"Su nombre procede, según algunas fuentes, de una antigua designación mesopotámica de la estrella; el origen exacto es incierto. Sagitario es el arquero centauro de la mitología griega, y Nunki forma parte de su Tetera."},"en":{"desc":"Sigma Sagittarii, a bright blue-white star in the Teapot asterism of Sagittarius, toward the centre of the Milky Way. It is low in the south in summer from Spain.","info":"A hot B2.5 V star about 230 light-years away, with hundreds of times the Sun's luminosity. It is a relatively young main-sequence star.","myth":"According to some sources its name comes from an ancient Mesopotamian designation of the star; the exact origin is uncertain. Sagittarius is the centaur archer of Greek mythology, and Nunki is part of its Teapot."}},"menkent":{"es":{"desc":"Theta Centauri, una estrella naranja brillante en el hombro del Centauro, en el hemisferio sur. Desde España es difícil de ver porque queda muy baja.","info":"Gigante naranja de tipo K0 III, a aprox. 59 años luz, con unas 60 veces la luminosidad del Sol. Está cerca del Sol en términos astronómicos y es una estrella evolucionada que fusiona helio.","myth":"Del árabe «mankib al-qanturis», «el hombro del Centauro». Centauro es la criatura mitad hombre, mitad caballo de la mitología griega, a veces identificada con el sabio Quirón."},"en":{"desc":"Theta Centauri, a bright orange star on the shoulder of the Centaur, in the southern hemisphere. It is hard to see from Spain because it lies very low.","info":"A K0 III orange giant about 59 light-years away, with roughly 60 times the Sun's luminosity. It is close to the Sun in astronomical terms and is an evolved star fusing helium.","myth":"From the Arabic 'mankib al-qanturis', 'the shoulder of the Centaur'. Centaurus is the half-man, half-horse creature of Greek mythology, sometimes identified with the wise Chiron."}},"mirach":{"es":{"desc":"Beta Andromedae, una estrella naranja-rojiza en la cintura de Andrómeda, una de las más brillantes de su constelación. Sirve de punto de partida para hallar la galaxia de Andrómeda (M31).","info":"Gigante roja de tipo M0 III, a aprox. 200 años luz, con unas 1 800 veces la luminosidad del Sol. Cerca de ella se ve la débil galaxia NGC 404, el «fantasma de Mirach».","myth":"Del árabe «mi'zar», «faja» o «cintura», pues marca la cintura de Andrómeda. En la mitología griega Andrómeda era la princesa encadenada a una roca, rescatada por Perseo."},"en":{"desc":"Beta Andromedae, an orange-red star at Andromeda's waist, one of the brightest in its constellation. It is a starting point for finding the Andromeda Galaxy (M31).","info":"An M0 III red giant about 200 light-years away, with roughly 1,800 times the Sun's luminosity. Near it lies the faint galaxy NGC 404, 'Mirach's Ghost'.","myth":"From the Arabic 'mi'zar', 'girdle' or 'sash', since it marks Andromeda's waist. In Greek mythology Andromeda was the princess chained to a rock and rescued by Perseus."}},"alpheratz":{"es":{"desc":"Alfa Andromedae, una estrella blanco-azulada en la cabeza de Andrómeda, que comparte con el Gran Cuadrado de Pegaso. Fácil de hallar en otoño.","info":"Estrella de tipo B8 IV, a aprox. 97 años luz, con unas 200 veces la luminosidad del Sol. Es una estrella peculiar con exceso de mercurio y manganeso y forma un sistema binario.","myth":"Del árabe «surrat al-faras», «el ombligo del caballo»: se le consideraba parte de Pegaso. Antiguamente fue también Delta Pegasi, esquina del Gran Cuadrado, hasta que se asignó a Andrómeda."},"en":{"desc":"Alpha Andromedae, a blue-white star at Andromeda's head, shared with the Great Square of Pegasus. It is easy to find in autumn.","info":"A B8 IV star about 97 light-years away, with roughly 200 times the Sun's luminosity. It is a peculiar star with an excess of mercury and manganese and forms a binary system.","myth":"From the Arabic 'surrat al-faras', 'the navel of the horse': it was considered part of Pegasus. It was formerly also Delta Pegasi, a corner of the Great Square, until it was assigned to Andromeda."}},"rasalhague":{"es":{"desc":"Alfa Ophiuchi, una estrella blanca brillante en la cabeza de Ofiuco, el portador de la serpiente. Se ve en verano, alta en el sur.","info":"Estrella de tipo A5 III, a aprox. 49 años luz, con unas 25 veces la luminosidad del Sol. Es una binaria con un periodo orbital de unos ocho años, con compañera más débil.","myth":"Del árabe «ra's al-hawwa'», «la cabeza del encantador de serpientes». Ofiuco se identifica con Asclepio, dios de la medicina, que sostiene la serpiente."},"en":{"desc":"Alpha Ophiuchi, a bright white star at the head of Ophiuchus, the serpent bearer. It is seen in summer, high in the south.","info":"An A5 III star about 49 light-years away, with roughly 25 times the Sun's luminosity. It is a binary with an orbital period of around eight years and a fainter companion.","myth":"From the Arabic 'ra's al-hawwa'', 'the head of the snake charmer'. Ophiuchus is identified with Asclepius, the god of medicine, who holds the serpent."}},"kochab":{"es":{"desc":"Beta Ursae Minoris, una estrella naranja moderadamente brillante en el cuenco de la Osa Menor, la más brillante tras la Polar. Circumpolar en España.","info":"Gigante naranja de tipo K4 III, a aprox. 130 años luz, con unas 400 veces la luminosidad del Sol. Tiene un planeta confirmado. Hace unos 3 000 años fue la estrella brillante más cercana al polo norte celeste.","myth":"Del árabe «al-kaukab», «la estrella». Kochab y Pherkad son las «Guardianes del Polo»: giran en torno al polo norte celeste y fueron referencia para la navegación."},"en":{"desc":"Beta Ursae Minoris, a moderately bright orange star in the bowl of the Little Dipper, the brightest after Polaris. It is circumpolar in Spain.","info":"A K4 III orange giant about 130 light-years away, with roughly 400 times the Sun's luminosity. It has a confirmed planet. About 3,000 years ago it was the bright star nearest the north celestial pole.","myth":"From the Arabic 'al-kaukab', 'the star'. Kochab and Pherkad are the 'Guardians of the Pole': they circle the north celestial pole and were a navigation reference."}},"saiph":{"es":{"desc":"Kappa Orionis, una estrella blanco-azulada en la rodilla derecha de Orión, en diagonal opuesta a Betelgeuse. Parece menos brillante de lo que sugiere su luminosidad real.","info":"Supergigante azul de tipo B0.5 Ia, a aprox. 650 años luz, con decenas de miles de veces la luminosidad del Sol. Es tan caliente que gran parte de su luz está en el ultravioleta, por eso se ve menos brillante que Rigel.","myth":"Del árabe «saif al-jabbar», «la espada del Gigante». Marca la rodilla de Orión, el cazador gigante de la mitología griega."},"en":{"desc":"Kappa Orionis, a blue-white star at Orion's right knee, diagonally opposite Betelgeuse. It looks dimmer than its true luminosity would suggest.","info":"A B0.5 Ia blue supergiant about 650 light-years away, with tens of thousands of times the Sun's luminosity. It is so hot that much of its light is in the ultraviolet, which is why it looks fainter than Rigel.","myth":"From the Arabic 'saif al-jabbar', 'the sword of the Giant'. It marks the knee of Orion, the giant hunter of Greek mythology."}},"regor":{"es":{"desc":"Gamma Velorum, una estrella blanco-azulada brillante en la Vela, parte de la «Falsa Cruz». Es la estrella Wolf-Rayet más brillante del cielo. Visible solo desde el hemisferio sur.","info":"Sistema múltiple a aprox. 1 000 años luz, cuya pareja principal consta de una estrella Wolf-Rayet y una estrella azul caliente de tipo O que se orbitan en unos 78 días. Son estrellas muy masivas y calientes.","myth":"Regor es un nombre moderno: Roger al revés, en honor del astronauta Roger Chaffee, del Apolo 1; lo propuso su compañero Gus Grissom como broma. La Vela formaba parte de la antigua Argo Navis."},"en":{"desc":"Gamma Velorum, a bright blue-white star in Vela, part of the 'False Cross'. It is the brightest Wolf-Rayet star in the sky. It is visible only from the southern hemisphere.","info":"A multiple system about 1,000 light-years away, whose main pair consists of a Wolf-Rayet star and a hot blue O-type star orbiting each other in about 78 days. Both are very massive and hot.","myth":"Regor is a modern name: 'Roger' spelled backwards, in honour of Apollo 1 astronaut Roger Chaffee, proposed by his crewmate Gus Grissom as a joke. Vela was part of the ancient Argo Navis."}},"mercurio":{"es":{"desc":"El planeta más pequeño y cercano al Sol. A simple vista es un punto brillante y bajo, visible solo poco después del ocaso o antes del alba.","info":"Mundo rocoso con un núcleo metálico muy grande, superficie llena de cráteres y una exosfera casi inexistente, por lo que las temperaturas varían enormemente entre el día y la noche. Lo han visitado Mariner 10, MESSENGER (en órbita de 2011 a 2015) y BepiColombo (ESA/JAXA).","myth":"Conocido desde la Antigüedad, por su rapidez recibió el nombre del mensajero de los dioses romanos (el Hermes griego). Es difícil de observar porque nunca se aleja mucho del Sol en el cielo."},"en":{"desc":"The smallest planet and the closest to the Sun. To the naked eye it is a bright, low point of light, visible only shortly after sunset or before dawn.","info":"A rocky world with a very large metallic core, a heavily cratered surface and an almost nonexistent exosphere, so temperatures swing wildly between day and night. It has been visited by Mariner 10, MESSENGER (in orbit 2011-2015) and BepiColombo (ESA/JAXA).","myth":"Known since antiquity, it was named for its swift motion after the Roman messenger of the gods (the Greek Hermes). It is hard to observe because it never strays far from the Sun in the sky."}},"venus":{"es":{"desc":"Tras el Sol y la Luna, el astro más brillante del cielo. Se ve a simple vista como un «lucero» blanquecino al anochecer o al amanecer; con telescopio muestra fases.","info":"Planeta rocoso de tamaño parecido al de la Tierra, envuelto en una espesa atmósfera de dióxido de carbono y nubes de ácido sulfúrico. Su superficie ronda los 465 °C y gira muy despacio, en sentido retrógrado. Lo exploraron las sondas Venera, Magallanes y Venus Express.","myth":"Lleva el nombre de la diosa romana del amor y la belleza (la Afrodita griega). En 1610 Galileo observó sus fases, una prueba clave a favor del modelo heliocéntrico."},"en":{"desc":"After the Sun and the Moon, the brightest object in the sky. To the naked eye it is a brilliant whitish \"evening\" or \"morning star\"; through a telescope it shows phases.","info":"A rocky planet similar in size to Earth, wrapped in a thick carbon dioxide atmosphere and sulfuric acid clouds. Its surface sits around 465 °C, and it rotates very slowly in a retrograde direction. It has been explored by the Venera, Magellan and Venus Express probes.","myth":"Named after the Roman goddess of love and beauty (the Greek Aphrodite). In 1610 Galileo observed its phases, key evidence in favour of the heliocentric model."}},"tierra":{"es":{"desc":"Nuestro planeta, el único mundo conocido con vida. Visto desde el espacio destaca por el azul de sus océanos y el blanco de las nubes.","info":"Su superficie es en un 71 % agua líquida, y su atmósfera es de nitrógeno (78 %) y oxígeno (21 %). Un núcleo de hierro genera un campo magnético que desvía el viento solar. Se formó hace aprox. 4 540 millones de años.","myth":"El nombre viene del latín «Terra» (Tellus para los romanos; Gea o Gaia para los griegos). Copérnico propuso en 1543 que la Tierra gira alrededor del Sol, y las fotos «Blue Marble» (1972) y «Pálido punto azul» (1990) cambiaron nuestra forma de verla."},"en":{"desc":"Our home planet, the only world known to harbour life. Seen from space it stands out for the blue of its oceans and the white of its clouds.","info":"Its surface is 71% liquid water, and its atmosphere is nitrogen (78%) and oxygen (21%). An iron core generates a magnetic field that deflects the solar wind. It formed about 4.54 billion years ago.","myth":"The name comes from the Latin \"Terra\" (Tellus to the Romans; Gaia to the Greeks). Copernicus proposed in 1543 that the Earth orbits the Sun, and the \"Blue Marble\" (1972) and \"Pale Blue Dot\" (1990) images changed how we see it."}},"marte":{"es":{"desc":"El «planeta rojo»: a simple vista es un punto anaranjado cuyo brillo varía mucho. Con telescopio se aprecian los casquetes polares y manchas oscuras.","info":"Planeta rocoso con una atmósfera tenue de dióxido de carbono y un color debido al óxido de hierro. Alberga el volcán Olympus Mons (aprox. 22 km de altura) y el cañón Valles Marineris. Lo exploran rovers como Curiosity y Perseverance.","myth":"Recibe el nombre del dios romano de la guerra (el Ares griego), quizá por su color rojizo. Los datos de Tycho Brahe sobre su movimiento permitieron a Kepler formular sus leyes. Sus dos lunas, Fobos y Deimos, se descubrieron en 1877."},"en":{"desc":"The \"Red Planet\": to the naked eye it is an orange point whose brightness varies greatly. Through a telescope you can see its polar caps and dark markings.","info":"A rocky planet with a thin carbon dioxide atmosphere and a colour owed to iron oxide. It hosts Olympus Mons (about 22 km high) and the Valles Marineris canyon system. It is being explored by rovers such as Curiosity and Perseverance.","myth":"Named after the Roman god of war (the Greek Ares), perhaps for its blood-red colour. Tycho Brahe's data on its motion allowed Kepler to formulate his laws. Its two moons, Phobos and Deimos, were discovered in 1877."}},"jupiter":{"es":{"desc":"El mayor planeta del sistema solar. A simple vista es un astro blanco muy brillante; con prismáticos se ven sus cuatro lunas mayores y con telescopio, sus bandas.","info":"Gigante gaseoso formado sobre todo por hidrógeno y helio, con bandas de nubes y la Gran Mancha Roja, una tormenta gigantesca. Tiene un tenue sistema de anillos y decenas de satélites. Lo han visitado Pioneer, Voyager, Galileo y Juno, que lo orbita desde 2016.","myth":"Lleva el nombre del rey de los dioses romanos (el Zeus griego). En 1610 Galileo descubrió sus cuatro lunas mayores (Ío, Europa, Ganímedes y Calisto), prueba de que no todo giraba en torno a la Tierra."},"en":{"desc":"The largest planet in the solar system. To the naked eye it is a very bright white object; binoculars reveal its four largest moons and a telescope shows its cloud bands.","info":"A gas giant made mostly of hydrogen and helium, with cloud bands and the Great Red Spot, a giant storm. It has a faint ring system and dozens of moons. Pioneer, Voyager, Galileo and Juno (in orbit since 2016) have visited it.","myth":"Named after the king of the Roman gods (the Greek Zeus). In 1610 Galileo discovered its four largest moons (Io, Europa, Ganymede and Callisto), proof that not everything revolved around the Earth."}},"saturno":{"es":{"desc":"Famoso por sus anillos. A simple vista es un punto amarillento y estable; un telescopio pequeño basta para ver los anillos.","info":"Gigante gaseoso de hidrógeno y helio, tan poco denso que flotaría en agua. Sus anillos, de hielo de agua y roca, son los más extensos del sistema solar. La misión Cassini-Huygens lo estudió de 2004 a 2017.","myth":"Lleva el nombre del dios romano de la agricultura (el Crono griego), padre de Júpiter; las fiestas saturnales se celebraban en su honor. Galileo vio los anillos en 1610 sin entenderlos, y Huygens explicó su naturaleza en 1655."},"en":{"desc":"Famous for its rings. To the naked eye it is a steady yellowish point; even a small telescope shows the rings.","info":"A gas giant of hydrogen and helium, so low in density it would float on water. Its rings, made of water ice and rock, are the most extensive in the solar system. The Cassini-Huygens mission studied it from 2004 to 2017.","myth":"Named after the Roman god of agriculture (the Greek Cronus), father of Jupiter; the Saturnalia festival was held in his honour. Galileo saw the rings in 1610 without understanding them, and Huygens explained their nature in 1655."}},"urano":{"es":{"desc":"Gigante helado de color azul verdoso. Con cielo muy oscuro es apenas visible a simple vista; con prismáticos o telescopio se ve como un disco diminuto.","info":"Su atmósfera de hidrógeno, helio y metano le da su color. Su eje de rotación está inclinado unos 98°, de modo que prácticamente «rueda» sobre su órbita. Tiene anillos tenues y numerosos satélites. Solo lo ha visitado la Voyager 2, en 1986.","myth":"William Herschel lo descubrió el 13 de marzo de 1781 y al principio creyó que era un cometa; fue el primer planeta hallado con telescopio. Herschel lo bautizó «Georgium Sidus», pero se impuso el nombre propuesto por Bode, el dios griego del cielo, Urano."},"en":{"desc":"A blue-green ice giant. Under very dark skies it is barely visible to the naked eye; with binoculars or a telescope it appears as a tiny disc.","info":"Its atmosphere of hydrogen, helium and methane gives it its colour. Its rotation axis is tilted about 98 degrees, so it essentially rolls along its orbit. It has faint rings and many moons. Only Voyager 2 has visited it, in 1986.","myth":"William Herschel discovered it on 13 March 1781 and at first thought it was a comet; it was the first planet found with a telescope. Herschel called it \"Georgium Sidus\", but the name proposed by Bode, after the Greek god of the sky, Uranus, prevailed."}},"neptuno":{"es":{"desc":"El planeta más lejano. Invisible a simple vista; con prismáticos o un telescopio pequeño se ve como un puntito azulado.","info":"Gigante helado de hidrógeno, helio y metano, con los vientos más rápidos del sistema solar (más de 2 000 km/h). Tiene anillos tenues y varias lunas, entre ellas Tritón. Solo lo ha visitado la Voyager 2, en 1989.","myth":"Su posición se predijo con cálculos matemáticos, sobre todo de Le Verrier (Adams llegó a resultados similares), y Galle lo observó en Berlín el 23 de septiembre de 1846. Lleva el nombre del dios romano del mar (el Poseidón griego)."},"en":{"desc":"The most distant planet. Invisible to the naked eye; binoculars or a small telescope show it as a tiny bluish dot.","info":"An ice giant of hydrogen, helium and methane, with the fastest winds in the solar system (over 2,000 km/h). It has faint rings and several moons, including Triton. Only Voyager 2 has visited it, in 1989.","myth":"Its position was predicted by mathematical calculations, chiefly by Le Verrier (Adams reached similar results), and Galle observed it in Berlin on 23 September 1846. It is named after the Roman god of the sea (the Greek Poseidon)."}},"luna":{"es":{"desc":"Nuestro único satélite natural. A simple vista se ven sus mares oscuros y sus fases; con prismáticos, cráteres, montañas y cordilleras.","info":"Rocosa y sin atmósfera apreciable, su gravedad es un sexto de la terrestre. Muestra siempre la misma cara a la Tierra y provoca las mareas. Se cree que se formó tras el choque de un cuerpo del tamaño de Marte contra la Tierra primitiva.","myth":"Selene para los griegos y Luna para los romanos, estaba ligada también a Artemisa y Diana. En 1959 la sonda soviética Luna 2 la alcanzó, y el 20 de julio de 1969 el Apolo 11 llevó a los primeros humanos a su superficie."},"en":{"desc":"Our only natural satellite. To the naked eye you can see its dark maria and its phases; binoculars reveal craters, mountains and ridges.","info":"Rocky and with no appreciable atmosphere, its gravity is one sixth of Earth's. It always shows the same face to Earth and raises the tides. It is thought to have formed after a Mars-sized body struck the early Earth.","myth":"Selene to the Greeks and Luna to the Romans, it was also associated with Artemis and Diana. The Soviet probe Luna 2 reached it in 1959, and on 20 July 1969 Apollo 11 took the first humans to its surface."}},"fobos":{"es":{"desc":"La mayor de las dos lunas de Marte: un pequeño cuerpo irregular, con forma de patata, que solo se observa con telescopios grandes por la cercanía a Marte.","info":"Mide unos 27 × 22 × 18 km y orbita muy cerca de Marte, en unas 7,7 horas, por lo que sale dos o tres veces al día. Destaca el cráter Stickney. Su órbita decae poco a poco y en decenas de millones de años se romperá o chocará con Marte. JAXA prepara la misión MMX.","myth":"Lo descubrió Asaph Hall en 1877 en el Observatorio Naval de EE. UU. Su nombre, «miedo» en griego, es el de uno de los hijos de Ares que acompañaban al dios a la batalla."},"en":{"desc":"The larger of Mars's two moons: a small, irregular, potato-shaped body that can only be seen with large telescopes because it lies so close to Mars.","info":"It measures about 27 x 22 x 18 km and orbits very close to Mars, in about 7.7 hours, so it rises more than twice a day. Its most notable feature is the crater Stickney. Its orbit is slowly decaying and in tens of millions of years it will break up or crash into Mars. JAXA is preparing the MMX mission.","myth":"Discovered by Asaph Hall in 1877 at the US Naval Observatory. Its name, Greek for \"fear\", is that of one of the sons of Ares who accompanied the god into battle."}},"deimos":{"es":{"desc":"La menor y más externa de las lunas de Marte, un diminuto cuerpo irregular que solo se ve con telescopios potentes.","info":"Mide unos 15 × 12 × 10 km y tarda unas 30 horas en orbitar Marte. Su superficie está cubierta de polvo fino que suaviza los cráteres. Como Fobos, quizá sea un asteroide capturado, aunque se debate.","myth":"Asaph Hall lo descubrió en agosto de 1877, pocos días antes que a Fobos. Su nombre, «terror» en griego, es el del otro hijo de Ares; los nombres de ambas lunas se sugirieron a Hall desde Inglaterra a partir de la «Ilíada»."},"en":{"desc":"The smaller, outer moon of Mars, a tiny irregular body visible only with powerful telescopes.","info":"It measures about 15 x 12 x 10 km and takes about 30 hours to orbit Mars. Its surface is covered in fine dust that smooths its craters. Like Phobos, it may be a captured asteroid, though this is debated.","myth":"Asaph Hall discovered it in August 1877, a few days before Phobos. Its name, Greek for \"terror\", belongs to the other son of Ares; the names of both moons were suggested to Hall from England, drawn from the \"Iliad\"."}},"io":{"es":{"desc":"Luna interior de Júpiter, de color amarillento y anaranjado. Con prismáticos estables se distingue como un punto cerca de Júpiter; los detalles exigen telescopios grandes.","info":"Es el cuerpo con más actividad volcánica del sistema solar, con centenares de volcanes y lagos de lava. El calor procede de las mareas que Júpiter y las otras lunas ejercen sobre ella. Su superficie, de azufre y dióxido de azufre, no tiene cráteres de impacto visibles.","myth":"Galileo la vio en enero de 1610 junto a las demás lunas galileanas. Simon Marius propuso los nombres mitológicos. Ío era una sacerdotisa de Hera de quien se enamoró Zeus; este la convirtió en ternera para ocultarla de su esposa. La Voyager 1 halló sus volcanes activos en 1979."},"en":{"desc":"The innermost large moon of Jupiter, yellowish-orange in colour. With steady binoculars it shows as a point near Jupiter; surface detail needs large telescopes.","info":"It is the most volcanically active body in the solar system, with hundreds of volcanoes and lava lakes. Its heat comes from the tides raised by Jupiter and the other moons. Its sulfur and sulfur dioxide surface has no visible impact craters.","myth":"Galileo saw it in January 1610 along with the other Galilean moons. Simon Marius proposed the mythological names. Io was a priestess of Hera whom Zeus fell in love with; he turned her into a heifer to hide her from his wife. Voyager 1 discovered its active volcanoes in 1979."}},"europa":{"es":{"desc":"Luna de Júpiter de superficie helada muy brillante. Con prismáticos estables se ve como un punto cerca de Júpiter.","info":"Una corteza de hielo cubre un océano global de agua salada, uno de los lugares del sistema solar más prometedores para buscar vida. Es algo menor que nuestra Luna y su superficie está surcada de grietas. La misión Europa Clipper de la NASA fue lanzada en 2024 para estudiarla.","myth":"Galileo la observó en 1610. Su nombre procede de Europa, una princesa fenicia a la que Zeus, transformado en toro blanco, raptó y llevó a Creta; de ella toma nombre también el continente."},"en":{"desc":"An icy, very bright moon of Jupiter. With steady binoculars it shows as a point near Jupiter.","info":"An ice crust covers a global saltwater ocean, one of the most promising places in the solar system to search for life. It is slightly smaller than our Moon and its surface is crisscrossed by cracks. NASA's Europa Clipper mission, launched in 2024, will study it.","myth":"Galileo observed it in 1610. Its name comes from Europa, a Phoenician princess whom Zeus, transformed into a white bull, abducted and carried to Crete; the continent is also named after her."}},"ganimedes":{"es":{"desc":"La mayor luna del sistema solar, más grande que Mercurio. Con prismáticos estables se distingue como un punto junto a Júpiter.","info":"Mide unos 5 268 km de diámetro. Es el único satélite con campo magnético propio y probablemente oculte un océano bajo su corteza de hielo. Su superficie combina zonas oscuras y antiguas con otras más claras y surcadas. La sonda JUICE de la ESA, lanzada en 2023, la estudiará.","myth":"Galileo la descubrió en 1610. Ganimedes era en la mitología un joven troyano de gran belleza al que Zeus, convertido en águila, raptó para que fuera copero de los dioses; se le asocia con la constelación de Acuario."},"en":{"desc":"The largest moon in the solar system, bigger than Mercury. With steady binoculars it appears as a point beside Jupiter.","info":"It is about 5,268 km across. It is the only moon with its own magnetic field and probably hides an ocean beneath its icy crust. Its surface combines dark, ancient regions with brighter, grooved terrain. ESA's JUICE probe, launched in 2023, will study it.","myth":"Galileo discovered it in 1610. In myth Ganymede was a beautiful Trojan youth whom Zeus, in the form of an eagle, carried off to serve as cupbearer to the gods; he is associated with the constellation Aquarius."}},"calisto":{"es":{"desc":"La luna galileana más externa de Júpiter, oscura y cubierta de cráteres. Con prismáticos estables se distingue como un punto junto al planeta.","info":"Mide unos 4 821 km de diámetro y tiene una de las superficies más antiguas y craterizadas del sistema solar, de hielo y roca. Quizá oculte un océano profundo. Es la luna galileana menos afectada por la radiación de Júpiter.","myth":"Galileo la descubrió en 1610. Calisto fue una ninfa del séquito de Artemisa que, según el mito, Hera convirtió en osa; Zeus la colocó entre las estrellas como Osa Mayor."},"en":{"desc":"The outermost Galilean moon of Jupiter, dark and covered in craters. With steady binoculars it shows as a point beside the planet.","info":"It is about 4,821 km across and has one of the oldest and most heavily cratered surfaces in the solar system, made of ice and rock. It may hide a deep ocean. It is the Galilean moon least affected by Jupiter's radiation.","myth":"Galileo discovered it in 1610. Callisto was a nymph in Artemis's retinue whom, in the myth, Hera turned into a bear; Zeus placed her among the stars as Ursa Major."}},"titan":{"es":{"desc":"La mayor luna de Saturno, de color anaranjado. Se ve como un punto junto a Saturno con prismáticos estables o un telescopio pequeño.","info":"Es el único satélite con una atmósfera densa, de nitrógeno y metano, y tiene lagos y mares de metano y etano líquidos. Mide unos 5 150 km. La sonda Huygens aterrizó en su superficie el 14 de enero de 2005 y la misión Dragonfly de la NASA planea volver.","myth":"Christiaan Huygens lo descubrió en 1655. El nombre lo propuso John Herschel en 1847, y proviene de los Titanes, la generación de dioses griegos anterior a los olímpicos, hijos de Gea y Urano."},"en":{"desc":"The largest moon of Saturn, orange in colour. It shows as a point beside Saturn with steady binoculars or a small telescope.","info":"It is the only moon with a dense atmosphere, made of nitrogen and methane, and it has lakes and seas of liquid methane and ethane. It measures about 5,150 km. The Huygens probe landed on its surface on 14 January 2005, and NASA's Dragonfly mission plans to return.","myth":"Christiaan Huygens discovered it in 1655. The name was proposed by John Herschel in 1847, after the Titans, the generation of Greek gods before the Olympians, children of Gaia and Uranus."}},"encelado":{"es":{"desc":"Pequeña luna de Saturno, de superficie helada y muy brillante. Solo se ve con telescopios medianos o grandes, cerca del brillo de los anillos.","info":"Mide unos 504 km. Géiseres de vapor de agua y hielo brotan de grietas de su polo sur, alimentados por un océano subterráneo, y forman el anillo E de Saturno. La sonda Cassini los detectó y los atravesó, y es un objetivo clave en la búsqueda de vida.","myth":"William Herschel lo descubrió en 1789. El nombre, propuesto por su hijo John Herschel, es el de Encélado, un gigante de la mitología griega que combatió a los dioses olímpicos y, según un relato, fue sepultado bajo el Etna."},"en":{"desc":"A small moon of Saturn with a bright, icy surface. It can only be seen with medium or large telescopes, close to the glare of the rings.","info":"It is about 504 km across. Plumes of water vapour and ice erupt from cracks near its south pole, fed by a subsurface ocean, and supply Saturn's E ring. The Cassini probe detected them and flew through them, and it is a prime target in the search for life.","myth":"William Herschel discovered it in 1789. The name, proposed by his son John Herschel, is that of Enceladus, a giant of Greek mythology who fought the Olympian gods and, in one account, was buried beneath Mount Etna."}},"triton":{"es":{"desc":"La mayor luna de Neptuno, un mundo helado y muy brillante. Solo se observa con telescopios medianos o grandes.","info":"Orbita en sentido retrógrado, por lo que probablemente es un objeto del cinturón de Kuiper capturado por Neptuno. Su superficie, de hielo de nitrógeno, es de las más frías conocidas (aprox. −235 °C). La Voyager 2 detectó en 1989 penachos de nitrógeno.","myth":"William Lassell lo descubrió el 10 de octubre de 1846, apenas diecisiete días después del hallazgo de Neptuno. Tritón era, en la mitología griega, hijo de Poseidón y mensajero de las profundidades del mar, representado con cola de pez."},"en":{"desc":"The largest moon of Neptune, an icy and very bright world. It can only be seen with medium or large telescopes.","info":"It orbits in a retrograde direction, so it is probably a Kuiper belt object captured by Neptune. Its nitrogen-ice surface is among the coldest known (about -235 °C). Voyager 2 detected nitrogen plumes in 1989.","myth":"William Lassell discovered it on 10 October 1846, only seventeen days after the discovery of Neptune. In Greek mythology Triton was the son of Poseidon and a messenger of the sea depths, depicted with a fish's tail."}},"orion":{"es":{"desc":"La constelación más reconocible del invierno: tres estrellas alineadas forman el Cinturón, rodeado por Betelgeuse y Rigel. Se ve alta al sur por las noches de diciembre a febrero.","info":"Contiene la Nebulosa de Orión (M42), visible a simple vista como una mancha difusa a aprox. 1 300 años luz, y la Cabeza de Caballo. Betelgeuse es una supergigante roja y Rigel, una supergigante azul. Las tres estrellas del Cinturón son Alnitak, Alnilam y Mintaka.","myth":"Orión era un cazador gigante de la mitología griega. Según un relato, murió por la picadura de un escorpión; por eso Orión y Escorpio nunca están a la vez en el cielo. Ptolomeo la incluyó entre las 48 constelaciones clásicas."},"en":{"desc":"The most recognisable winter constellation: three aligned stars form the Belt, flanked by Betelgeuse and Rigel. It stands high in the south on evenings from December to February.","info":"It contains the Orion Nebula (M42), visible to the naked eye as a hazy patch about 1,300 light-years away, and the Horsehead Nebula. Betelgeuse is a red supergiant and Rigel a blue supergiant. The Belt stars are Alnitak, Alnilam and Mintaka.","myth":"Orion was a giant hunter in Greek mythology. In one account he died from a scorpion's sting, which is why Orion and Scorpius are never in the sky together. Ptolemy included it among the 48 classical constellations."}},"osa-mayor":{"es":{"desc":"Contiene el «Carro» o «Cazo», siete estrellas brillantes (Dubhe, Merak, Phecda, Megrez, Alioth, Mizar, Alkaid). Es circumpolar desde Cataluña, y se ve mejor en primavera.","info":"Es la tercera constelación más extensa del cielo. Mizar y Alcor forman una pareja visible a simple vista. Contiene las galaxias M81 y M82 (a aprox. 12 millones de años luz), M101 y la Nebulosa del Búho (M97). Las estrellas del Carro señalan la Polar.","myth":"Para los griegos representaba a la ninfa Calisto, convertida en osa por Hera y colocada en el cielo por Zeus. Ptolomeo la incluyó entre las 48 constelaciones clásicas; muchas culturas ven en el Carro un carro o un cazo."},"en":{"desc":"It holds the \"Plough\" or \"Big Dipper\", seven bright stars (Dubhe, Merak, Phecda, Megrez, Alioth, Mizar, Alkaid). It is circumpolar from Catalonia and best seen in spring.","info":"It is the third-largest constellation in the sky. Mizar and Alcor form a naked-eye pair. It contains the galaxies M81 and M82 (about 12 million light-years away), M101 and the Owl Nebula (M97). The Dipper's stars point to Polaris.","myth":"To the Greeks it represented the nymph Callisto, turned into a bear by Hera and placed in the sky by Zeus. Ptolemy included it among the 48 classical constellations; many cultures see a wagon or a ladle in the Dipper."}},"osa-menor":{"es":{"desc":"Pequeña constelación con forma de cazo, que contiene la Polar en el extremo de su mango. Es circumpolar y visible toda la noche, aunque sus estrellas son débiles.","info":"La Polar (Polaris) está a menos de 1° del polo norte celeste y es una estrella variable cefeida, a aprox. 430 años luz. Kochab y Pherkad, las dos brillantes del «cazo», se llaman los «Guardianes de la Polar». Salvo estas estrellas, el resto es poco brillante.","myth":"Ptolomeo la incluyó entre las 48 constelaciones clásicas. Según versiones, representa a una de las ninfas que criaron a Zeus (Cinosura, «cola de perro»), y para los navegantes antiguos servía de guía hacia el norte."},"en":{"desc":"A small dipper-shaped constellation holding Polaris at the end of its handle. It is circumpolar and visible all night, though its stars are faint.","info":"Polaris lies less than 1 degree from the north celestial pole and is a Cepheid variable star about 430 light-years away. Kochab and Pherkad, the two bright stars of the bowl, are called the \"Guardians of the Pole\". The rest of the stars are faint.","myth":"Ptolemy included it among the 48 classical constellations. In some versions it represents one of the nymphs who raised Zeus (Cynosura, \"dog's tail\"), and ancient sailors used it as a guide to the north."}},"casiopea":{"es":{"desc":"Constelación en forma de W (o M) fácil de reconocer, circumpolar desde Cataluña y alta en el cielo en otoño. Sus estrellas principales son Schedar, Caph y Gamma Cassiopeiae.","info":"Cruzada por la Vía Láctea, es rica en cúmulos abiertos, como M52, M103 y NGC 457. Contiene Casiopea A, resto de supernova, y la supernova de Tycho Brahe de 1572. Schedar es una gigante naranja y Caph, una estrella blanca.","myth":"Casiopea era, en la mitología griega, la reina etíope vanidosa, esposa de Cefeo y madre de Andrómeda, castigada por Poseidón por jactarse de su belleza. Ptolomeo la incluyó entre las 48 constelaciones clásicas."},"en":{"desc":"An easily recognised W-shaped (or M-shaped) constellation, circumpolar from Catalonia and high in the sky in autumn. Its main stars are Schedar, Caph and Gamma Cassiopeiae.","info":"Crossed by the Milky Way, it is rich in open clusters such as M52, M103 and NGC 457. It contains Cassiopeia A, a supernova remnant, and the site of Tycho Brahe's supernova of 1572. Schedar is an orange giant and Caph a white star.","myth":"In Greek mythology Cassiopeia was the vain Ethiopian queen, wife of Cepheus and mother of Andromeda, punished by Poseidon for boasting of her beauty. Ptolemy included it among the 48 classical constellations."}},"cefeo":{"es":{"desc":"Constelación con forma de casita, de estrellas débiles, circumpolar desde Cataluña. Se ve bien en otoño, al lado de Casiopea. Su estrella principal es Alderamin.","info":"Delta Cephei es el prototipo de las cefeidas, variables clave para medir distancias cósmicas. La Estrella Granate (Mu Cephei) es una supergigante roja muy roja. Contiene la nebulosa IC 1396, una gran región de formación estelar.","myth":"Cefeo era el rey de Etiopía, esposo de Casiopea y padre de Andrómeda. Ptolomeo la incluyó entre las 48 constelaciones clásicas. John Goodricke estudió la variabilidad de Delta Cephei en 1784."},"en":{"desc":"A house-shaped constellation of faint stars, circumpolar from Catalonia. It is well placed in autumn, next to Cassiopeia. Its main star is Alderamin.","info":"Delta Cephei is the prototype of the Cepheids, variable stars key to measuring cosmic distances. The Garnet Star (Mu Cephei) is a very red supergiant. It contains the nebula IC 1396, a large star-forming region.","myth":"Cepheus was the king of Ethiopia, husband of Cassiopeia and father of Andromeda. Ptolemy included it among the 48 classical constellations. John Goodricke studied the variability of Delta Cephei in 1784."}},"cisne":{"es":{"desc":"Constelación con forma de gran cruz, la «Cruz del Norte», sobre la Vía Láctea. Deneb marca la cola. Se ve casi cenital en verano y otoño.","info":"Albireo, en el pico, es una doble preciosa de colores dorado y azul con prismáticos potentes o un telescopio pequeño. Contiene las nebulosas Norteamérica (NGC 7000) y del Velo, y Cygnus X-1, uno de los primeros agujeros negros estelares aceptados.","myth":"En la mitología griega suele representar a Zeus transformado en cisne, o a Orfeo convertido en cisne junto a la Lira. Ptolomeo la incluyó entre las 48 constelaciones clásicas. Deneb forma el Triángulo de Verano con Vega y Altair."},"en":{"desc":"A large cross-shaped constellation, the \"Northern Cross\", set along the Milky Way. Deneb marks the tail. It is almost overhead in summer and autumn.","info":"Albireo, at the beak, is a beautiful gold-and-blue double star in strong binoculars or a small telescope. It contains the North America (NGC 7000) and Veil nebulae, and Cygnus X-1, one of the first accepted stellar black holes.","myth":"In Greek myth it often represents Zeus transformed into a swan, or Orpheus turned into a swan beside the Lyre. Ptolemy included it among the 48 classical constellations. Deneb forms the Summer Triangle with Vega and Altair."}},"lira":{"es":{"desc":"Pequeña constelación de verano con forma de paralelogramo, dominada por Vega, una de las estrellas más brillantes del cielo. Pasa casi por el cenit en Cataluña.","info":"Vega está a aprox. 25 años luz. Epsilon Lyrae es la «doble doble», visible con prismáticos y telescopio. La Nebulosa del Anillo (M57) es una nebulosa planetaria, y Sheliak (Beta Lyrae) es una binaria eclipsante.","myth":"La Lira es el instrumento de Orfeo, fabricado según el mito por Hermes con el caparazón de una tortuga. Zeus lo colocó en el cielo tras la muerte del músico. Ptolomeo la incluyó entre las 48 constelaciones clásicas."},"en":{"desc":"A small summer constellation shaped like a parallelogram, dominated by Vega, one of the brightest stars in the sky. It passes almost overhead from Catalonia.","info":"Vega lies about 25 light-years away. Epsilon Lyrae is the \"double double\", visible with binoculars and a telescope. The Ring Nebula (M57) is a planetary nebula, and Sheliak (Beta Lyrae) is an eclipsing binary.","myth":"The Lyre is Orpheus's instrument, made in myth by Hermes from a tortoise shell. Zeus placed it in the sky after the musician's death. Ptolemy included it among the 48 classical constellations."}},"aguila":{"es":{"desc":"Constelación de verano en la Vía Láctea, con Altair como estrella principal flanqueada por Tarazed y Alshain. Forma parte del Triángulo de Verano.","info":"Altair, a aprox. 17 años luz, gira sobre sí misma en pocas horas y está muy aplanada. La zona es rica en campos estelares de la Vía Láctea y contiene cúmulos abiertos, aunque pocos objetos destacan con instrumentos pequeños.","myth":"Representa el águila de Zeus, que llevaba sus rayos y raptó a Ganimedes para convertirlo en copero de los dioses. Ptolomeo la incluyó entre las 48 constelaciones clásicas."},"en":{"desc":"A summer constellation in the Milky Way, with Altair as its main star flanked by Tarazed and Alshain. It is part of the Summer Triangle.","info":"Altair, about 17 light-years away, spins in only a few hours and is noticeably flattened. The area is rich in Milky Way star fields and contains open clusters, though few objects stand out in small instruments.","myth":"It represents the eagle of Zeus, which carried his thunderbolts and abducted Ganymede to serve as cupbearer of the gods. Ptolemy included it among the 48 classical constellations."}},"escorpio":{"es":{"desc":"Constelación con forma de J o de escorpión, con la roja Antares en el corazón. Desde Cataluña se ve baja al sur en las noches de verano, con la cola cerca del horizonte.","info":"Antares es una supergigante roja a aprox. 550 años luz. Contiene los cúmulos abiertos M6 y M7 (el cúmulo de Ptolomeo, visible a simple vista) y los cúmulos globulares M4 y M80. Shaula y Dschubba son otras estrellas notables.","myth":"Según el mito, fue el escorpión enviado para matar a Orión, y por eso Orión se oculta cuando sale Escorpio. Antares significa «rival de Ares» (Marte) por su color rojizo. Ptolomeo la incluyó entre las 48 constelaciones clásicas."},"en":{"desc":"A J-shaped, scorpion-like constellation with red Antares at its heart. From Catalonia it sits low in the south on summer nights, with its tail near the horizon.","info":"Antares is a red supergiant about 550 light-years away. The constellation contains the open clusters M6 and M7 (Ptolemy's Cluster, visible to the naked eye) and the globular clusters M4 and M80. Shaula and Dschubba are other notable stars.","myth":"In myth it is the scorpion sent to kill Orion, which is why Orion sets as Scorpius rises. Antares means \"rival of Ares\" (Mars) for its reddish colour. Ptolemy included it among the 48 classical constellations."}},"leo":{"es":{"desc":"Constelación de primavera con una «hoz» de estrellas que forma la cabeza y el pecho del león, con Régulo en la base, y un triángulo que forma las ancas con Denébola.","info":"Régulo está a aprox. 79 años luz. Algieba es una doble dorada con telescopio. Contiene el Triplete de Leo (M65, M66 y NGC 3628) y las galaxias M95 y M96. Las Leónidas, lluvia de meteoros de noviembre, parecen provenir de aquí.","myth":"Se identifica con el león de Nemea, que Hércules mató en el primero de sus doce trabajos. Los antiguos ya asociaban la constelación al Sol y al verano. Ptolomeo la incluyó entre las 48 constelaciones clásicas."},"en":{"desc":"A spring constellation with a \"sickle\" of stars forming the lion's head and chest, with Regulus at its base, and a triangle forming the hindquarters ending in Denebola.","info":"Regulus is about 79 light-years away. Algieba is a golden double star in a telescope. The constellation contains the Leo Triplet (M65, M66 and NGC 3628) and the galaxies M95 and M96. The Leonids, a November meteor shower, appear to radiate from here.","myth":"It is identified with the Nemean lion, which Hercules killed in the first of his twelve labours. The ancients already linked the constellation with the Sun and summer. Ptolemy included it among the 48 classical constellations."}},"tauro":{"es":{"desc":"Constelación de invierno con la roja Aldebarán, el ojo del toro, y los cúmulos de las Híades, en forma de V, y de las Pléyades. Se ve alta al sur en las noches de invierno.","info":"Las Pléyades (M45), a aprox. 440 años luz, se ven a simple vista como un pequeño grupo de estrellas azuladas. Las Híades son el cúmulo abierto más cercano, a aprox. 150 años luz. La Nebulosa del Cangrejo (M1) es el resto de una supernova.","myth":"Se identifica con el toro en que se transformó Zeus para raptar a Europa. La Nebulosa del Cangrejo es el resto de la supernova que astrónomos chinos registraron en 1054. Ptolomeo la incluyó entre las 48 constelaciones clásicas."},"en":{"desc":"A winter constellation with red Aldebaran, the bull's eye, and the V-shaped Hyades and Pleiades clusters. It stands high in the south on winter nights.","info":"The Pleiades (M45), about 440 light-years away, are visible to the naked eye as a small group of bluish stars. The Hyades are the nearest open cluster, about 150 light-years away. The Crab Nebula (M1) is a supernova remnant.","myth":"It is identified with the bull into which Zeus transformed himself to abduct Europa. The Crab Nebula is the remnant of the supernova recorded by Chinese astronomers in 1054. Ptolemy included it among the 48 classical constellations."}},"geminis":{"es":{"desc":"Constelación de invierno y primavera con las estrellas gemelas Cástor y Pólux, muy próximas entre sí. Está alta al sur en las tardes de febrero y marzo.","info":"Pólux, una gigante naranja a aprox. 34 años luz, es la más brillante; Cástor es un sistema múltiple de seis estrellas. Contiene el cúmulo abierto M35 y la Nebulosa del Esquimal (NGC 2392). Las Gemínidas, en diciembre, son una de las lluvias de meteoros más activas.","myth":"Representa a los gemelos Cástor y Pólux (los Dioscuros), hijos de Leda; según el mito, Pólux era inmortal y Cástor mortal, y Zeus los unió en el cielo. Urano se descubrió en esta constelación en 1781 y Plutón en 1930. Ptolomeo la incluyó entre las 48 clásicas."},"en":{"desc":"A winter and spring constellation with the twin stars Castor and Pollux, close to each other. It stands high in the south on February and March evenings.","info":"Pollux, an orange giant about 34 light-years away, is the brighter; Castor is a sextuple star system. The constellation contains the open cluster M35 and the Eskimo Nebula (NGC 2392). The Geminids, in December, are one of the most active meteor showers.","myth":"It represents the twins Castor and Pollux (the Dioscuri), sons of Leda; in myth Pollux was immortal and Castor mortal, and Zeus united them in the sky. Uranus was discovered in this constellation in 1781 and Pluto in 1930. Ptolemy included it among the 48 classical constellations."}},"can-mayor":{"es":{"desc":"Constelación de invierno con Sirio, la estrella más brillante del cielo nocturno. Desde Cataluña se ve baja al sur en las noches de invierno, siguiendo a Orión.","info":"Sirio está a aprox. 8,6 años luz y tiene una compañera enana blanca, Sirio B. También destacan Mirzam, Adhara, Wezen y Aludra. El cúmulo abierto M41, cerca de Sirio, se aprecia con prismáticos.","myth":"Se identifica con uno de los perros de Orión (o con Laelaps, el perro que nunca fallaba). Los antiguos egipcios, que llamaban a Sirio «Sothis», anunciaban con su aparición al amanecer la crecida del Nilo; de ahí viene la «canícula». Ptolomeo la incluyó entre las 48 constelaciones clásicas."},"en":{"desc":"A winter constellation with Sirius, the brightest star in the night sky. From Catalonia it sits low in the south on winter nights, following Orion.","info":"Sirius is about 8.6 light-years away and has a white dwarf companion, Sirius B. Mirzam, Adhara, Wezen and Aludra also stand out. The open cluster M41, near Sirius, can be seen with binoculars.","myth":"It is identified with one of Orion's dogs (or with Laelaps, the dog that never missed its prey). The ancient Egyptians, who called Sirius \"Sothis\", used its dawn appearance to herald the Nile flood, hence the \"dog days\". Ptolemy included it among the 48 classical constellations."}},"can-menor":{"es":{"desc":"Pequeña constelación de invierno que solo cuenta con dos estrellas visibles, Proción y Gomeisa. Se ve al sur-este de Orión y al este de Géminis.","info":"Proción, a aprox. 11,5 años luz, es una de las estrellas más cercanas y brillantes, con una compañera enana blanca. Forma con Sirio y Betelgeuse el Triángulo de Invierno. Salvo estas estrellas, la constelación tiene pocos objetos de interés.","myth":"Su nombre, Proción, procede del griego y significa «antes del perro»: sale poco antes que Sirio. Según versiones, es el perro de Orión o Maira, la perra del ateniense Icario. Ptolomeo la incluyó entre las 48 constelaciones clásicas."},"en":{"desc":"A small winter constellation with only two bright stars, Procyon and Gomeisa. It lies south-east of Orion and east of Gemini.","info":"Procyon, about 11.5 light-years away, is one of the nearest and brightest stars, with a white dwarf companion. With Sirius and Betelgeuse it forms the Winter Triangle. Apart from these stars, the constellation has few objects of interest.","myth":"The name Procyon comes from Greek and means \"before the dog\": it rises shortly before Sirius. In some versions it is Orion's dog or Maera, the dog of the Athenian Icarius. Ptolemy included it among the 48 classical constellations."}},"auriga":{"es":{"desc":"Constelación de invierno con forma de pentágono irregular, dominada por la brillante Capela. Se ve alta en el cielo en las noches de invierno, cerca del cenit.","info":"Capela, a aprox. 43 años luz, es en realidad un sistema de cuatro estrellas, con dos gigantes amarillas muy parecidas. Contiene los cúmulos abiertos M36, M37 y M38, visibles con prismáticos en la Vía Láctea. Menkalinan es otra estrella destacada.","myth":"Representa a un auriga o cochero; según una tradición, a Erictonio, que inventó el carro de cuatro caballos. Capela («cabrita») se asocia a la cabra Amaltea, que amamantó a Zeus. Ptolomeo la incluyó entre las 48 constelaciones clásicas."},"en":{"desc":"A winter constellation shaped like an irregular pentagon, dominated by bright Capella. It rides high in the sky on winter nights, near the zenith.","info":"Capella, about 43 light-years away, is actually a four-star system, with two very similar yellow giants. The constellation contains the open clusters M36, M37 and M38, visible with binoculars in the Milky Way. Menkalinan is another notable star.","myth":"It represents a charioteer; one tradition identifies him as Erichthonius, inventor of the four-horse chariot. Capella (\"little she-goat\") is associated with the goat Amalthea, who suckled Zeus. Ptolemy included it among the 48 classical constellations."}},"boyero":{"es":{"desc":"Constelación de primavera y verano con forma de cometa o cucurucho, con la brillante Arturo en el vértice inferior. Se encuentra siguiendo el arco del mango de la Osa Mayor.","info":"Arturo, una gigante naranja a aprox. 37 años luz, es la cuarta estrella más brillante del cielo y la más brillante del hemisferio norte celeste. Izar es una doble hermosa con telescopio. Entre sus estrellas hay un enorme vacío de galaxias, el Vacío del Boyero.","myth":"El nombre significa «el que conduce los bueyes» en griego, y suele identificarse con un labrador. Arturo significa «guardián de la Osa». Según versiones, el Boyero es Arcas, hijo de Calisto, o Icario. Ptolomeo la incluyó entre las 48 constelaciones clásicas."},"en":{"desc":"A spring and summer constellation shaped like a kite or ice-cream cone, with bright Arcturus at the lower vertex. Find it by following the arc of the Big Dipper's handle.","info":"Arcturus, an orange giant about 37 light-years away, is the fourth-brightest star in the sky and the brightest in the northern celestial hemisphere. Izar is a lovely double in a telescope. The Boötes Void, a vast region nearly empty of galaxies, lies in this direction.","myth":"The name means \"ox-driver\" in Greek, and the figure is usually seen as a ploughman. Arcturus means \"guardian of the bear\". In some versions Boötes is Arcas, son of Callisto, or Icarius. Ptolemy included it among the 48 classical constellations."}},"virgo":{"es":{"desc":"Gran constelación de primavera, la segunda más extensa del cielo, con Spica, brillante estrella azulada, en el extremo inferior. Se ve al sur en las noches de abril a junio.","info":"Spica está a aprox. 250 años luz. En la dirección de Virgo se encuentra el Cúmulo de Virgo, con M87 (cuyo agujero negro se fotografió en 2019), M104 (la Galaxia del Sombrero), M49 y M60. También contiene 3C 273, un cuásar brillante.","myth":"Se asocia a Démeter (Ceres para los romanos), diosa de las cosechas, cuya espiga es Spica, o a Astrea, diosa de la justicia. Hiparco comparó la posición de Spica con registros anteriores y descubrió la precesión de los equinoccios. Ptolomeo la incluyó entre las 48 constelaciones clásicas."},"en":{"desc":"A large spring constellation, the second-largest in the sky, with Spica, a bright bluish star, at its lower end. It is seen in the south on April to June nights.","info":"Spica is about 250 light-years away. Toward Virgo lies the Virgo Cluster of galaxies, including M87 (whose black hole was imaged in 2019), M104 (the Sombrero Galaxy), M49 and M60. It also contains 3C 273, a bright quasar.","myth":"It is associated with Demeter (Ceres to the Romans), goddess of the harvest, whose ear of wheat is Spica, or with Astraea, goddess of justice. Hipparchus compared Spica's position with earlier records and discovered the precession of the equinoxes. Ptolemy included it among the 48 classical constellations."}},"corona-boreal":{"es":{"desc":"Pequeño arco de estrellas en semicírculo, fácil de reconocer en primavera y verano. Se ve entre el Boyero y Hércules, y su estrella más brillante es Alphecca (Gemma).","info":"Alphecca es una estrella blanca; el arco recuerda a una diadema. T Coronae Borealis es una nova recurrente que estalló en 1866 y 1946, y se espera que vuelva a hacerlo. La constelación incluye un cúmulo de galaxias distante.","myth":"Según el mito, es la corona que Dioniso regaló a Ariadna al abandonarla Teseo en Naxos, y que después fue colocada entre las estrellas. Ptolomeo la incluyó entre las 48 constelaciones clásicas."},"en":{"desc":"A small semicircular arc of stars, easy to recognise in spring and summer. It lies between Boötes and Hercules, and its brightest star is Alphecca (Gemma).","info":"Alphecca is a white star; the arc resembles a diadem. T Coronae Borealis is a recurrent nova that erupted in 1866 and 1946 and is expected to do so again. The constellation includes a distant galaxy cluster.","myth":"In myth it is the crown Dionysus gave to Ariadne after Theseus abandoned her on Naxos, later placed among the stars. Ptolemy included it among the 48 classical constellations."}},"hercules":{"es":{"desc":"Gran constelación de verano de estrellas poco brillantes, con el «Trapecio» o «Piedra Angular» central. Se ve alta al sur en las noches de verano, entre Lira y Corona Boreal.","info":"Contiene el cúmulo globular M13, el más brillante del hemisferio norte, a aprox. 22 000 años luz, visible a simple vista en cielos oscuros, y M92. Ras Algethi (Alfa Herculis) es una doble gigante roja. En 1974 se envió el mensaje de Arecibo hacia M13.","myth":"Representa al héroe Heracles (Hércules para los romanos), famoso por sus doce trabajos. Ptolomeo lo llamaba «el Arrodillado» (Engonasin) y lo incluyó entre las 48 constelaciones clásicas."},"en":{"desc":"A large summer constellation of faint stars, with the central \"Keystone\". It stands high in the south on summer nights, between Lyra and Corona Borealis.","info":"It contains the globular cluster M13, the brightest in the northern sky, about 22,000 light-years away and visible to the naked eye in dark skies, and M92. Ras Algethi (Alpha Herculis) is a double red giant. In 1974 the Arecibo message was sent toward M13.","myth":"It represents the hero Heracles (Hercules to the Romans), famous for his twelve labours. Ptolemy called it \"the Kneeler\" (Engonasin) and included it among the 48 classical constellations."}},"dragon":{"es":{"desc":"Larga y sinuosa constelación circumpolar que rodea a la Osa Menor, de estrellas débiles. Su cabeza, formada por un cuadrilátero, se ve cerca de Lira y Hércules.","info":"Tuban (Thuban) fue la estrella polar hace aprox. 4 800 años, en tiempos de las pirámides egipcias. Eltanin (Gamma Draconis) sirvió a James Bradley para descubrir la aberración de la luz en 1725-1728. La Nebulosa Ojo de Gato (NGC 6543) es una nebulosa planetaria.","myth":"Según el mito, es Ladón, el dragón que guardaba las manzanas de oro del jardín de las Hespérides, derrotado por Hércules; en otra versión, un dragón arrojado al cielo por Atenea. Ptolomeo la incluyó entre las 48 constelaciones clásicas."},"en":{"desc":"A long, winding circumpolar constellation of faint stars wrapping around Ursa Minor. Its head, a quadrilateral, is seen near Lyra and Hercules.","info":"Thuban was the pole star about 4,800 years ago, in the time of the Egyptian pyramids. Eltanin (Gamma Draconis) allowed James Bradley to discover the aberration of light in 1725-1728. The Cat's Eye Nebula (NGC 6543) is a planetary nebula.","myth":"In myth it is Ladon, the dragon that guarded the golden apples of the Hesperides, defeated by Hercules; in another version, a dragon hurled into the sky by Athena. Ptolemy included it among the 48 classical constellations."}},"perseo":{"es":{"desc":"Constelación de otoño e invierno en la Vía Láctea, con la brillante Mirfak y la variable Algol. Se ve alta en el cielo entre Casiopea y Tauro.","info":"Algol es una binaria eclipsante que baja de brillo cada 2,87 días. El Doble Cúmulo (h y χ Persei) se ve a simple vista y con prismáticos; también contiene M34. Las Perseidas, la lluvia de meteoros de agosto, parecen salir de esta constelación.","myth":"Representa a Perseo, héroe que decapitó a la Medusa y salvó a Andrómeda. Algol, la «estrella demonio», sería el ojo de la cabeza de Medusa que lleva el héroe. John Goodricke explicó su variabilidad en 1783. Ptolomeo la incluyó entre las 48 constelaciones clásicas."},"en":{"desc":"An autumn and winter constellation in the Milky Way, with bright Mirfak and the variable Algol. It rides high in the sky between Cassiopeia and Taurus.","info":"Algol is an eclipsing binary that dims every 2.87 days. The Double Cluster (h and chi Persei) is visible to the naked eye and with binoculars; the constellation also contains M34. The Perseids, the August meteor shower, appear to radiate from here.","myth":"It represents Perseus, the hero who beheaded Medusa and rescued Andromeda. Algol, the \"Demon Star\", is said to be the eye of Medusa's head, which the hero carries. John Goodricke explained its variability in 1783. Ptolemy included it among the 48 classical constellations."}},"andromeda":{"es":{"desc":"Constelación de otoño que parte de la esquina del Gran Cuadrado de Pegaso y se extiende en dos cadenas de estrellas. Contiene la Galaxia de Andrómeda, visible a simple vista.","info":"La Galaxia de Andrómeda (M31), a aprox. 2,5 millones de años luz, es la galaxia grande más cercana a la Vía Láctea y se ve como una mancha alargada en cielos oscuros. La acompañan M32 y M110. Almach es una doble dorada y azul. Alpheratz es la estrella que une Andrómeda con Pegaso.","myth":"Andrómeda era la hija de Casiopea y Cefeo, encadenada a una roca para ser sacrificada al monstruo marino Ceto, y salvada por Perseo. Edwin Hubble demostró en 1923 que M31 está fuera de la Vía Láctea. Ptolomeo la incluyó entre las 48 constelaciones clásicas."},"en":{"desc":"An autumn constellation that starts from a corner of the Great Square of Pegasus and extends in two chains of stars. It contains the Andromeda Galaxy, visible to the naked eye.","info":"The Andromeda Galaxy (M31), about 2.5 million light-years away, is the nearest large galaxy to the Milky Way and appears as an elongated patch in dark skies. It is accompanied by M32 and M110. Almach is a gold-and-blue double. Alpheratz is the star linking Andromeda to Pegasus.","myth":"Andromeda was the daughter of Cassiopeia and Cepheus, chained to a rock to be sacrificed to the sea monster Cetus, and saved by Perseus. Edwin Hubble showed in 1923 that M31 lies outside the Milky Way. Ptolemy included it among the 48 classical constellations."}},"pegaso":{"es":{"desc":"Constelación de otoño con el «Gran Cuadrado», formado por Markab, Scheat, Algenib y Alpheratz. Se ve alto al sur en las noches de octubre y noviembre.","info":"El Gran Cuadrado mide unos 15° de lado y sirve de guía para encontrar estrellas más débiles de la zona. Contiene el cúmulo globular M15 y la estrella 51 Pegasi, alrededor de la cual se descubrió en 1995 el primer exoplaneta en una estrella de tipo solar.","myth":"Pegaso era el caballo alado nacido de la sangre de Medusa al ser decapitada por Perseo; Belerofonte lo domó, y luego llevó los rayos de Zeus. Ptolomeo la incluyó entre las 48 constelaciones clásicas."},"en":{"desc":"An autumn constellation with the \"Great Square\", formed by Markab, Scheat, Algenib and Alpheratz. It stands high in the south on October and November nights.","info":"The Great Square measures about 15 degrees across and serves as a guide for finding fainter stars in the area. It contains the globular cluster M15 and the star 51 Pegasi, around which the first exoplanet around a Sun-like star was discovered in 1995.","myth":"Pegasus was the winged horse born from Medusa's blood when she was beheaded by Perseus; Bellerophon tamed it, and it later carried Zeus's thunderbolts. Ptolemy included it among the 48 classical constellations."}},"aries":{"es":{"desc":"Pequeña constelación zodiacal de otoño, un arco corto de estrellas medias entre Piscis y Tauro. Sus estrellas principales son Hamal, Sheratan y Mesarthim.","info":"Hamal es una gigante naranja a aprox. 66 años luz. Mesarthim (Gamma Arietis) es una doble fácil con telescopio pequeño, descubierta por Robert Hooke en 1664. Es una constelación pobre en objetos de cielo profundo para instrumentos pequeños.","myth":"Representa al carnero de vellocino de oro, que salvó a Frixo y Hele; el vellocino fue buscado luego por Jasón y los Argonautas. En la Antigüedad el equinoccio de primavera estaba en Aries, por lo que el «punto Aries» conserva ese nombre. Ptolomeo la incluyó entre las 48 clásicas."},"en":{"desc":"A small zodiac constellation of autumn, a short arc of moderately bright stars between Pisces and Taurus. Its main stars are Hamal, Sheratan and Mesarthim.","info":"Hamal is an orange giant about 66 light-years away. Mesarthim (Gamma Arietis) is an easy double in a small telescope, discovered by Robert Hooke in 1664. It is a constellation poor in deep-sky objects for small instruments.","myth":"It represents the ram of the Golden Fleece, which saved Phrixus and Helle; the fleece was later sought by Jason and the Argonauts. In antiquity the spring equinox lay in Aries, so the \"First Point of Aries\" keeps that name. Ptolemy included it among the 48 classical constellations."}},"cruz-del-sur":{"es":{"desc":"La constelación más pequeña del cielo, con cuatro estrellas brillantes en forma de cruz (Acrux, Mimosa, Gacrux y Delta). No es visible desde Cataluña: pertenece al cielo austral.","info":"Contiene el Saco de Carbón, una nebulosa oscura conspicua, y el Joyero (NGC 4755), un cúmulo abierto de estrellas de colores. Acrux es una estrella múltiple. Solo es visible al sur de unos 25-30° N de latitud, y es un símbolo de varias banderas del hemisferio sur.","myth":"Ptolomeo incluía sus estrellas en Centauro, y los navegantes europeos la distinguieron como constelación propia en los siglos XVI y XVII, al explorar los mares del sur, y fue clave para la orientación en el hemisferio sur."},"en":{"desc":"The smallest constellation in the sky, with four bright stars in a cross shape (Acrux, Mimosa, Gacrux and Delta). It is not visible from Catalonia: it belongs to the southern sky.","info":"It contains the Coalsack, a conspicuous dark nebula, and the Jewel Box (NGC 4755), an open cluster of coloured stars. Acrux is a multiple star. It is only visible south of roughly 25-30 degrees N latitude, and is a symbol on several southern-hemisphere flags.","myth":"Ptolemy counted its stars as part of Centaurus, and European navigators distinguished it as its own constellation in the 16th and 17th centuries while exploring the southern seas; it became key for navigation in the southern hemisphere."}},"centauro":{"es":{"desc":"Gran constelación austral, de la que solo se ve su parte norte desde Cataluña, muy baja sobre el horizonte sur en las noches de primavera. Contiene Alfa Centauri.","info":"Alfa Centauri, a aprox. 4,4 años luz, es el sistema estelar más cercano al Sol; su compañera Próxima Centauri es la estrella más próxima conocida. Omega Centauri (NGC 5139) es el mayor cúmulo globular de la Vía Láctea, y Centaurus A es una galaxia activa muy brillante.","myth":"Representa a un centauro, mitad hombre y mitad caballo, a menudo identificado con Quirón, el sabio maestro de héroes como Aquiles y Jasón. Ptolomeo la incluyó entre las 48 constelaciones clásicas, con la Cruz del Sur dentro de ella."},"en":{"desc":"A large southern constellation of which only the northern part can be seen from Catalonia, very low above the southern horizon on spring evenings. It contains Alpha Centauri.","info":"Alpha Centauri, about 4.4 light-years away, is the star system nearest the Sun; its companion Proxima Centauri is the closest known star. Omega Centauri (NGC 5139) is the largest globular cluster of the Milky Way, and Centaurus A is a very bright active galaxy.","myth":"It represents a centaur, half man and half horse, often identified with Chiron, the wise teacher of heroes such as Achilles and Jason. Ptolemy included it among the 48 classical constellations, with the Southern Cross inside it."}},"sagitario":{"es":{"desc":"Constelación de verano con forma de tetera, baja en el horizonte sur desde Cataluña. Señala la dirección del centro de la Vía Láctea, muy brillante en esta zona.","info":"En su dirección está Sagitario A*, el agujero negro supermasivo del centro galáctico, de aprox. 4 millones de masas solares, a aprox. 26 000 años luz. Contiene las nebulosas Laguna (M8), Trífida (M20) y Omega (M17) y el cúmulo globular M22.","myth":"Representa a un centauro arquero, que algunas tradiciones identifican con Quirón o con el sátiro Croto. Ptolomeo la incluyó entre las 48 constelaciones clásicas. Los astrónomos Genzel y Ghez recibieron el Nobel de Física en 2020 por demostrar el agujero negro de Sagitario A*."},"en":{"desc":"A summer constellation shaped like a teapot, low on the southern horizon from Catalonia. It marks the direction of the centre of the Milky Way, very bright in this area.","info":"In its direction lies Sagittarius A*, the supermassive black hole at the galactic centre, of about 4 million solar masses, about 26,000 light-years away. It contains the Lagoon (M8), Trifid (M20) and Omega (M17) nebulae and the globular cluster M22.","myth":"It represents a centaur archer, whom some traditions identify with Chiron or with the satyr Crotus. Ptolemy included it among the 48 classical constellations. The astronomers Genzel and Ghez shared the 2020 Nobel Prize in Physics for demonstrating the black hole Sagittarius A*."}},"capricornio":{"es":{"desc":"Constelación zodiacal de verano y otoño, de estrellas débiles con forma de triángulo o sonrisa. Se ve baja al sur-sureste desde Cataluña en las noches de agosto a octubre.","info":"Alfa Capricorni (Algedi) es una doble visible a simple vista, y Deneb Algedi es la estrella más brillante. Contiene el cúmulo globular M30. Es una constelación débil, con pocos objetos al alcance de instrumentos pequeños.","myth":"Se representa como una cabra con cola de pez. Según un mito, es Pan, que se lanzó al Nilo para huir del monstruo Tifón y se transformó a medias en pez. Ptolomeo la incluyó entre las 48 constelaciones clásicas."},"en":{"desc":"A summer and autumn zodiac constellation of faint stars forming a triangle or smile. It is seen low in the south-south-east from Catalonia on nights from August to October.","info":"Alpha Capricorni (Algedi) is a double visible to the naked eye, and Deneb Algedi is the brightest star. It contains the globular cluster M30. It is a faint constellation with few objects within reach of small instruments.","myth":"It is depicted as a goat with a fish's tail. In one myth it is Pan, who leapt into the Nile to escape the monster Typhon and half-transformed into a fish. Ptolemy included it among the 48 classical constellations."}},"libra":{"es":{"desc":"Constelación zodiacal de verano, discreta, entre Virgo y Escorpio. Sus estrellas principales, Zubenelgenubi y Zubeneschamali, forman un cuadrilátero débil, bajo al sur.","info":"Zubenelgenubi (Alfa Librae) es una doble visible a simple vista, o con prismáticos. Zubeneschamali es la estrella más brillante. Gliese 581, con planetas, está en esta constelación. No tiene objetos de cielo profundo muy conocidos.","myth":"Es la única constelación zodiacal que representa un objeto: una balanza. Los griegos la veían como las pinzas del escorpión (los nombres árabes de sus estrellas conservan «pinza»); los romanos la convirtieron en balanza, asociada a la justicia. Ptolomeo la llamaba «Quelas»."},"en":{"desc":"A discreet summer zodiac constellation between Virgo and Scorpius. Its main stars, Zubenelgenubi and Zubeneschamali, form a faint quadrilateral, low in the south.","info":"Zubenelgenubi (Alpha Librae) is a double visible to the naked eye or with binoculars. Zubeneschamali is the brightest star. Gliese 581, a planet-bearing star, lies in this constellation. It has no well-known deep-sky objects.","myth":"It is the only zodiac constellation that depicts an object: a pair of scales. The Greeks saw it as the claws of the scorpion (the Arabic names of its stars preserve \"claw\"); the Romans turned it into scales, linked to justice. Ptolemy called it \"Chelae\"."}},"triangulo-austral":{"es":{"desc":"Pequeña constelación austral con tres estrellas brillantes que forman un triángulo (Atria, Beta y Gamma). No es visible desde Cataluña, pues está demasiado al sur.","info":"Atria (Alfa Trianguli Australis) es una gigante naranja. Contiene el cúmulo abierto NGC 6025. Solo se ve en latitudes inferiores a unos 25° N, cerca de la Vía Láctea austral y de Alfa Centauri.","myth":"No tiene mito clásico: no figura entre las 48 constelaciones de Ptolomeo. Lo incluyó Johann Bayer en su atlas Uranometria (1603), a partir de las observaciones de los navegantes neerlandeses Keyser y de Houtman en el hemisferio sur."},"en":{"desc":"A small southern constellation with three bright stars forming a triangle (Atria, Beta and Gamma). It is not visible from Catalonia, being too far south.","info":"Atria (Alpha Trianguli Australis) is an orange giant. The constellation contains the open cluster NGC 6025. It is only visible at latitudes south of about 25 degrees N, near the southern Milky Way and Alpha Centauri.","myth":"It has no classical myth: it is not among Ptolemy's 48 constellations. Johann Bayer included it in his atlas Uranometria (1603), based on observations made in the southern hemisphere by the Dutch navigators Keyser and de Houtman."}},"halley":{"es":{"desc":"El cometa periódico más famoso. Cada aprox. 76 años se hace visible a simple vista, con una cabellera y una cola brillantes. Su último paso fue en 1986.","info":"Su núcleo, helado y oscuro, tiene forma de patata y unos 15 km de largo. En 1986 lo visitaron las sondas Giotto (ESA), Vega 1 y 2, Suisei y Sakigake. Sus restos originan las Oriónidas y las Eta Acuáridas. El próximo perihelio será en 2061.","myth":"Edmond Halley, que observó el cometa de 1682, advirtió que coincidía con apariciones anteriores y predijo su regreso para 1758; se cumplió tras su muerte. Hay registros de sus pasos desde al menos el 240 a. C., y aparece en el Tapiz de Bayeux (1066)."},"en":{"desc":"The most famous periodic comet. Every 76 years or so it becomes visible to the naked eye, with a bright coma and tail. Its last passage was in 1986.","info":"Its icy, dark nucleus is potato-shaped and about 15 km long. In 1986 it was visited by the Giotto (ESA), Vega 1 and 2, Suisei and Sakigake probes. Its debris causes the Orionids and Eta Aquariids. The next perihelion will be in 2061.","myth":"Edmond Halley, who observed the comet of 1682, noticed that it matched earlier apparitions and predicted its return for 1758; it came back after his death. Records of its passages exist from at least 240 BC, and it appears in the Bayeux Tapestry (1066)."}},"cinturon-asteroides":{"es":{"desc":"Región entre las órbitas de Marte y Júpiter con millones de asteroides. No se ve a simple vista; los asteroides más brillantes, como Vesta, sí se ven con prismáticos.","info":"Contiene millones de cuerpos rocosos y metálicos, pero su masa total es muy pequeña, bastante menor que la de la Luna. Ceres, un planeta enano de unos 940 km, reúne aprox. un tercio de esa masa. Las sondas Dawn (Vesta y Ceres) y Hayabusa2 (Ryugu) estudiaron asteroides.","myth":"Giuseppe Piazzi descubrió Ceres el 1 de enero de 1801, el primer asteroide conocido. Los objetos no llegaron a formar un planeta, probablemente por la influencia gravitatoria de Júpiter. Los asteroides están muy separados entre sí, no como en las películas."},"en":{"desc":"A region between the orbits of Mars and Jupiter with millions of asteroids. It is not visible to the naked eye; the brightest asteroids, such as Vesta, can be seen with binoculars.","info":"It contains millions of rocky and metallic bodies, but their total mass is very small, well below that of the Moon. Ceres, a dwarf planet about 940 km across, holds roughly a third of that mass. The Dawn probe (Vesta and Ceres) studied asteroids at close range.","myth":"Giuseppe Piazzi discovered Ceres on 1 January 1801, the first known asteroid. The objects never formed a planet, probably because of Jupiter's gravitational influence. Asteroids are very far apart from each other, unlike in the movies."}},"cinturon-kuiper":{"es":{"desc":"Disco de cuerpos helados más allá de la órbita de Neptuno. Está lejos y no se ve con instrumentos de aficionado, salvo Plutón con telescopios grandes.","info":"Contiene Plutón y otros planetas enanos como Haumea y Makemake, junto a miles de cuerpos helados. Es el origen de muchos cometas de periodo corto. New Horizons sobrevoló Plutón en 2015 y Arrokoth en 2019.","myth":"Lleva el nombre de Gerard Kuiper, que planteó su existencia a mediados del siglo XX. El primer objeto descubierto tras Plutón fue 1992 QB1, hallado por David Jewitt y Jane Luu en 1992. El descubrimiento de Eris llevó a la redefinición de «planeta» en 2006."},"en":{"desc":"A disc of icy bodies beyond the orbit of Neptune. It is distant and out of reach of amateur instruments, except Pluto with large telescopes.","info":"It contains Pluto and other dwarf planets such as Haumea and Makemake, along with thousands of icy bodies. It is the source of many short-period comets. New Horizons flew past Pluto in 2015 and Arrokoth in 2019.","myth":"Named after Gerard Kuiper, who discussed its existence in the mid-20th century. The first object found after Pluto was 1992 QB1, discovered by David Jewitt and Jane Luu in 1992. The discovery of Eris led to the redefinition of \"planet\" in 2006."}},"ngc-4889":{"es":{"desc":"Galaxia elíptica gigante en el Cúmulo de Coma, en la Cabellera de Berenice. Es débil y solo se ve con telescopios medianos o grandes.","info":"Es la galaxia más brillante del Cúmulo de Coma y alberga uno de los mayores agujeros negros conocidos, de aprox. 21 mil millones de masas solares. Su horizonte de sucesos es unas diez veces mayor que el sistema solar.","myth":"Su masa se estimó en 2011 a partir de las velocidades de las estrellas que orbitan en torno al centro, medidas con telescopios de gran tamaño. Es notable por ser uno de los agujeros negros más masivos medidos. Se halla en una región donde ya no hay gas para alimentarlo."},"en":{"desc":"A giant elliptical galaxy in the Coma Cluster, in Coma Berenices. It is faint and visible only in medium or large telescopes.","info":"It is the brightest galaxy in the Coma Cluster and hosts one of the largest known black holes, of about 21 billion solar masses. Its event horizon is about ten times larger than the solar system.","myth":"Its mass was estimated in 2011 from the velocities of stars orbiting the centre, measured with large telescopes. It is notable as one of the most massive black holes ever measured. It sits in a region with little gas left to feed it."}},"holm-15a":{"es":{"desc":"Galaxia elíptica gigante en el cúmulo Abell 85, en la Ballena. Muy débil, accesible solo a grandes telescopios.","info":"Es la galaxia central del cúmulo Abell 85 y alberga un agujero negro de aprox. 40 mil millones de masas solares, uno de los mayores medidos. Su núcleo es inusualmente poco denso en estrellas.","myth":"Su masa se midió directamente en 2019 a partir del movimiento de las estrellas con el instrumento SINFONI del VLT, uno de los mayores agujeros negros determinados por este método. El nombre procede de Holmberg, que la catalogó (Holm 15A)."},"en":{"desc":"A giant elliptical galaxy in the Abell 85 cluster, in Cetus. Very faint, accessible only to large telescopes.","info":"It is the central galaxy of the Abell 85 cluster and hosts a black hole of about 40 billion solar masses, one of the largest measured. Its core is unusually sparse in stars.","myth":"Its mass was measured directly in 2019 from the motion of stars using the VLT's SINFONI instrument, one of the largest black holes determined by this method. The name comes from Holmberg, who catalogued it (Holm 15A)."}},"galaxia-de-andromeda-m31":{"es":{"desc":"Mancha alargada y tenue visible a simple vista en cielos oscuros (mag. aprox. 3,4); en prismáticos muestra un núcleo brillante y un halo extenso.","info":"Galaxia espiral de unos 220 000 años luz de diámetro, la mayor del Grupo Local, a aprox. 2,5 millones de años luz. Se acerca a la Vía Láctea y se prevé una fusión dentro de unos 4 500 millones de años. Tiene como satélites a M32 y M110.","myth":"Ya la describió el astrónomo persa al-Sufi hacia el año 964 como una «pequeña nube». Messier la incluyó en su catálogo en 1764. En 1923-1924 Edwin Hubble midió cefeidas en ella y demostró que era una galaxia independiente. Su nombre procede de la constelación y de la princesa de la mitología griega."},"en":{"desc":"A faint elongated glow visible to the naked eye from dark skies (mag. about 3.4); binoculars show a bright core and a wide halo.","info":"A spiral galaxy about 220,000 light-years across, the largest of the Local Group, at about 2.5 million light-years. It is approaching the Milky Way, and a merger is expected in roughly 4.5 billion years. M32 and M110 are among its satellites.","myth":"The Persian astronomer al-Sufi described it around 964 as a 'small cloud'. Messier included it in his catalogue in 1764. In 1923-1924 Edwin Hubble measured Cepheid variables in it and showed it was a separate galaxy. The name comes from the constellation and the princess of Greek myth."}},"galaxia-del-triangulo-m33":{"es":{"desc":"Galaxia muy extensa y de brillo superficial bajo (mag. aprox. 6): con cielo muy oscuro se intuye a simple vista; en prismáticos, un halo difuso.","info":"Galaxia espiral de unos 60 000 años luz de diámetro, a aprox. 2,7 millones de años luz, la tercera más grande del Grupo Local tras M31 y la Vía Láctea. Alberga NGC 604, una de las mayores regiones de formación estelar conocidas.","myth":"Fue registrada por Giovanni Battista Hodierna antes de 1654 y Messier la incluyó en su catálogo en 1764. Se la conoce por su constelación, el Triángulo; también se la llama galaxia del Molinillo, nombre que comparte con otras espirales."},"en":{"desc":"A very large, low-surface-brightness galaxy (mag. about 6): under very dark skies it may be glimpsed with the naked eye; binoculars show a diffuse glow.","info":"A spiral galaxy about 60,000 light-years across, at about 2.7 million light-years, the third largest in the Local Group after M31 and the Milky Way. It hosts NGC 604, one of the largest known star-forming regions.","myth":"Giovanni Battista Hodierna recorded it before 1654, and Messier added it to his catalogue in 1764. It takes its common name from its constellation, Triangulum, and is also nicknamed the Pinwheel, a name shared with other spirals."}},"galaxia-de-bode-m81":{"es":{"desc":"Espiral brillante (mag. aprox. 6,9) visible en prismáticos como un óvalo difuso; con telescopio pequeño se distingue el núcleo brillante.","info":"Galaxia espiral de diseño grandioso, a aprox. 12 millones de años luz, la mayor de su grupo. Interacciona gravitatoriamente con M82 y en 1993 mostró la supernova SN 1993J, una de las más cercanas y estudiadas de su época.","myth":"Johann Elert Bode la descubrió en 1774, de ahí su nombre. Pierre Méchain la volvió a observar en 1781 y Messier la incluyó en su catálogo. Forma pareja en el cielo con M82, a menos de un grado."},"en":{"desc":"A bright spiral (mag. about 6.9) seen in binoculars as a diffuse oval; a small telescope shows its bright core.","info":"A grand-design spiral galaxy about 12 million light-years away, the largest of its group. It interacts gravitationally with M82, and in 1993 it hosted supernova SN 1993J, one of the closest and best-studied of its era.","myth":"Johann Elert Bode discovered it in 1774, hence its name. Pierre Méchain observed it again in 1781 and Messier added it to his catalogue. It lies less than a degree from M82 in the sky."}},"galaxia-del-remolino-m51":{"es":{"desc":"Espiral de frente con una pequeña compañera (mag. aprox. 8,4): en telescopio pequeño se ven dos núcleos unidos; los brazos exigen cielo oscuro.","info":"Galaxia espiral de diseño grandioso, a aprox. 23 millones de años luz, que interacciona con su compañera NGC 5195. El paso cercano de esta última refuerza sus brazos y estimula la formación de estrellas.","myth":"Messier la descubrió en 1773 y Méchain añadió después a NGC 5195. En 1845 lord Rosse, con su gran telescopio Leviatán, dibujó su estructura en espiral, la primera galaxia en la que se reconoció esa forma. De ahí el nombre de Remolino."},"en":{"desc":"A face-on spiral with a small companion (mag. about 8.4): a small telescope shows two linked cores; the arms need dark skies.","info":"A grand-design spiral galaxy about 23 million light-years away, interacting with its companion NGC 5195. The close passage of the companion strengthens its arms and triggers star formation.","myth":"Messier discovered it in 1773, and Méchain later noted the companion NGC 5195. In 1845 Lord Rosse, using his great Leviathan telescope, sketched its spiral structure, the first galaxy in which that shape was recognised. Hence the name Whirlpool."}},"gran-nube-de-magallanes":{"es":{"desc":"Mancha luminosa a simple vista en el cielo del hemisferio sur, como un fragmento desprendido de la Vía Láctea; en prismáticos se resuelven cúmulos y nebulosas.","info":"Galaxia satélite de la Vía Láctea, a aprox. 160 000 años luz, de tipo irregular con rastros de barra. Contiene la Nebulosa de la Tarántula, enorme región de formación estelar, y en ella estalló en 1987 la supernova SN 1987A, la más cercana vista a simple vista desde 1604.","myth":"Es conocida por pueblos del sur desde la antigüedad. Su nombre procede de la expedición de Magallanes (1519-1522), cuyos cronistas, como Pigafetta, describieron las dos nubes. Se halla en el límite entre las constelaciones de Dorado y Mensa."},"en":{"desc":"A glowing patch visible to the naked eye in the southern sky, like a detached piece of the Milky Way; binoculars resolve clusters and nebulae.","info":"A satellite galaxy of the Milky Way about 160,000 light-years away, irregular with traces of a bar. It holds the Tarantula Nebula, a huge star-forming region, and in 1987 supernova SN 1987A exploded in it, the closest seen since 1604.","myth":"Southern peoples have known it since antiquity. The name comes from Magellan's expedition (1519-1522), whose chroniclers, such as Pigafetta, described both clouds. It lies on the border of the constellations Dorado and Mensa."}},"pequena-nube-de-magallanes":{"es":{"desc":"Tenue mancha a simple vista en cielos oscuros del hemisferio sur, más pequeña y débil que la Gran Nube; junto a ella se ve el cúmulo 47 Tucanae.","info":"Galaxia irregular enana satélite de la Vía Láctea, a aprox. 200 000 años luz. Está conectada con la Gran Nube por un puente de gas y ambas se influyen gravitatoriamente. 47 Tucanae, en su misma dirección, es un cúmulo de nuestra propia galaxia, mucho más cercano.","myth":"Los cronistas de la expedición de Magallanes, entre 1519 y 1522, la describieron junto a su hermana mayor. Los estudios de Henrietta Leavitt sobre sus estrellas cefeidas, publicados en 1912, dieron la relación período-luminosidad, base para medir distancias cósmicas."},"en":{"desc":"A faint naked-eye patch in dark southern skies, smaller and dimmer than the Large Cloud; the cluster 47 Tucanae shines next to it.","info":"A dwarf irregular satellite galaxy of the Milky Way, about 200,000 light-years away. A bridge of gas links it to the Large Cloud, and they influence each other gravitationally. 47 Tucanae, in the same direction, is a cluster of our own galaxy and much closer.","myth":"The chroniclers of Magellan's expedition, between 1519 and 1522, described it alongside its larger sibling. Henrietta Leavitt's study of its Cepheid stars, published in 1912, revealed the period-luminosity relation, a foundation for measuring cosmic distances."}},"nebulosa-de-orion-m42":{"es":{"desc":"La nebulosa más famosa: visible a simple vista como una estrella difusa en la espada de Orión (mag. aprox. 4); en telescopio pequeño destaca el Trapecio.","info":"Nebulosa de emisión a aprox. 1 300 años luz, una de las regiones de formación estelar masiva más cercanas. El gas brilla por la radiación de las jóvenes estrellas del Trapecio. Forma parte de un enorme complejo de nubes moleculares.","myth":"Nicolas-Claude Fabri de Peiresc la observó con telescopio en 1610 y Christiaan Huygens la dibujó en 1656. Messier la incluyó en su catálogo. Galileo ya había visto las estrellas del Trapecio en 1617, pero no se fijó en la nebulosa."},"en":{"desc":"The most famous nebula: visible to the naked eye as a fuzzy star in Orion's sword (mag. about 4); a small telescope shows the Trapezium.","info":"An emission nebula about 1,300 light-years away, one of the nearest massive star-forming regions. Its gas glows from the radiation of the young Trapezium stars. It is part of a vast complex of molecular clouds.","myth":"Nicolas-Claude Fabri de Peiresc observed it with a telescope in 1610, and Christiaan Huygens drew it in 1656. Messier included it in his catalogue. Galileo had seen the Trapezium stars in 1617 but did not notice the nebula."}},"nebulosa-de-la-laguna-m8":{"es":{"desc":"Nebulosa visible a simple vista en cielos oscuros como una mancha débil (mag. aprox. 6); en prismáticos se ve el cúmulo y una banda oscura que la cruza.","info":"Nebulosa de emisión a unos 4 000-5 000 años luz, región de formación estelar con el joven cúmulo abierto NGC 6530 en su interior. Una franja de polvo oscuro la divide y da nombre a la «laguna». Abarca un tamaño aparente mayor que el de la Luna llena.","myth":"Giovanni Battista Hodierna la registró antes de 1654, y Guillaume Le Gentil la redescubrió en 1747. Messier la incluyó en su catálogo en 1764 como un cúmulo con nebulosidad."},"en":{"desc":"Visible to the naked eye from dark sites as a faint patch (mag. about 6); binoculars show the cluster and a dark lane crossing it.","info":"An emission nebula some 4,000-5,000 light-years away, a star-forming region with the young open cluster NGC 6530 inside. A lane of dark dust splits it and gives the 'lagoon' its name. Its apparent size exceeds that of the full Moon.","myth":"Giovanni Battista Hodierna recorded it before 1654, and Guillaume Le Gentil rediscovered it in 1747. Messier included it in his catalogue in 1764 as a cluster with nebulosity."}},"nebulosa-dumbbell-m27":{"es":{"desc":"Planetaria brillante (mag. aprox. 7,5), visible en prismáticos; con telescopio pequeño recuerda a una pesa o a un reloj de arena.","info":"Nebulosa planetaria a aprox. 1 200-1 400 años luz, formada por las capas de gas expulsadas por una estrella moribunda, hoy una enana blanca. Es una de las planetarias más grandes y fáciles de observar en el cielo.","myth":"Messier la descubrió el 12 de julio de 1764, y fue la primera nebulosa planetaria conocida. El nombre Dumbbell («pesa») se debe a John Herschel. Está en la pequeña constelación de la Zorrita."},"en":{"desc":"A bright planetary nebula (mag. about 7.5) visible in binoculars; in a small telescope it resembles a dumbbell or an hourglass.","info":"A planetary nebula about 1,200-1,400 light-years away, made of gas shed by a dying star that is now a white dwarf. It is one of the largest and easiest planetary nebulae to observe.","myth":"Messier discovered it on 12 July 1764, the first planetary nebula ever known. The name Dumbbell was given by John Herschel. It lies in the small constellation Vulpecula, the Fox."}},"nebulosa-del-anillo-m57":{"es":{"desc":"Pequeño anillo ovalado (mag. aprox. 8,8) que se ve en telescopios pequeños; la estrella central es muy débil y exige instrumentos mayores.","info":"Nebulosa planetaria a unos 2 300 años luz, formada por gas expulsado por una estrella agonizante. El anillo que vemos es probablemente un cilindro de gas visto casi desde el extremo. La estrella central es una enana blanca muy tenue.","myth":"Antoine Darquier de Pellepoix la descubrió en enero de 1779 y Messier la encontró poco después, de forma independiente, e hizo la descripción que la incluyó en su catálogo. Darquier la comparó con un planeta apagado. Se halla entre Sheliak y Sulafat, en la Lira."},"en":{"desc":"A small oval ring (mag. about 8.8) visible in small telescopes; the central star is very faint and needs larger instruments.","info":"A planetary nebula about 2,300 light-years away, formed from gas shed by a dying star. The ring we see is probably a cylinder of gas viewed nearly end-on. The central star is a very faint white dwarf.","myth":"Antoine Darquier de Pellepoix discovered it in January 1779, and Messier found it independently soon after, adding it to his catalogue. Darquier compared it to a faded planet. It lies between Sheliak and Sulafat in Lyra."}},"nebulosa-del-cangrejo-m1":{"es":{"desc":"Pequeña mancha ovalada y débil (mag. aprox. 8,4) que requiere prismáticos y cielo oscuro; el telescopio no muestra los filamentos sin aumentos altos.","info":"Resto de supernova a aprox. 6 500 años luz, en expansión a más de 1 000 km/s. En su centro hay un púlsar que gira unas 30 veces por segundo, descubierto en 1968. Es una de las fuentes de rayos X y gamma más estudiadas.","myth":"John Bevis la descubrió en 1731, y Messier la encontró en 1758 mientras buscaba el cometa Halley; así nació su catálogo, que empieza con ella. Astrónomos chinos registraron en 1054 la supernova que la originó. El nombre Cangrejo viene de un dibujo de lord Rosse."},"en":{"desc":"A small, faint oval glow (mag. about 8.4) that needs binoculars and dark skies; filaments are not visible without high magnification.","info":"A supernova remnant about 6,500 light-years away, expanding at over 1,000 km/s. At its centre lies a pulsar spinning about 30 times per second, discovered in 1968. It is one of the most studied sources of X-rays and gamma rays.","myth":"John Bevis discovered it in 1731, and Messier found it in 1758 while hunting for Halley's Comet; his catalogue begins with it. Chinese astronomers recorded the supernova that created it in 1054. The name Crab comes from a drawing by Lord Rosse."}},"nebulosa-de-eta-carinae":{"es":{"desc":"Enorme nebulosa visible a simple vista como una mancha brillante en la Vía Láctea austral; en prismáticos destacan el Ojo de Cerradura y la estrella Eta Carinae.","info":"Gran región de formación estelar (NGC 3372) a aprox. 7 500 años luz, varias veces mayor que la Nebulosa de Orión. Contiene estrellas masivas, entre ellas Eta Carinae, una estrella inestable que supera con mucho al Sol en masa y brillo.","myth":"Nicolas-Louis de Lacaille la catalogó desde el Cabo de Buena Esperanza hacia 1751-1752. En la década de 1840 Eta Carinae sufrió una gran erupción que la convirtió temporalmente en una de las estrellas más brillantes del cielo."},"en":{"desc":"A huge nebula visible to the naked eye as a bright patch in the southern Milky Way; binoculars show the Keyhole and the star Eta Carinae.","info":"A great star-forming region (NGC 3372) about 7,500 light-years away, several times larger than the Orion Nebula. It holds massive stars, among them Eta Carinae, an unstable star far exceeding the Sun in mass and brightness.","myth":"Nicolas-Louis de Lacaille catalogued it from the Cape of Good Hope around 1751-1752. In the 1840s Eta Carinae suffered a great eruption that temporarily made it one of the brightest stars in the sky."}},"m16":{"es":{"desc":"Nebulosa débil (mag. aprox. 6,0) con un cúmulo de estrellas visible en prismáticos; los detalles de la nebulosa se aprecian con telescopio y filtro.","info":"Nebulosa de emisión asociada al cúmulo joven NGC 6611, a aprox. 7 000 años luz. En su interior están los Pilares de la Creación, columnas de gas y polvo de varios años luz de alto, donde nacen estrellas.","myth":"Jean-Philippe Loys de Chéseaux descubrió el cúmulo hacia 1745-1746 y Messier lo incluyó en su catálogo en 1764. Su nombre alude a la silueta de un águila. La imagen de los Pilares del telescopio Hubble de 1995 es una de las más célebres de la astronomía."},"en":{"desc":"A faint nebula (mag. about 6.0) with a star cluster visible in binoculars; nebular detail appears with a telescope and filter.","info":"An emission nebula linked to the young cluster NGC 6611, about 7,000 light-years away. Inside it are the Pillars of Creation, columns of gas and dust several light-years tall where stars are born.","myth":"Jean-Philippe Loys de Chéseaux discovered the cluster around 1745-1746, and Messier added it to his catalogue in 1764. The name refers to an eagle's silhouette. The Hubble Space Telescope's 1995 image of the Pillars is one of astronomy's most famous."}},"m17":{"es":{"desc":"Nebulosa brillante (mag. aprox. 6,0) con forma de gancho o cisne, visible en prismáticos; un telescopio pequeño muestra su barra luminosa.","info":"Nebulosa de emisión a aprox. 5 500 años luz, una de las regiones de formación de estrellas masivas más activas de la Vía Láctea. La barra brillante y otro brazo curvo le dan forma de omega, cisne o herradura.","myth":"Chéseaux la descubrió hacia 1745-1746 y Messier la incluyó en su catálogo en 1764, describiéndola como una luz alargada sin estrellas. Recibe varios nombres: Omega, Cisne, Herradura y Langosta, según cómo se interprete su silueta."},"en":{"desc":"A bright nebula (mag. about 6.0) shaped like a hook or a swan, visible in binoculars; a small telescope shows its luminous bar.","info":"An emission nebula about 5,500 light-years away, one of the most active massive star-forming regions in the Milky Way. Its bright bar and a curved arm give it the shape of an omega, swan or horseshoe.","myth":"Chéseaux discovered it around 1745-1746, and Messier added it to his catalogue in 1764, describing it as an elongated light without stars. It has several names, Omega, Swan, Horseshoe and Lobster, depending on how its outline is read."}},"m20":{"es":{"desc":"Nebulosa débil (mag. aprox. 6,3) que en telescopio pequeño muestra tres lóbulos separados por bandas oscuras de polvo.","info":"Combina una nebulosa de emisión rosada, una de reflexión azul y bandas de polvo oscuro, a aprox. 5 200 años luz. Es una región joven de formación estelar y en su centro hay una estrella múltiple que la ilumina.","myth":"Messier la descubrió el 5 de junio de 1764. John Herschel le dio el nombre de Trífida, por las tres bandas oscuras que parecen dividirla en tres partes. Está muy cerca de la Laguna, en Sagitario."},"en":{"desc":"A faint nebula (mag. about 6.3) that in a small telescope shows three lobes separated by dark lanes of dust.","info":"It combines a pink emission nebula, a blue reflection nebula and dark dust lanes, about 5,200 light-years away. It is a young star-forming region with a multiple star at its centre that lights it up.","myth":"Messier discovered it on 5 June 1764. John Herschel named it Trifid for the three dark lanes that seem to divide it into three parts. It lies very close to the Lagoon Nebula, in Sagittarius."}},"m24":{"es":{"desc":"Parche brillante de la Vía Láctea (mag. aprox. 4,6), visible a simple vista como un fragmento desprendido; en prismáticos revela miles de estrellas.","info":"No es un cúmulo, sino una zona de la Vía Láctea casi libre de polvo que nos deja mirar hacia el centro galáctico, a aprox. 10 000 años luz. Contiene el cúmulo abierto NGC 6603 y nebulosas oscuras como Barnard 92 y 93.","myth":"Messier la incluyó en su catálogo en 1764 como una gran nube de estrellas en Sagitario. Se la conoce como la Pequeña Nube Estelar de Sagitario. Es de los objetos del catálogo mejores para observar con prismáticos de campo amplio."},"en":{"desc":"A bright patch of the Milky Way (mag. about 4.6), visible to the naked eye like a detached fragment; binoculars reveal thousands of stars.","info":"It is not a cluster but a stretch of the Milky Way nearly free of dust that lets us look toward the galactic centre, about 10,000 light-years away. It contains the open cluster NGC 6603 and dark nebulae such as Barnard 92 and 93.","myth":"Messier included it in his catalogue in 1764 as a great star cloud in Sagittarius. It is known as the Small Sagittarius Star Cloud. It is among the catalogue's best objects for wide-field binoculars."}},"m32":{"es":{"desc":"Pequeña mancha redondeada y brillante (mag. 8,1) junto a M31; se ve con prismáticos y telescopio pequeño como una estrella desenfocada.","info":"Galaxia elíptica compacta, satélite de la galaxia de Andrómeda, a aprox. 2,5 millones de años luz. Su núcleo es muy denso y alberga un agujero negro supermasivo de unos pocos millones de masas solares.","myth":"Guillaume Le Gentil la descubrió en 1749 mientras observaba M31. Messier la incluyó después en su catálogo. Es una de las galaxias más pequeñas del catálogo, pero estudiada por su cercanía."},"en":{"desc":"A small, bright rounded patch (mag. 8.1) next to M31; binoculars and small telescopes show it as an out-of-focus star.","info":"A compact elliptical galaxy, a satellite of the Andromeda Galaxy, about 2.5 million light-years away. Its core is very dense and hosts a supermassive black hole of a few million solar masses.","myth":"Guillaume Le Gentil discovered it in 1749 while observing M31. Messier later included it in his catalogue. It is one of the smallest galaxies in the catalogue, yet well studied because of its proximity."}},"m43":{"es":{"desc":"Pequeña nebulosa en forma de coma (mag. 9,0) justo al norte de M42; se ve con telescopio pequeño.","info":"Nebulosa de emisión a aprox. 1 600 años luz, separada de M42 por una banda de polvo oscuro. Está iluminada principalmente por una joven estrella, NU Orionis, y forma parte del mismo complejo de formación estelar.","myth":"Jean-Jacques Dortous de Mairan la describió en 1731, y de ahí su nombre. Messier la incluyó en su catálogo junto a M42. Es una de las pocas nebulosas que lleva el apellido de su descubridor."},"en":{"desc":"A small comma-shaped nebula (mag. 9.0) just north of M42; visible in a small telescope.","info":"An emission nebula about 1,600 light-years away, separated from M42 by a lane of dark dust. It is lit mainly by a young star, NU Orionis, and belongs to the same star-forming complex.","myth":"Jean-Jacques Dortous de Mairan described it in 1731, hence its name. Messier included it in his catalogue alongside M42. It is one of the few nebulae to carry its discoverer's surname."}},"m49":{"es":{"desc":"Mancha redonda y brillante (mag. 8,4) visible con telescopio pequeño; es una de las galaxias más brillantes de Virgo.","info":"Galaxia elíptica gigante a aprox. 56 millones de años luz, la más luminosa del cúmulo de Virgo, rodeada de numerosos cúmulos globulares. Es el centro de un subgrupo dentro del cúmulo.","myth":"Messier la descubrió el 19 de febrero de 1771. Fue la primera galaxia del cúmulo de Virgo en ser descubierta, aunque entonces se consideraba una simple nebulosa."},"en":{"desc":"A bright round glow (mag. 8.4) visible in a small telescope; one of the brightest galaxies in Virgo.","info":"A giant elliptical galaxy about 56 million light-years away, the most luminous in the Virgo Cluster, surrounded by many globular clusters. It anchors a subgroup within the cluster.","myth":"Messier discovered it on 19 February 1771. It was the first Virgo Cluster galaxy to be found, though at the time it was regarded as a mere nebula."}},"m58":{"es":{"desc":"Galaxia débil (mag. 9,7) de aspecto ovalado con núcleo brillante; hace falta telescopio de 100 mm o más en cielo oscuro.","info":"Galaxia espiral barrada a aprox. 62 millones de años luz, miembro del cúmulo de Virgo. Es una de las espirales barradas más brillantes de este cúmulo y su núcleo muestra actividad.","myth":"Messier la descubrió el 15 de abril de 1779 mientras seguía el cometa de aquel año, y la incluyó en su catálogo. Poco antes había anotado otras galaxias de Virgo, en la zona más rica en nebulosas del cielo."},"en":{"desc":"A faint galaxy (mag. 9.7) with an oval look and a bright core; a 100 mm or larger telescope and dark skies are needed.","info":"A barred spiral galaxy about 62 million light-years away, a member of the Virgo Cluster. It is one of the brightest barred spirals in this cluster, and its core shows signs of activity.","myth":"Messier discovered it on 15 April 1779 while following that year's comet, and added it to his catalogue. He had just recorded other Virgo galaxies, in the sky's richest area of nebulae."}},"m59":{"es":{"desc":"Pequeña galaxia ovalada (mag. 9,6); en telescopio pequeño se ve como una mancha alargada con núcleo brillante.","info":"Galaxia elíptica a aprox. 60 millones de años luz en el cúmulo de Virgo, de forma notablemente alargada. Está muy cerca en el cielo de M60 y, en su entorno, se descubrió una galaxia enana ultracompacta.","myth":"Johann Gottfried Koehler la descubrió en abril de 1779, y Messier la observó poco después y la incluyó en su catálogo. Aparece en la misma noche que otras galaxias de Virgo en los registros de esos días."},"en":{"desc":"A small oval galaxy (mag. 9.6); a small telescope shows an elongated patch with a bright core.","info":"An elliptical galaxy about 60 million light-years away in the Virgo Cluster, notably elongated. It lies very near M60 in the sky, and an ultra-compact dwarf galaxy was found around it.","myth":"Johann Gottfried Koehler discovered it in April 1779, and Messier observed it soon afterwards and added it to his catalogue. It features in the records of those same few days as other Virgo galaxies."}},"m60":{"es":{"desc":"Galaxia brillante (mag. 8,8) de aspecto ovalado; con telescopio pequeño se aprecia junto a la débil NGC 4647.","info":"Galaxia elíptica gigante a aprox. 55 millones de años luz, con un agujero negro supermasivo de varios miles de millones de masas solares. Forma una pareja en interacción con la espiral NGC 4647 (Arp 116).","myth":"Koehler la descubrió en abril de 1779 y Messier la observó de forma independiente pocos días después. Se incluyó en su catálogo junto a M59 y M58, que son galaxias vecinas en Virgo."},"en":{"desc":"A bright galaxy (mag. 8.8) with an oval look; in a small telescope it appears beside the faint NGC 4647.","info":"A giant elliptical galaxy about 55 million light-years away, with a supermassive black hole of several billion solar masses. It forms an interacting pair with the spiral NGC 4647 (Arp 116).","myth":"Koehler discovered it in April 1779, and Messier observed it independently a few days later. It entered his catalogue together with M59 and M58, neighbouring galaxies in Virgo."}},"m61":{"es":{"desc":"Galaxia débil (mag. 9,7) de aspecto circular con núcleo luminoso; en telescopio pequeño se aprecia como una mancha difusa.","info":"Galaxia espiral a aprox. 52 millones de años luz, en el cúmulo de Virgo, con intensa formación estelar. Ha mostrado varias supernovas en el último siglo, lo que la hace muy vigilada.","myth":"Barnaba Oriani la descubrió el 5 de mayo de 1779 mientras seguía un cometa. Messier, que seguía el mismo cometa, la confundió al principio con un cometa y luego la incluyó en su catálogo."},"en":{"desc":"A faint galaxy (mag. 9.7) with a circular look and a luminous core; a small telescope shows a diffuse patch.","info":"A spiral galaxy about 52 million light-years away, in the Virgo Cluster, with vigorous star formation. It has hosted several supernovae over the last century, so it is closely monitored.","myth":"Barnaba Oriani discovered it on 5 May 1779 while following a comet. Messier, tracking the same comet, at first mistook it for a comet too and then added it to his catalogue."}},"m63":{"es":{"desc":"Galaxia alargada y brillante (mag. 8,6); en telescopio pequeño se ve un núcleo muy brillante y un halo ovalado.","info":"Galaxia espiral de brazos algodonosos (floculenta) a aprox. 27 millones de años luz, principal miembro de un grupo en Perros de Caza. Se han detectado corrientes estelares que revelan fusiones pasadas con galaxias menores.","myth":"Pierre Méchain la descubrió el 14 de junio de 1779 y Messier la incluyó en su catálogo. Su nombre alude a sus brazos entrelazados, que recuerdan los pétalos de un girasol."},"en":{"desc":"An elongated, bright galaxy (mag. 8.6); a small telescope shows a very bright core and an oval halo.","info":"A flocculent spiral galaxy with woolly arms about 27 million light-years away, the main member of a group in Canes Venatici. Stellar streams have been detected that reveal past mergers with smaller galaxies.","myth":"Pierre Méchain discovered it on 14 June 1779, and Messier added it to his catalogue. Its name alludes to its interwoven arms, which recall the petals of a sunflower."}},"m64":{"es":{"desc":"Galaxia brillante (mag. 8,5); con telescopio pequeño se aprecia un núcleo luminoso y, con más abertura, la banda oscura que lo rodea.","info":"Galaxia espiral a aprox. 17 millones de años luz, con una espectacular banda de polvo que oscurece un lado del núcleo. El gas exterior gira en sentido contrario al de las estrellas, probablemente por una fusión antigua.","myth":"Edward Pigott la descubrió en marzo de 1779, y poco después Bode y Messier la observaron por su cuenta; Messier la incluyó en su catálogo. Su nombre alude a la banda de polvo que parece un ojo morado."},"en":{"desc":"A bright galaxy (mag. 8.5); a small telescope shows a luminous core and, with more aperture, the dark band around it.","info":"A spiral galaxy about 17 million light-years away, with a spectacular dust band that darkens one side of the core. The outer gas rotates in the opposite sense to the stars, probably due to an ancient merger.","myth":"Edward Pigott discovered it in March 1779, and soon afterwards Bode and Messier observed it independently; Messier added it to his catalogue. The name alludes to the dust band that looks like a bruised eye."}},"m65":{"es":{"desc":"Galaxia alargada y brillante (mag. 9,3) del Triplete de Leo; se ve con telescopio pequeño junto a M66.","info":"Galaxia espiral a aprox. 35 millones de años luz, vista muy inclinada, con un núcleo brillante y bandas de polvo. Forma con M66 y NGC 3628 el famoso Triplete de Leo, un grupo en interacción gravitatoria.","myth":"Pierre Méchain descubrió M65 y M66 en marzo de 1780, y Messier los incluyó poco después en su catálogo. Su proximidad en el cielo hace que se observen juntas en un mismo campo de telescopio."},"en":{"desc":"A bright, elongated galaxy (mag. 9.3) of the Leo Triplet; visible in a small telescope next to M66.","info":"A spiral galaxy about 35 million light-years away, seen tilted, with a bright core and dust lanes. With M66 and NGC 3628 it forms the famous Leo Triplet, a gravitationally interacting group.","myth":"Pierre Méchain discovered M65 and M66 in March 1780, and Messier added them to his catalogue soon after. Their closeness in the sky lets them be seen together in one telescope field."}},"m66":{"es":{"desc":"Galaxia brillante (mag. 8,9) del Triplete de Leo, más luminosa que M65; con telescopio pequeño se ve junto a ella.","info":"Galaxia espiral a aprox. 36 millones de años luz. Sus brazos están algo deformados, probablemente por la interacción gravitatoria con sus vecinas. En ella estalló la supernova SN 1989B.","myth":"Méchain la descubrió en marzo de 1780 junto a M65 y Messier la incluyó en su catálogo. Forma un trío con M65 y NGC 3628 al sur de la zona de Leo."},"en":{"desc":"A bright galaxy (mag. 8.9) of the Leo Triplet, more luminous than M65; a small telescope shows it beside its neighbour.","info":"A spiral galaxy about 36 million light-years away. Its arms are somewhat distorted, probably by gravitational interaction with its neighbours. Supernova SN 1989B exploded in it.","myth":"Méchain discovered it in March 1780 along with M65, and Messier included it in his catalogue. It forms a trio with M65 and NGC 3628 in the Leo region."}},"m73":{"es":{"desc":"Pequeño grupo de cuatro estrellas de mag. 9-10 en forma de Y; en telescopio pequeño no se ve nebulosidad alguna.","info":"No es un cúmulo real, sino un asterismo de cuatro estrellas en Acuario. Los estudios modernos indican que no están físicamente ligadas: sus distancias son muy diferentes, por lo que el dato de aprox. 2 500 años luz es solo orientativo.","myth":"Messier lo descubrió en 1780 y lo incluyó en su catálogo como un cúmulo de unas pocas estrellas con algo de nebulosidad. Es de los objetos más modestos y discutidos de su lista."},"en":{"desc":"A small group of four stars of mag. 9-10 in a Y shape; a small telescope shows no nebulosity at all.","info":"Not a real cluster but an asterism of four stars in Aquarius. Modern studies indicate they are not physically bound: their distances differ greatly, so the figure of about 2,500 light-years is only indicative.","myth":"Messier discovered it in 1780 and listed it as a cluster of a few stars with some nebulosity. It is one of the most modest and debated objects in his list."}},"m74":{"es":{"desc":"Espiral de frente de brillo superficial muy bajo (mag. 9,4); difícil de ver, exige cielo muy oscuro y poca luz de fondo.","info":"Galaxia espiral de diseño grandioso a aprox. 32 millones de años luz, de brazos muy definidos. Ha mostrado varias supernovas, entre ellas SN 2002ap, una hipernova.","myth":"Pierre Méchain la descubrió en 1780 y Messier la observó poco después, incluyéndola en su catálogo. Su apodo, Galaxia Fantasma, refleja lo difícil de verla a ojo."},"en":{"desc":"A face-on spiral of very low surface brightness (mag. 9.4); hard to see, it demands very dark skies and little background light.","info":"A grand-design spiral galaxy about 32 million light-years away, with sharply defined arms. It has hosted several supernovae, among them SN 2002ap, a hypernova.","myth":"Pierre Méchain discovered it in 1780, and Messier observed it shortly afterwards, adding it to his catalogue. Its nickname, the Phantom Galaxy, reflects how hard it is to see by eye."}},"m76":{"es":{"desc":"Planetaria pequeña y débil (mag. 10,1) de forma alargada; con telescopio de 100 mm se aprecia su doble lóbulo.","info":"Nebulosa planetaria bipolar a aprox. 2 500 años luz, formada por gas expulsado por una estrella agonizante. Con dos lóbulos principales y un anillo central. Es de los objetos más débiles del catálogo de Messier.","myth":"Pierre Méchain la descubrió en septiembre de 1780 y Messier la incluyó en su catálogo. Se la llama Pequeña Dumbbell porque recuerda a M27, aunque es menor y más débil."},"en":{"desc":"A small, faint planetary nebula (mag. 10.1) of elongated shape; a 100 mm telescope reveals its double lobe.","info":"A bipolar planetary nebula about 2,500 light-years away, formed from gas shed by a dying star, with two main lobes and a central ring. It is among the faintest objects in Messier's catalogue.","myth":"Pierre Méchain discovered it in September 1780, and Messier added it to his catalogue. It is called the Little Dumbbell because it resembles M27, though it is smaller and fainter."}},"m77":{"es":{"desc":"Galaxia de núcleo muy brillante (mag. 8,9) y halo tenue; en telescopio pequeño parece casi estelar en el centro.","info":"Galaxia espiral a aprox. 47 millones de años luz con un núcleo activo de tipo Seyfert, una de las más conocidas. Su centro emite intensamente en radio y rayos X por la materia que cae en su agujero negro.","myth":"Méchain la descubrió en octubre de 1780 y Messier la incluyó en su catálogo. Ambos la tomaron al principio por un cúmulo de estrellas. Su espectro peculiar fue de los primeros que llevaron a identificar las galaxias Seyfert."},"en":{"desc":"A galaxy with a very bright core (mag. 8.9) and faint halo; in a small telescope the centre looks nearly stellar.","info":"A spiral galaxy about 47 million light-years away with an active Seyfert nucleus, one of the best known. Its centre emits strongly in radio and X-rays from matter falling into its black hole.","myth":"Méchain discovered it in October 1780, and Messier added it to his catalogue. Both at first took it for a star cluster. Its peculiar spectrum was among the first that led to the identification of Seyfert galaxies."}},"m78":{"es":{"desc":"Nebulosa difusa y débil (mag. 8,3) en Orión; con telescopio pequeño y cielo oscuro se ve como una mancha con dos estrellas.","info":"Nebulosa de reflexión a aprox. 1 600 años luz, una de las más brillantes del cielo, que dispersa la luz azulada de dos estrellas jóvenes. Forma parte del mismo gran complejo de nubes que M42.","myth":"Pierre Méchain la descubrió en diciembre de 1780 y Messier la observó y la incluyó en su catálogo. No es una nebulosa de emisión como las vecinas: su brillo es luz estelar reflejada por polvo."},"en":{"desc":"A faint diffuse nebula (mag. 8.3) in Orion; with a small telescope and dark skies it looks like a glow around two stars.","info":"A reflection nebula about 1,600 light-years away, one of the brightest in the sky, scattering the bluish light of two young stars. It belongs to the same great cloud complex as M42.","myth":"Pierre Méchain discovered it in December 1780, and Messier observed it and added it to his catalogue. It is not an emission nebula like its neighbours: its glow is starlight reflected by dust."}},"m82":{"es":{"desc":"Galaxia alargada y brillante (mag. 8,4), vista de canto; con telescopio pequeño se ve junto a M81, con una banda oscura.","info":"Galaxia irregular a aprox. 12 millones de años luz con una formación estelar muy intensa (starburst), provocada por su encuentro con M81. Un viento galáctico expulsa gas en chorros perpendiculares al disco.","myth":"Johann Elert Bode la descubrió en 1774 junto a M81 y Messier la incluyó en su catálogo en 1781. En 2014 mostró la supernova SN 2014J, una de las más cercanas en décadas, descubierta por estudiantes londinenses."},"en":{"desc":"An elongated, bright galaxy (mag. 8.4), seen edge-on; a small telescope shows it beside M81, with a dark band.","info":"An irregular galaxy about 12 million light-years away with very intense star formation (starburst), triggered by its encounter with M81. A galactic wind blows gas out in jets perpendicular to the disc.","myth":"Johann Elert Bode discovered it in 1774 together with M81, and Messier included it in his catalogue in 1781. In 2014 it hosted supernova SN 2014J, one of the closest in decades, discovered by London students."}},"m83":{"es":{"desc":"Galaxia brillante (mag. 7,5) con núcleo marcado; en prismáticos se ve como un óvalo difuso y en telescopios medianos asoma la barra.","info":"Galaxia espiral barrada a aprox. 15 millones de años luz, con intensa formación estelar. Se han registrado al menos seis supernovas, un récord entre las galaxias de su entorno. Se observa mejor desde el hemisferio sur.","myth":"Nicolas-Louis de Lacaille la descubrió en 1752 desde el Cabo de Buena Esperanza. Méchain la redescubrió en 1781 y Messier la incluyó en su catálogo. Se la conoce como el Molinillo Austral en contraste con M101."},"en":{"desc":"A bright galaxy (mag. 7.5) with a marked core; binoculars show a diffuse oval and medium telescopes begin to show the bar.","info":"A barred spiral galaxy about 15 million light-years away, with intense star formation. At least six supernovae have been recorded in it, a record among galaxies of its neighbourhood. It is best seen from the southern hemisphere.","myth":"Nicolas-Louis de Lacaille discovered it in 1752 from the Cape of Good Hope. Méchain rediscovered it in 1781, and Messier added it to his catalogue. It is called the Southern Pinwheel in contrast to M101."}},"m84":{"es":{"desc":"Galaxia redondeada (mag. 9,1) en la Cadena de Markarian; en telescopio pequeño se ve con M86 en el mismo campo.","info":"Galaxia lenticular a aprox. 55 millones de años luz en el cúmulo de Virgo, con un agujero negro supermasivo y chorros que emiten en radio. Es una de las galaxias de la Cadena de Markarian.","myth":"Messier la descubrió el 18 de marzo de 1781, la misma noche que M86 y otras galaxias de Virgo. La Cadena de Markarian recibe su nombre del astrónomo armenio Benjamin Markarian."},"en":{"desc":"A rounded galaxy (mag. 9.1) in Markarian's Chain; a small telescope shows it with M86 in the same field.","info":"A lenticular galaxy about 55 million light-years away in the Virgo Cluster, with a supermassive black hole and jets emitting in radio. It is one of the galaxies of Markarian's Chain.","myth":"Messier discovered it on 18 March 1781, the same night as M86 and other Virgo galaxies. Markarian's Chain is named for the Armenian astronomer Benjamin Markarian."}},"m85":{"es":{"desc":"Galaxia ovalada (mag. 9,1) con núcleo brillante; en telescopio pequeño se ve una mancha difusa junto a una estrella cercana.","info":"Galaxia lenticular a aprox. 60 millones de años luz, la más septentrional de las grandes del cúmulo de Virgo, ya en Cabellera de Berenice. Interacciona con la pequeña NGC 4394. Albergó la supernova SN 1960R.","myth":"Pierre Méchain la descubrió el 4 de marzo de 1781 y Messier la incluyó en su catálogo más tarde, ese mismo mes. Es el último objeto de la lista original ordenada por Messier en 1781."},"en":{"desc":"An oval galaxy (mag. 9.1) with a bright core; a small telescope shows a diffuse patch beside a nearby star.","info":"A lenticular galaxy about 60 million light-years away, the northernmost of the large Virgo Cluster members, already in Coma Berenices. It interacts with the small NGC 4394. It hosted supernova SN 1960R.","myth":"Pierre Méchain discovered it on 4 March 1781, and Messier included it in his catalogue later that month. It is among the galaxies Messier added in 1781, a year of many Virgo discoveries."}},"m86":{"es":{"desc":"Galaxia redondeada y brillante (mag. 8,9), en la Cadena de Markarian; en telescopio pequeño se ve junto a M84.","info":"Galaxia lenticular a aprox. 52 millones de años luz que se acerca a nosotros a unos 244 km/s, una rareza que se explica porque cae hacia el centro del cúmulo de Virgo. Arrastra gas caliente que interacciona con otra galaxia vecina.","myth":"Messier la descubrió el 18 de marzo de 1781 y la incluyó en su catálogo. Es una de las galaxias de la Cadena de Markarian, una hilera visible de galaxias de Virgo."},"en":{"desc":"A bright rounded galaxy (mag. 8.9) in Markarian's Chain; a small telescope shows it next to M84.","info":"A lenticular galaxy about 52 million light-years away that is approaching us at about 244 km/s, an oddity explained by its fall toward the centre of the Virgo Cluster. It trails hot gas that interacts with a neighbouring galaxy.","myth":"Messier discovered it on 18 March 1781 and added it to his catalogue. It is one of the galaxies of Markarian's Chain, a visible row of Virgo galaxies."}},"m87":{"es":{"desc":"Galaxia redonda y brillante (mag. 8,6); en telescopio pequeño es un óvalo difuso con núcleo brillante; el chorro solo se ve en fotografías.","info":"Galaxia elíptica gigante a aprox. 53 millones de años luz, en el centro del cúmulo de Virgo, con miles de cúmulos globulares. Su agujero negro, de unos 6 500 millones de masas solares, lanza un chorro de unos 5 000 años luz.","myth":"Messier la descubrió el 18 de marzo de 1781. Heber Curtis vio el chorro en 1918. En abril de 2019 el Event Horizon Telescope publicó la primera imagen de la sombra de un agujero negro, la de M87."},"en":{"desc":"A bright round galaxy (mag. 8.6); in a small telescope it is a diffuse oval with a bright core; the jet shows only in photographs.","info":"A giant elliptical galaxy about 53 million light-years away, at the centre of the Virgo Cluster, with thousands of globular clusters. Its black hole, about 6.5 billion solar masses, launches a jet some 5,000 light-years long.","myth":"Messier discovered it on 18 March 1781. Heber Curtis noticed the jet in 1918. In April 2019 the Event Horizon Telescope published the first image of a black hole's shadow, that of M87."}},"m88":{"es":{"desc":"Galaxia alargada (mag. 9,6) con núcleo brillante; en telescopio pequeño se aprecia como un óvalo difuso.","info":"Galaxia espiral a aprox. 47 millones de años luz, en la zona de Cabellera de Berenice del cúmulo de Virgo. Sus brazos bien definidos se ven con inclinación, por lo que aparece alargada.","myth":"Messier la descubrió el 18 de marzo de 1781 y la incluyó en su catálogo. Esa noche anotó varias galaxias de la zona."},"en":{"desc":"An elongated galaxy (mag. 9.6) with a bright core; a small telescope shows a diffuse oval.","info":"A spiral galaxy about 47 million light-years away, in the Coma Berenices part of the Virgo Cluster. Its well-defined arms are seen at an angle, so it looks elongated.","myth":"Messier discovered it on 18 March 1781 and added it to his catalogue. That night he noted several galaxies in the region."}},"m89":{"es":{"desc":"Pequeña mancha casi circular (mag. 9,8); en telescopio pequeño apenas se distingue de una estrella desenfocada.","info":"Galaxia elíptica casi esférica a aprox. 50 millones de años luz, en el cúmulo de Virgo. Con técnicas de imagen profunda muestra débiles plumas y capas de estrellas, restos de antiguas interacciones.","myth":"Messier la descubrió el 18 de marzo de 1781 y la incluyó en su catálogo. Se halla cerca de M90 en el cielo."},"en":{"desc":"A small, almost circular glow (mag. 9.8); in a small telescope it is barely distinguishable from an out-of-focus star.","info":"A nearly spherical elliptical galaxy about 50 million light-years away, in the Virgo Cluster. Deep imaging shows faint plumes and shells of stars, remnants of old interactions.","myth":"Messier discovered it on 18 March 1781 and added it to his catalogue. It lies near M90 in the sky."}},"m90":{"es":{"desc":"Galaxia alargada (mag. 9,5) con núcleo brillante; con telescopio de 100 mm en cielo oscuro se ve un óvalo difuso.","info":"Galaxia espiral a aprox. 58 millones de años luz que se acerca a nosotros a unos 280 km/s, una de las pocas del cúmulo de Virgo con desplazamiento al azul. Sus brazos pierden gas al moverse por el cúmulo.","myth":"Messier la descubrió el 18 de marzo de 1781 y la incluyó en su catálogo. Es una de las grandes espirales de la parte occidental del cúmulo de Virgo."},"en":{"desc":"An elongated galaxy (mag. 9.5) with a bright core; a 100 mm telescope under dark skies shows a diffuse oval.","info":"A spiral galaxy about 58 million light-years away that is approaching us at about 280 km/s, one of the few Virgo Cluster members that are blueshifted. Its arms lose gas as it moves through the cluster.","myth":"Messier discovered it on 18 March 1781 and added it to his catalogue. It is one of the large spirals in the western part of the Virgo Cluster."}},"m91":{"es":{"desc":"Galaxia muy débil (mag. 10,2) en Cabellera de Berenice; requiere telescopio de 150 mm y cielo oscuro para verla.","info":"Galaxia espiral barrada a aprox. 63 millones de años luz, miembro del cúmulo de Virgo. Su barra central y sus brazos son discretos, de brillo superficial bajo.","myth":"Messier la anotó en 1781, pero dio una posición equivocada, así que durante mucho tiempo se la consideró un objeto perdido. Se la identificó con NGC 4548 en el siglo XX, y así se completó la lista de objetos."},"en":{"desc":"A very faint galaxy (mag. 10.2) in Coma Berenices; a 150 mm telescope and dark skies are needed to see it.","info":"A barred spiral galaxy about 63 million light-years away, a member of the Virgo Cluster. Its central bar and arms are subtle, with low surface brightness.","myth":"Messier recorded it in 1781 but gave a wrong position, so for a long time it was considered a lost object. It was identified with NGC 4548 in the 20th century, completing the list of objects."}},"m94":{"es":{"desc":"Galaxia compacta y brillante (mag. 8,2); en telescopio pequeño se ve un núcleo muy brillante rodeado de un halo suave.","info":"Galaxia espiral a aprox. 16 millones de años luz, con un anillo interior de intensa formación estelar y un halo exterior tenue. Su núcleo muestra actividad moderada.","myth":"Pierre Méchain la descubrió el 22 de marzo de 1781 y Messier la observó dos días después y la incluyó en su catálogo. Se halla en Perros de Caza, no lejos de Cor Caroli."},"en":{"desc":"A compact, bright galaxy (mag. 8.2); in a small telescope it shows a very bright core wrapped in a soft halo.","info":"A spiral galaxy about 16 million light-years away, with an inner ring of intense star formation and a faint outer halo. Its nucleus shows moderate activity.","myth":"Pierre Méchain discovered it on 22 March 1781, and Messier observed it two days later and added it to his catalogue. It lies in Canes Venatici, not far from Cor Caroli."}},"m95":{"es":{"desc":"Galaxia redondeada (mag. 9,7) con núcleo brillante; en telescopio pequeño se ve un óvalo difuso junto a M96.","info":"Galaxia espiral barrada a aprox. 33 millones de años luz, miembro del grupo de Leo I. Presenta un anillo de formación estelar alrededor de la barra. En 2012 se vio la supernova SN 2012aw.","myth":"Pierre Méchain la descubrió el 20 de marzo de 1781 y Messier la incluyó en su catálogo. Aparece en el mismo campo que M96, descubierta esa misma noche."},"en":{"desc":"A rounded galaxy (mag. 9.7) with a bright core; a small telescope shows a diffuse oval next to M96.","info":"A barred spiral galaxy about 33 million light-years away, a member of the Leo I group. It has a ring of star formation around its bar. Supernova SN 2012aw was seen in it in 2012.","myth":"Pierre Méchain discovered it on 20 March 1781, and Messier added it to his catalogue. It appears in the same field as M96, found that same night."}},"m96":{"es":{"desc":"Galaxia ovalada (mag. 9,2) con núcleo brillante; con telescopio pequeño se ve junto a M95.","info":"Galaxia espiral a aprox. 31 millones de años luz, la más brillante del grupo de Leo I. Sus brazos son asimétricos, probablemente por interacciones con sus vecinas. En ella estalló la supernova SN 1998bu.","myth":"Pierre Méchain la descubrió el 20 de marzo de 1781 y Messier la incluyó en su catálogo. Es el miembro principal del grupo de Leo I, que lleva su nombre."},"en":{"desc":"An oval galaxy (mag. 9.2) with a bright core; a small telescope shows it next to M95.","info":"A spiral galaxy about 31 million light-years away, the brightest of the Leo I group. Its arms are asymmetric, probably due to interactions with neighbours. Supernova SN 1998bu exploded in it.","myth":"Pierre Méchain discovered it on 20 March 1781, and Messier included it in his catalogue. It is the leading member of the Leo I group, sometimes called the M96 Group."}},"m97":{"es":{"desc":"Planetaria débil y casi circular (mag. 9,9) en la Osa Mayor; requiere cielo oscuro y telescopio de 100 mm o más, mejor con filtro.","info":"Nebulosa planetaria a aprox. 2 030 años luz, formada por gas expulsado por una estrella agonizante. Su forma de disco muestra dos zonas oscuras que recuerdan los ojos de un búho.","myth":"Pierre Méchain la descubrió el 16 de febrero de 1781 y Messier la incluyó en su catálogo. El nombre de Búho procede de un dibujo de lord Rosse hacia 1848, que mostraba las dos manchas oscuras."},"en":{"desc":"A faint, nearly circular planetary nebula (mag. 9.9) in Ursa Major; it needs dark skies and a 100 mm or larger telescope, ideally with a filter.","info":"A planetary nebula about 2,030 light-years away, formed from gas shed by a dying star. Its disc shape shows two dark patches that resemble an owl's eyes.","myth":"Pierre Méchain discovered it on 16 February 1781, and Messier added it to his catalogue. The Owl name comes from a drawing by Lord Rosse around 1848 that showed the two dark spots."}},"m98":{"es":{"desc":"Galaxia alargada y débil (mag. 10,1) vista casi de canto; necesita telescopio de 100 mm o más y cielo oscuro.","info":"Galaxia espiral a aprox. 44 millones de años luz en Cabellera de Berenice, a las afueras del cúmulo de Virgo. Se acerca a nosotros, algo inusual a esa distancia.","myth":"Pierre Méchain la descubrió el 15 de marzo de 1781 y Messier la incluyó en su catálogo. Es de las espirales más alargadas de la lista."},"en":{"desc":"A faint, elongated galaxy (mag. 10.1) seen nearly edge-on; it needs a 100 mm or larger telescope and dark skies.","info":"A spiral galaxy about 44 million light-years away in Coma Berenices, on the outskirts of the Virgo Cluster. It is approaching us, which is unusual at that distance.","myth":"Pierre Méchain discovered it on 15 March 1781, and Messier added it to his catalogue. It is one of the most elongated spirals on the list."}},"m99":{"es":{"desc":"Galaxia débil (mag. 9,9) de aspecto circular; en telescopio medio se aprecian vagamente sus brazos.","info":"Galaxia espiral a aprox. 50 millones de años luz, con brazos asimétricos, uno de ellos más extendido que los otros. Ha mostrado varias supernovas en el último siglo.","myth":"Pierre Méchain la descubrió el 15 de marzo de 1781 y Messier la incluyó en su catálogo. En 1846 lord Rosse reconoció su estructura espiral, de las primeras galaxias en que se vio esa forma."},"en":{"desc":"A faint galaxy (mag. 9.9) of circular aspect; a medium telescope vaguely shows its arms.","info":"A spiral galaxy about 50 million light-years away, with asymmetric arms, one of them more extended than the others. It has hosted several supernovae over the last century.","myth":"Pierre Méchain discovered it on 15 March 1781, and Messier added it to his catalogue. In 1846 Lord Rosse recognised its spiral structure, among the first galaxies in which that shape was seen."}},"m100":{"es":{"desc":"Galaxia débil (mag. 9,3) de núcleo brillante y brazos tenues; en telescopio pequeño se ve un óvalo difuso.","info":"Galaxia espiral de diseño grandioso a aprox. 55 millones de años luz, en el cúmulo de Virgo. Ha mostrado varias supernovas. Las cefeidas medidas en ella con el Hubble ayudaron a precisar la escala de distancias del universo.","myth":"Pierre Méchain la descubrió el 15 de marzo de 1781 y Messier la incluyó en su catálogo. Lord Rosse dibujó su estructura espiral hacia mediados del siglo XIX."},"en":{"desc":"A faint galaxy (mag. 9.3) with a bright core and dim arms; a small telescope shows a diffuse oval.","info":"A grand-design spiral galaxy about 55 million light-years away, in the Virgo Cluster. It has hosted several supernovae. Cepheids measured in it with Hubble helped refine the universe's distance scale.","myth":"Pierre Méchain discovered it on 15 March 1781, and Messier added it to his catalogue. Lord Rosse drew its spiral structure in the mid-19th century."}},"m101":{"es":{"desc":"Espiral de frente muy extensa pero de brillo superficial bajo (mag. 7,9); necesita cielo muy oscuro y poco aumento para apreciarla.","info":"Galaxia espiral de diseño grandioso a aprox. 21 millones de años luz y unos 170 000 años luz de diámetro, mayor que la Vía Láctea. En ella estalló la supernova SN 2011fe, una de las más cercanas y mejor estudiadas.","myth":"Pierre Méchain la descubrió el 27 de marzo de 1781 y Messier la incluyó en su catálogo. Su nombre, Molinete, alude a la forma de sus brazos en espiral, parecidos a las aspas de uno."},"en":{"desc":"A very extensive face-on spiral of low surface brightness (mag. 7.9); it needs very dark skies and low magnification to be appreciated.","info":"A grand-design spiral galaxy about 21 million light-years away and some 170,000 light-years across, larger than the Milky Way. Supernova SN 2011fe exploded in it, one of the closest and best-studied.","myth":"Pierre Méchain discovered it on 27 March 1781, and Messier added it to his catalogue. Its name, Pinwheel, alludes to the shape of its spiral arms, like the vanes of a pinwheel."}},"m102":{"es":{"desc":"Galaxia delgada y brillante (mag. 9,9) vista de canto, con una banda de polvo; en telescopio pequeño es un huso luminoso.","info":"Galaxia lenticular a aprox. 44 millones de años luz en Dragón, vista de canto con una marcada banda de polvo. Suele identificarse con NGC 5866, aunque la identidad de M102 se ha discutido.","myth":"Pierre Méchain comunicó este objeto en 1781, y Messier lo incluyó en su catálogo. Más tarde Méchain dijo que podía ser una observación duplicada de M101, por lo que su identidad aún se discute."},"en":{"desc":"A thin, bright galaxy (mag. 9.9) seen edge-on, with a dust lane; in a small telescope it is a luminous spindle.","info":"A lenticular galaxy about 44 million light-years away in Draco, seen edge-on with a marked dust lane. It is usually identified with NGC 5866, though M102's identity has been debated.","myth":"Pierre Méchain reported this object in 1781, and Messier included it in his catalogue. Méchain later said it might be a duplicate observation of M101, so its identity is still debated."}},"m104":{"es":{"desc":"Galaxia brillante (mag. 8,0) con una banda de polvo y un núcleo muy luminoso; en telescopio pequeño recuerda a un sombrero.","info":"Galaxia espiral a aprox. 29 millones de años luz, vista casi de canto, con un gran bulbo central y una banda de polvo oscuro. Alberga un agujero negro supermasivo de unos mil millones de masas solares.","myth":"Pierre Méchain la descubrió el 11 de mayo de 1781; fue añadida más tarde al catálogo de Messier a partir de sus notas. En 1912 Vesto Slipher midió su gran velocidad de alejamiento, de las primeras pruebas de la expansión del universo."},"en":{"desc":"A bright galaxy (mag. 8.0) with a dust lane and a very luminous core; in a small telescope it recalls a sombrero.","info":"A spiral galaxy about 29 million light-years away, seen almost edge-on, with a large central bulge and a lane of dark dust. It hosts a supermassive black hole of about a billion solar masses.","myth":"Pierre Méchain discovered it on 11 May 1781; it was added to Messier's catalogue later, from his notes. In 1912 Vesto Slipher measured its high recession velocity, one of the early clues to the expansion of the universe."}},"m105":{"es":{"desc":"Galaxia redonda y brillante (mag. 9,3) acompañada de otras dos más débiles; se ve bien con telescopio pequeño.","info":"Galaxia elíptica a aprox. 32 millones de años luz, miembro del grupo de Leo I, junto a NGC 3384 y NGC 3389. Todo el grupo está rodeado por un enorme anillo de hidrógeno neutro, el Anillo de Leo.","myth":"Pierre Méchain la descubrió el 24 de marzo de 1781, y Messier la añadió a su catálogo mediante una nota. Es el último objeto de Messier en ser puesto en la lista original por el astrónomo."},"en":{"desc":"A bright round galaxy (mag. 9.3) accompanied by two fainter ones; well seen in a small telescope.","info":"An elliptical galaxy about 32 million light-years away, a member of the Leo I group, alongside NGC 3384 and NGC 3389. The whole group is surrounded by a huge ring of neutral hydrogen, the Leo Ring.","myth":"Pierre Méchain discovered it on 24 March 1781, and Messier added it to his catalogue through a note. It was among the late additions of Messier's work."}},"m106":{"es":{"desc":"Galaxia alargada y brillante (mag. 8,4); en telescopio pequeño muestra un núcleo luminoso y un halo extenso.","info":"Galaxia espiral a aprox. 24 millones de años luz con un núcleo activo tipo Seyfert. Su disco contiene máseres de agua que permitieron medir su distancia con gran precisión y pesar su agujero negro central.","myth":"Pierre Méchain la descubrió en 1781 y Messier la anotó, aunque no la numeró en su lista. Fue incorporada al catálogo en el siglo XX, ya con el número M106."},"en":{"desc":"A bright elongated galaxy (mag. 8.4); a small telescope shows a luminous core and an extensive halo.","info":"A spiral galaxy about 24 million light-years away with an active Seyfert nucleus. Its disc contains water masers that allowed its distance to be measured with great precision and its central black hole to be weighed.","myth":"Pierre Méchain discovered it in 1781, and Messier noted it though he did not number it in his list. It was added to the catalogue in the 20th century, as M106."}},"m108":{"es":{"desc":"Galaxia alargada y débil (mag. 10,0) vista casi de canto, a poca distancia de la estrella Merak; requiere cielo oscuro.","info":"Galaxia espiral barrada a aprox. 46 millones de años luz en la Osa Mayor, vista casi de canto. Su aspecto alargado le ha dado el apodo de Galaxia de la Tabla de Surf. No aparece en la lista original de Messier.","myth":"Pierre Méchain la descubrió en 1781 y Messier la anotó, pero no la numeró en su catálogo original. Fue añadida al catálogo en el siglo XX. Está junto a M97 en el cielo."},"en":{"desc":"A faint, elongated galaxy (mag. 10.0) seen nearly edge-on, a short way from the star Merak; it needs dark skies.","info":"A barred spiral galaxy about 46 million light-years away in Ursa Major, seen nearly edge-on. Its elongated look earned the nickname Surfboard Galaxy. It is not in Messier's original list.","myth":"Pierre Méchain discovered it in 1781, and Messier noted it but did not number it in his original catalogue. It was added in the 20th century. It lies next to M97 in the sky."}},"m109":{"es":{"desc":"Galaxia débil (mag. 9,8) cerca de la estrella Phecda; con telescopio de 100 mm se ve un núcleo ovalado y una barra tenue.","info":"Galaxia espiral barrada a aprox. 83 millones de años luz en la Osa Mayor, con una barra y un anillo de brazos. Es la más lejana del catálogo con esa distancia y vecina de otras galaxias del grupo.","myth":"Pierre Méchain la descubrió en 1781 y Messier la anotó sin numerarla. Fue añadida al catálogo en el siglo XX, junto con M108. En ella se observó la supernova SN 1956A."},"en":{"desc":"A faint galaxy (mag. 9.8) near the star Phecda; a 100 mm telescope shows an oval core and a faint bar.","info":"A barred spiral galaxy about 83 million light-years away in Ursa Major, with a bar and a ring of arms. It is among the farthest at that distance in the catalogue and has neighbours in its group.","myth":"Pierre Méchain discovered it in 1781, and Messier noted it without numbering it. It was added to the catalogue in the 20th century, along with M108. Supernova SN 1956A was observed in it."}},"m110":{"es":{"desc":"Galaxia ovalada y débil (mag. 8,5, pero de brillo superficial bajo), junto a M31; se ve con prismáticos en cielo oscuro.","info":"Galaxia elíptica enana a aprox. 2,7 millones de años luz, satélite de la galaxia de Andrómeda. Es inusual porque contiene polvo y algo de formación estelar, a diferencia de la mayoría de elípticas.","myth":"Messier la dibujó en 1773 pero no la numeró; Caroline Herschel la observó en 1783. Fue añadida al catálogo en el siglo XX, como número 110. Es el último objeto de la lista moderna ampliada."},"en":{"desc":"A faint oval galaxy (mag. 8.5 but low surface brightness), next to M31; visible in binoculars under dark skies.","info":"A dwarf elliptical galaxy about 2.7 million light-years away, a satellite of the Andromeda Galaxy. It is unusual in containing dust and some star formation, unlike most ellipticals.","myth":"Messier drew it in 1773 but did not number it; Caroline Herschel observed it in 1783. It was added to the catalogue in the 20th century as number 110. It is the last object on the modern extended list."}},"pleyades-m45":{"es":{"desc":"El cúmulo abierto más famoso del cielo: a simple vista se ven 6 o 7 estrellas azuladas muy juntas (mag. aprox. 1,6 en conjunto); con prismáticos, decenas.","info":"Cúmulo abierto con más de un millar de estrellas jóvenes, calientes y azules, de unos 100 millones de años de edad. Está a aprox. 440 años luz y ocupa unos 2 grados de cielo. Las estrellas están envueltas en nebulosidad de reflexión, visible en fotografías.","myth":"Conocido desde la Antigüedad en muchas culturas: los griegos veían a las siete hijas de Atlante y Pleione; en Japón se llama Subaru y en la tradición maorí, Matariki. Charles Messier lo incluyó en su catálogo como M45."},"en":{"desc":"The most famous open cluster in the sky: to the naked eye you see 6 or 7 closely packed bluish stars (combined mag. about 1.6); binoculars reveal dozens.","info":"An open cluster of over a thousand young, hot, blue stars, roughly 100 million years old. It lies about 440 light-years away and spans around 2 degrees of sky. The stars are wrapped in reflection nebulosity, visible in long-exposure photographs.","myth":"Known since antiquity to many cultures: the Greeks saw the seven daughters of Atlas and Pleione; in Japan it is Subaru and in Maori tradition, Matariki. Charles Messier listed it in his catalogue as M45."}},"pesebre-m44":{"es":{"desc":"Cúmulo abierto muy grande visible a simple vista como una mancha brillante y difusa (mag. aprox. 3,1) en Cáncer; con prismáticos se resuelve en decenas de estrellas.","info":"Cúmulo abierto de varios cientos de estrellas, a aprox. 600 años luz, de edad similar a las Híades (unos 600-700 millones de años). Ocupa más de 1 grado, así que se aprecia mejor con prismáticos que con telescopio.","myth":"También llamado Praesepe, «pesebre» en latín; las estrellas vecinas Asellus Boreal y Austral son los «asnos» que comen en él. Galileo lo resolvió en estrellas con su telescopio en 1609, y Messier lo incluyó como M44."},"en":{"desc":"A very large open cluster visible to the naked eye as a bright, fuzzy patch (mag. about 3.1) in Cancer; binoculars resolve it into dozens of stars.","info":"An open cluster of several hundred stars about 600 light-years away, of similar age to the Hyades (roughly 600 to 700 million years). It spans more than 1 degree, so binoculars suit it better than a telescope.","myth":"Also called Praesepe, Latin for 'manger'; the neighbouring stars Asellus Borealis and Australis are the 'donkeys' feeding at it. Galileo resolved it into stars with his telescope in 1609, and Messier listed it as M44."}},"cumulo-de-hercules-m13":{"es":{"desc":"El gran cúmulo globular del hemisferio norte: apenas visible a simple vista como una mota en cielos oscuros (mag. aprox. 5,8); en telescopio pequeño, una bola de estrellas.","info":"Cúmulo globular de unas 300 000 estrellas, con más de 11 000 millones de años, a aprox. 22 000 años luz. Mide unos 145 años luz de diámetro. Con telescopios medianos se resuelven sus bordes en estrellas.","myth":"Edmond Halley lo descubrió en 1714 y Messier lo catalogó en 1764 como M13. En 1974 se envió desde el radiotelescopio de Arecibo un mensaje simbólico en su dirección."},"en":{"desc":"The great globular cluster of the northern sky: barely visible to the naked eye as a faint speck under dark skies (mag. about 5.8); a small telescope shows a ball of stars.","info":"A globular cluster of about 300,000 stars, over 11 billion years old, roughly 22,000 light-years away. It is about 145 light-years across. Medium telescopes resolve its outer regions into individual stars.","myth":"Edmond Halley discovered it in 1714 and Messier catalogued it in 1764 as M13. In 1974 a symbolic message was beamed toward it from the Arecibo radio telescope."}},"cumulo-globular-m22":{"es":{"desc":"Uno de los cúmulos globulares más brillantes del cielo (mag. aprox. 5,1): visible a simple vista como una mota en cielos oscuros y espectacular en prismáticos.","info":"Cúmulo globular de varios cientos de miles de estrellas a aprox. 10 000 años luz, de los más cercanos a nosotros. Un telescopio pequeño ya resuelve estrellas individuales en sus bordes. Se ve bajo en el cielo desde latitudes medias del norte.","myth":"Fue observado por Abraham Ihle en 1665, siendo uno de los primeros globulares conocidos. Messier lo incluyó en su catálogo en 1764."},"en":{"desc":"One of the brightest globular clusters in the sky (mag. about 5.1): visible to the naked eye as a faint speck under dark skies and striking in binoculars.","info":"A globular cluster of several hundred thousand stars about 10,000 light-years away, among the nearest to us. Even a small telescope resolves individual stars at its edges. It sits low in the sky from mid-northern latitudes.","myth":"It was observed by Abraham Ihle in 1665, making it one of the first globular clusters known. Messier included it in his catalogue in 1764."}},"cumulo-globular-m4":{"es":{"desc":"Cúmulo globular grande y poco concentrado (mag. aprox. 5,6) situado a poco más de 1 grado de Antares; fácil en prismáticos, y se resuelve en estrellas con telescopio pequeño.","info":"Cúmulo globular a aprox. 7 200 años luz, uno de los más cercanos a la Tierra. Contiene decenas de miles de estrellas y tiene una barra central de estrellas, visible en telescopios medianos. Es muy antiguo, de unos 12 000 millones de años.","myth":"Fue descubierto por Philippe Loys de Chéseaux en 1746 y estudiado por Lacaille en 1752. Messier lo incluyó en su catálogo en 1764; fue uno de los primeros globulares resueltos en estrellas."},"en":{"desc":"A large, loosely packed globular cluster (mag. about 5.6) just over 1 degree from Antares; easy in binoculars, and a small telescope resolves its stars.","info":"A globular cluster about 7,200 light-years away, one of the closest to Earth. It holds tens of thousands of stars and has a central bar of stars visible in medium telescopes. It is very old, around 12 billion years.","myth":"It was discovered by Philippe Loys de Chéseaux in 1746 and studied by Lacaille in 1752. Messier added it to his catalogue in 1764; it was among the first globulars resolved into stars."}},"omega-centauri":{"es":{"desc":"El cúmulo globular más grande y brillante del cielo (mag. aprox. 3,7). A simple vista parece una estrella borrosa; con prismáticos, una gran bola de luz. Pertenece a la constelación del Centauro.","info":"Contiene unos 10 millones de estrellas y mide unos 150 años luz de diámetro, a aprox. 15 800 años luz. Se considera el posible núcleo de una antigua galaxia enana absorbida por la Vía Láctea. Es visible desde el hemisferio sur y latitudes bajas del norte.","myth":"Ptolomeo lo catalogó como una estrella; Edmond Halley notó su aspecto nebuloso en 1677 y Lacaille lo incluyó en su catálogo. Su nombre «Omega» procede de la designación de Bayer. En la constelación del Centauro."},"en":{"desc":"The largest and brightest globular cluster in the sky (mag. about 3.7). To the naked eye it looks like a fuzzy star; binoculars show a big ball of light. It belongs to the constellation Centaurus.","info":"It holds roughly 10 million stars and spans roughly 150 light-years, about 15,800 light-years away. It is thought to be the stripped core of an ancient dwarf galaxy absorbed by the Milky Way. It is visible from the southern hemisphere and low northern latitudes.","myth":"Ptolemy listed it as a star; Edmond Halley noted its nebulous look in 1677 and Lacaille included it in his catalogue. The name 'Omega' comes from Bayer's designation. In the constellation Centaurus."}},"47-tucanae":{"es":{"desc":"Segundo cúmulo globular más brillante del cielo (mag. aprox. 4,1): a simple vista parece una estrella borrosa; con prismáticos o telescopio, un núcleo denso y brillante. Está en el Tucán.","info":"Cúmulo globular de aprox. 1 millón de estrellas, a unos 14 000 años luz, con un núcleo muy concentrado. Aparece en el cielo junto a la Pequeña Nube de Magallanes, aunque está mucho más cerca que ella.","myth":"Fue catalogado por Nicolas-Louis de Lacaille en 1751-52 desde El Cabo. La designación «47 Tucanae» viene del catálogo de estrellas de Bode y de la constelación del Tucán. Desde España no se ve."},"en":{"desc":"The second-brightest globular cluster in the sky (mag. about 4.1): to the naked eye a fuzzy star; binoculars or a telescope show a dense, bright core. It lies in Tucana.","info":"A globular cluster of about 1 million stars, roughly 14,000 light-years away, with a highly concentrated core. It appears in the sky next to the Small Magellanic Cloud, though it is much closer to us.","myth":"It was catalogued by Nicolas-Louis de Lacaille in 1751-52 from the Cape of Good Hope. The name '47 Tucanae' comes from Bode's star catalogue and the constellation Tucana. It is not visible from mid-northern latitudes."}},"cumulo-de-ptolomeo-m7":{"es":{"desc":"Cúmulo abierto brillante y extenso (mag. aprox. 3,3) en la cola de Escorpio, visible a simple vista como una mancha luminosa; magnífico con prismáticos.","info":"Cúmulo abierto de unas 80 estrellas visibles, de unos 200 millones de años, a aprox. 1 000 años luz de nosotros. Ocupa más de 1 grado de cielo. Es el cúmulo abierto más meridional del catálogo Messier.","myth":"Ya lo mencionó Ptolomeo hacia el año 130 d. C. como una «nebulosa» tras la cola del Escorpión, de ahí su nombre. Hodierna lo observó en el siglo XVII y Messier lo incluyó en 1764."},"en":{"desc":"A bright, extended open cluster (mag. about 3.3) in the tail of Scorpius, visible to the naked eye as a glowing patch; superb in binoculars.","info":"An open cluster of around 80 visible stars, about 200 million years old, roughly 1,000 light-years away. It covers over 1 degree of sky. It is the southernmost open cluster in the Messier catalogue.","myth":"Ptolemy mentioned it around 130 AD as a 'nebula' behind the Scorpion's tail, hence its name. Hodierna observed it in the 17th century and Messier included it in 1764."}},"doble-cumulo-de-perseo":{"es":{"desc":"Dos cúmulos abiertos contiguos (mag. aprox. 4 cada uno), visibles a simple vista como una mancha brillante entre Perseo y Casiopea; a bajos aumentos, un campo espectacular.","info":"NGC 869 y NGC 884 (h y χ Persei) son cúmulos abiertos jóvenes, de unos 13 millones de años, a aprox. 7 500 años luz. Se ven juntos en el mismo campo de prismáticos o telescopio de bajos aumentos, con muchas estrellas azules y alguna supergigante roja.","myth":"Conocido desde la Antigüedad (se atribuye a Hiparco una mención hacia el siglo II a. C.). Se encuentra en la constelación de Perseo y no figura en el catálogo de Messier. Los dos cúmulos aparecen designados como h y χ Persei."},"en":{"desc":"Two neighbouring open clusters (mag. about 4 each), visible to the naked eye as a bright patch between Perseus and Cassiopeia; a spectacular field at low power.","info":"NGC 869 and NGC 884 (h and chi Persei) are young open clusters, about 13 million years old, roughly 7,500 light-years away. They fit in the same binocular or low-power telescope field, with many blue stars and a few red supergiants.","myth":"Known since antiquity (a mention by Hipparchus around the 2nd century BC is attributed to him). It lies in the constellation Perseus and is not in the Messier catalogue. The two clusters are designated h and chi Persei."}},"m2":{"es":{"desc":"Cúmulo globular compacto y rico (mag. aprox. 6,5) en Acuario; con prismáticos se ve como una mota redonda y con telescopio pequeño se empiezan a resolver sus bordes.","info":"Cúmulo globular de unas 150 000 estrellas, a aprox. 37 500 años luz. Es uno de los más ricos y concentrados del catálogo Messier, con forma ligeramente achatada.","myth":"Descubierto por Jean-Dominique Maraldi en 1746, Messier lo redescubrió en 1760 y lo incluyó en su catálogo. Está en la constelación de Acuario."},"en":{"desc":"A compact, rich globular cluster (mag. about 6.5) in Aquarius; binoculars show a round speck and a small telescope begins to resolve its edges.","info":"A globular cluster of roughly 150,000 stars, about 37,500 light-years away. It is one of the richest and most concentrated in the Messier catalogue, with a slightly flattened shape.","myth":"Discovered by Jean-Dominique Maraldi in 1746, rediscovered by Messier in 1760, and listed in his catalogue. It lies in the constellation Aquarius."}},"m3":{"es":{"desc":"Brillante cúmulo globular (mag. aprox. 6,2) en Perros de Caza; con prismáticos es una mancha redonda y con telescopio pequeño se resuelven estrellas en sus bordes.","info":"Cúmulo globular de unas 500 000 estrellas, a aprox. 33 900 años luz. Destaca por albergar centenares de estrellas variables, entre ellas muchas RR Lyrae, muy estudiadas.","myth":"Fue el primer objeto que Messier descubrió él mismo, en 1764, y lo incluyó en su catálogo como M3. Se encuentra en la constelación de los Perros de Caza."},"en":{"desc":"A bright globular cluster (mag. about 6.2) in Canes Venatici; binoculars show a round patch and a small telescope resolves stars at its edges.","info":"A globular cluster of some 500,000 stars, about 33,900 light-years away. It is notable for hosting hundreds of variable stars, many of them well-studied RR Lyrae stars.","myth":"It was the first object Messier discovered himself, in 1764, and he listed it in his catalogue as M3. It lies in the constellation Canes Venatici."}},"m5":{"es":{"desc":"Uno de los cúmulos globulares más bellos del norte (mag. aprox. 5,6): visible casi a simple vista en cielos oscuros; en telescopio pequeño, una bola densa con borde granular.","info":"Cúmulo globular de más de 100 000 estrellas, a aprox. 24 500 años luz. Es uno de los más antiguos de la Vía Láctea, con más de 10 000 millones de años. Está en la Serpiente, cerca de la estrella 5 Serpentis.","myth":"Gottfried Kirch lo descubrió en 1702; Messier lo redescubrió en 1764 y lo incluyó en su catálogo como M5."},"en":{"desc":"One of the finest globular clusters of the northern sky (mag. about 5.6): nearly visible to the naked eye under dark skies; a small telescope shows a dense ball with a granular edge.","info":"A globular cluster of over 100,000 stars, about 24,500 light-years away. It is one of the oldest in the Milky Way, more than 10 billion years old. It lies in Serpens, near the star 5 Serpentis.","myth":"Gottfried Kirch discovered it in 1702; Messier rediscovered it in 1764 and listed it in his catalogue as M5."}},"m6":{"es":{"desc":"Cúmulo abierto brillante (mag. aprox. 4,2) en Escorpio, visible a simple vista; con prismáticos o telescopio de bajos aumentos recuerda a una mariposa.","info":"Cúmulo abierto de unas 80 estrellas, a aprox. 1 600 años luz, de unos 100 millones de años. Su forma, con dos «alas» de estrellas, le da el nombre. Contiene una estrella gigante naranja variable, BM Scorpii.","myth":"Fue observado por Hodierna antes de 1654 y Messier lo incluyó en su catálogo en 1764. Su nombre popular, de la Mariposa, viene de su perfil visto en telescopio."},"en":{"desc":"A bright open cluster (mag. about 4.2) in Scorpius, visible to the naked eye; binoculars or a low-power telescope show a butterfly-like shape.","info":"An open cluster of around 80 stars, about 1,600 light-years away, roughly 100 million years old. Its shape, with two 'wings' of stars, gives it its name. It contains an orange variable giant, BM Scorpii.","myth":"Hodierna observed it before 1654 and Messier included it in his catalogue in 1764. Its popular name, the Butterfly Cluster, comes from its outline in a telescope."}},"m9":{"es":{"desc":"Cúmulo globular pequeño y débil (mag. aprox. 7,7) en Ofiuco; en telescopio pequeño es una mancha difusa y redondeada, y requiere más apertura para resolver estrellas.","info":"Cúmulo globular a aprox. 25 800 años luz, muy cerca del centro de la Vía Láctea. Tiene un núcleo denso y una forma algo achatada. En el cielo se ve cerca de la zona de oscuridad por polvo de Ofiuco.","myth":"Messier lo descubrió en 1764 y lo incluyó en su catálogo como M9. Está en la constelación de Ofiuco."},"en":{"desc":"A small, faint globular cluster (mag. about 7.7) in Ophiuchus; in a small telescope it is a round, diffuse patch, and more aperture is needed to resolve stars.","info":"A globular cluster about 25,800 light-years away, quite close to the centre of the Milky Way. It has a dense core and a slightly flattened shape. In the sky it sits near the dusty dark region of Ophiuchus.","myth":"Messier discovered it in 1764 and listed it in his catalogue as M9. It lies in the constellation Ophiuchus."}},"m10":{"es":{"desc":"Cúmulo globular brillante (mag. aprox. 6,6) en Ofiuco, visible con prismáticos como una mancha redonda; con telescopio pequeño se resuelven estrellas en el borde.","info":"Cúmulo globular a aprox. 14 300 años luz, con decenas de miles de estrellas. Se encuentra en el mismo campo que M12, a unos 3 grados, y suele observarse junto a este.","myth":"Messier lo descubrió en 1764 y lo incluyó en su catálogo como M10. Está en la constelación de Ofiuco."},"en":{"desc":"A bright globular cluster (mag. about 6.6) in Ophiuchus, visible in binoculars as a round patch; a small telescope resolves stars at the edge.","info":"A globular cluster about 14,300 light-years away, with tens of thousands of stars. It lies only about 3 degrees from M12 and is often observed together with it.","myth":"Messier discovered it in 1764 and listed it in his catalogue as M10. It lies in the constellation Ophiuchus."}},"m11":{"es":{"desc":"Cúmulo abierto compacto y rico (mag. aprox. 6,3) en el Escudo; con telescopio pequeño parece un abanico de estrellas, con una estrella brillante en un lado.","info":"Cúmulo abierto con unas 3 000 estrellas, a aprox. 6 200 años luz, de unos 250 millones de años. Es uno de los cúmulos abiertos más ricos y densos conocidos.","myth":"Fue descubierto por Gottfried Kirch en 1681 y Messier lo incluyó en su catálogo. Su nombre del Pato Salvaje se debe a que, visto en telescopio, las estrellas forman una V que recuerda a una bandada de patos en vuelo."},"en":{"desc":"A compact, rich open cluster (mag. about 6.3) in Scutum; a small telescope shows a fan of stars with one bright star on one side.","info":"An open cluster of about 3,000 stars, roughly 6,200 light-years away and some 250 million years old. It is one of the richest and densest open clusters known.","myth":"Gottfried Kirch discovered it in 1681 and Messier included it in his catalogue. The name Wild Duck comes from its V-shaped stars in a telescope, recalling a flock of ducks in flight."}},"m12":{"es":{"desc":"Cúmulo globular de brillo medio (mag. aprox. 6,7) en Ofiuco, menos concentrado que M10; visible con prismáticos y resoluble en estrellas con telescopio pequeño.","info":"Cúmulo globular a aprox. 15 700 años luz. Tiene un núcleo relativamente poco denso para un globular. Está cerca de M10, a unos 3 grados, y ambos caben en un campo amplio.","myth":"Messier lo descubrió en 1764 y lo catalogó como M12. Se encuentra en la constelación de Ofiuco."},"en":{"desc":"A medium-bright globular cluster (mag. about 6.7) in Ophiuchus, less concentrated than M10; visible in binoculars and resolvable into stars with a small telescope.","info":"A globular cluster about 15,700 light-years away. Its core is relatively loose for a globular. It lies near M10, about 3 degrees away, and both fit in a wide field.","myth":"Messier discovered it in 1764 and catalogued it as M12. It lies in the constellation Ophiuchus."}},"m14":{"es":{"desc":"Cúmulo globular débil (mag. aprox. 7,6) en Ofiuco; con telescopio pequeño es una mancha redonda y tenue, y hacen falta más aumentos para resolver estrellas.","info":"Cúmulo globular a aprox. 30 300 años luz, bastante rico y de forma ligeramente alargada. En 1938 apareció en él una nova, observada después en fotografías.","myth":"Messier lo descubrió en 1764 y lo incluyó en su catálogo como M14. Está en la constelación de Ofiuco."},"en":{"desc":"A faint globular cluster (mag. about 7.6) in Ophiuchus; in a small telescope it is a dim, round patch, and more magnification is needed to resolve stars.","info":"A globular cluster about 30,300 light-years away, fairly rich and slightly elongated. A nova appeared in it in 1938, later identified on photographs.","myth":"Messier discovered it in 1764 and listed it in his catalogue as M14. It lies in the constellation Ophiuchus."}},"m15":{"es":{"desc":"Cúmulo globular brillante y compacto (mag. aprox. 6,2) en Pegaso, cerca de la estrella Enif; en telescopio pequeño es una bola con centro muy brillante.","info":"Cúmulo globular a aprox. 33 600 años luz, de núcleo extremadamente denso, entre los más concentrados que se conocen. Contiene una nebulosa planetaria, Pease 1, el primer ejemplo conocido en un cúmulo globular.","myth":"Fue descubierto por Jean-Dominique Maraldi en 1746 y Messier lo redescubrió en 1764 y lo incluyó en su catálogo como M15."},"en":{"desc":"A bright, compact globular cluster (mag. about 6.2) in Pegasus, near the star Enif; in a small telescope it is a ball with a very bright centre.","info":"A globular cluster about 33,600 light-years away with an extremely dense core, among the most concentrated known. It holds a planetary nebula, Pease 1, the first one found in a globular cluster.","myth":"Jean-Dominique Maraldi discovered it in 1746, and Messier rediscovered it in 1764 and listed it in his catalogue as M15."}},"m18":{"es":{"desc":"Pequeño cúmulo abierto (mag. aprox. 6,9) en Sagitario, entre las nubes estelares de la Vía Láctea; en telescopio pequeño, unas pocas decenas de estrellas.","info":"Cúmulo abierto a aprox. 4 900 años luz, con unas pocas decenas de estrellas visibles. Está poco poblado y poco destacado, cerca de la nebulosa Omega (M17).","myth":"Messier lo descubrió en 1764 y lo incluyó en su catálogo como M18. Se encuentra en la constelación de Sagitario."},"en":{"desc":"A small open cluster (mag. about 6.9) in Sagittarius, amid the star clouds of the Milky Way; in a small telescope, a few dozen stars.","info":"An open cluster about 4,900 light-years away with only a few dozen visible stars. Sparse and unremarkable, it lies close to the Omega Nebula (M17).","myth":"Messier discovered it in 1764 and listed it in his catalogue as M18. It lies in the constellation Sagittarius."}},"m19":{"es":{"desc":"Cúmulo globular (mag. aprox. 6,8) en Ofiuco, de forma notablemente achatada; con telescopio pequeño se ve como una mancha ovalada con centro brillante.","info":"Cúmulo globular a aprox. 28 700 años luz, uno de los más achatados del catálogo Messier. Está muy cerca del centro galáctico, por lo que el polvo interestelar lo enrojece algo.","myth":"Messier lo descubrió en 1764 y lo incluyó en su catálogo como M19. Está en la constelación de Ofiuco."},"en":{"desc":"A globular cluster (mag. about 6.8) in Ophiuchus with a noticeably flattened shape; in a small telescope it shows as an oval patch with a bright centre.","info":"A globular cluster about 28,700 light-years away, one of the most flattened in the Messier catalogue. It lies close to the galactic centre, so interstellar dust reddens it slightly.","myth":"Messier discovered it in 1764 and listed it in his catalogue as M19. It lies in the constellation Ophiuchus."}},"m21":{"es":{"desc":"Cúmulo abierto (mag. aprox. 5,9) en Sagitario, cerca de la nebulosa Trífida; con prismáticos o telescopio pequeño se ven decenas de estrellas.","info":"Cúmulo abierto joven, de unos 5 millones de años, a aprox. 4 250 años luz. Tiene unas 50 estrellas visibles. Comparte campo con la nebulosa Trífida (M20), a unos 0,7 grados.","myth":"Messier lo descubrió en 1764 y lo incluyó en su catálogo como M21. Está en la constelación de Sagitario."},"en":{"desc":"An open cluster (mag. about 5.9) in Sagittarius, near the Trifid Nebula; binoculars or a small telescope show dozens of stars.","info":"A young open cluster, around 5 million years old, about 4,250 light-years away, with some 50 visible stars. It shares a field with the Trifid Nebula (M20), about 0.7 degrees away.","myth":"Messier discovered it in 1764 and listed it in his catalogue as M21. It lies in the constellation Sagittarius."}},"m23":{"es":{"desc":"Cúmulo abierto rico y extenso (mag. aprox. 5,5) en Sagitario; con prismáticos se ve como una mancha brillante y con telescopio pequeño, decenas de estrellas.","info":"Cúmulo abierto con unas 150 estrellas, a aprox. 2 150 años luz, de unos 300 millones de años. Ocupa casi el tamaño de la Luna llena, así que se aprecia bien a bajos aumentos.","myth":"Messier lo descubrió en 1764 y lo incluyó en su catálogo como M23. Se encuentra en la constelación de Sagitario."},"en":{"desc":"A rich, extended open cluster (mag. about 5.5) in Sagittarius; binoculars show a bright patch and a small telescope reveals dozens of stars.","info":"An open cluster of about 150 stars, about 2,150 light-years away, roughly 300 million years old. It spans nearly the size of the full Moon, so it looks best at low power.","myth":"Messier discovered it in 1764 and listed it in his catalogue as M23. It lies in the constellation Sagittarius."}},"m25":{"es":{"desc":"Cúmulo abierto brillante (mag. aprox. 4,6) en Sagitario, visible a simple vista en cielos oscuros; muy bonito con prismáticos.","info":"Cúmulo abierto con unas 600 estrellas, a aprox. 2 000 años luz, de unos 90 millones de años. Contiene la variable cefeida U Sagittarii, cuyo brillo varía en unos 6,7 días.","myth":"Fue descubierto por Philippe Loys de Chéseaux hacia 1745-46 y Messier lo incluyó en su catálogo en 1764. Es el único objeto Messier con designación IC (IC 4725)."},"en":{"desc":"A bright open cluster (mag. about 4.6) in Sagittarius, visible to the naked eye under dark skies; very pretty in binoculars.","info":"An open cluster of around 600 stars, about 2,000 light-years away, roughly 90 million years old. It contains the Cepheid variable U Sagittarii, whose brightness cycles every 6.7 days.","myth":"Philippe Loys de Chéseaux discovered it around 1745-46 and Messier added it to his catalogue in 1764. It is the only Messier object with an IC designation (IC 4725)."}},"m26":{"es":{"desc":"Cúmulo abierto pequeño y débil (mag. aprox. 8,0) en el Escudo; en telescopio pequeño, un grupo tenue de estrellas poco concentrado.","info":"Cúmulo abierto a aprox. 5 000 años luz, con unas pocas decenas de estrellas visibles. Tiene un hueco central con pocas estrellas, que lo hace distintivo en fotos.","myth":"Messier lo descubrió en 1764 y lo incluyó en su catálogo como M26. Está en la constelación del Escudo, una constelación creada en el siglo XVII por Hevelio."},"en":{"desc":"A small, faint open cluster (mag. about 8.0) in Scutum; in a small telescope, a dim, loosely packed group of stars.","info":"An open cluster about 5,000 light-years away with a few dozen visible stars. A sparse central region makes it distinctive in photographs.","myth":"Messier discovered it in 1764 and listed it in his catalogue as M26. It lies in Scutum, a constellation created in the 17th century by Hevelius."}},"m28":{"es":{"desc":"Cúmulo globular pequeño y brillante (mag. aprox. 6,8) en Sagitario, cerca de la Tetera; con telescopio pequeño es una mancha redonda con centro brillante.","info":"Cúmulo globular a aprox. 18 000 años luz, de núcleo compacto. Contiene un púlsar de milisegundo, el primero hallado en un cúmulo globular. Está cerca de la estrella Lambda Sagittarii.","myth":"Messier lo descubrió en 1764 y lo incluyó en su catálogo como M28. Se encuentra en la constelación de Sagitario."},"en":{"desc":"A small, bright globular cluster (mag. about 6.8) in Sagittarius, near the Teapot; in a small telescope it is a round patch with a bright centre.","info":"A globular cluster about 18,000 light-years away with a compact core. It hosts a millisecond pulsar, the first found in a globular cluster. It lies near the star Lambda Sagittarii.","myth":"Messier discovered it in 1764 and listed it in his catalogue as M28. It lies in the constellation Sagittarius."}},"m29":{"es":{"desc":"Cúmulo abierto pequeño (mag. aprox. 6,6) en el Cisne, cerca de Sadr; en telescopio pequeño, un grupito de estrellas brillantes con forma de cajita.","info":"Cúmulo abierto con unas pocas docenas de estrellas, a aprox. 4 000 años luz. Es poco denso y se ve rodeado por el campo estelar de la Vía Láctea. Está unos 1,7 grados al sur de Sadr.","myth":"Messier lo descubrió en 1764 y lo incluyó en su catálogo como M29. Está en la constelación del Cisne."},"en":{"desc":"A small open cluster (mag. about 6.6) in Cygnus, near Sadr; in a small telescope, a tight group of bright stars shaped like a little box.","info":"An open cluster with a few dozen stars, about 4,000 light-years away. It is sparse and sits against the Milky Way star field. It lies roughly 1.7 degrees south of Sadr.","myth":"Messier discovered it in 1764 and listed it in his catalogue as M29. It lies in the constellation Cygnus."}},"m30":{"es":{"desc":"Cúmulo globular pequeño (mag. aprox. 7,2) en Capricornio; en telescopio pequeño se ve como una mancha brillante, con una hilera de estrellas que sale de su borde.","info":"Cúmulo globular a aprox. 27 000 años luz, de núcleo muy concentrado. Es de los llamados «de núcleo colapsado»: sus estrellas se aprietan en el centro. Hay cadenas de estrellas en su periferia.","myth":"Messier lo descubrió en 1764 y lo incluyó en su catálogo como M30. Se encuentra en la constelación de Capricornio."},"en":{"desc":"A small globular cluster (mag. about 7.2) in Capricornus; in a small telescope it looks like a bright patch, with a line of stars trailing from its edge.","info":"A globular cluster about 27,000 light-years away with a very concentrated core. It is a so-called core-collapsed cluster: its stars crowd tightly at the centre. Chains of stars are seen in its outskirts.","myth":"Messier discovered it in 1764 and listed it in his catalogue as M30. It lies in the constellation Capricornus."}},"m34":{"es":{"desc":"Cúmulo abierto (mag. aprox. 5,5) en Perseo, apenas visible a simple vista en cielos oscuros; con prismáticos o telescopio pequeño, unas decenas de estrellas.","info":"Cúmulo abierto con unas 100 estrellas, a aprox. 1 500 años luz, de unos 200 millones de años. Ocupa un campo similar al de la Luna llena y se aprecia bien con bajos aumentos.","myth":"Fue observado por Hodierna antes de 1654 y Messier lo incluyó en su catálogo en 1764 como M34. Se encuentra en la constelación de Perseo."},"en":{"desc":"An open cluster (mag. about 5.5) in Perseus, just visible to the naked eye under dark skies; binoculars or a small telescope show a few dozen stars.","info":"An open cluster of roughly 100 stars, about 1,500 light-years away, around 200 million years old. It fills a field similar to the full Moon and is best at low power.","myth":"Hodierna observed it before 1654 and Messier included it in his catalogue in 1764 as M34. It lies in the constellation Perseus."}},"m35":{"es":{"desc":"Cúmulo abierto grande y brillante (mag. aprox. 5,3) en Géminis, visible a simple vista en cielos oscuros; con prismáticos se ve como un enjambre de estrellas.","info":"Cúmulo abierto con varios centenares de estrellas, a aprox. 2 800 años luz. Ocupa un área similar a la Luna llena. A su lado, en el mismo campo, se ve el cúmulo más débil y lejano NGC 2158.","myth":"Fue descubierto por Philippe Loys de Chéseaux hacia 1745-46 y Messier lo incluyó en su catálogo en 1764. Está en la constelación de Géminis, junto al pie de Cástor."},"en":{"desc":"A large, bright open cluster (mag. about 5.3) in Gemini, visible to the naked eye under dark skies; binoculars show it as a swarm of stars.","info":"An open cluster of several hundred stars, about 2,800 light-years away. It covers an area similar to the full Moon. In the same field you can see the fainter, more distant cluster NGC 2158.","myth":"Philippe Loys de Chéseaux discovered it around 1745-46 and Messier added it to his catalogue in 1764. It lies in Gemini, near the foot of Castor."}},"m36":{"es":{"desc":"Cúmulo abierto (mag. aprox. 6,0) en Auriga, visible con prismáticos; con telescopio pequeño, unas decenas de estrellas brillantes sobre un fondo tenue.","info":"Cúmulo abierto joven, de unos 25 millones de años, a aprox. 4 100 años luz. Tiene unas 60 estrellas. Forma, junto con M37 y M38, el trío de cúmulos abiertos de Auriga.","myth":"Hodierna lo observó antes de 1654 y Messier lo incluyó en su catálogo en 1764 como M36. Está en la constelación de Auriga, el Cochero."},"en":{"desc":"An open cluster (mag. about 6.0) in Auriga, visible in binoculars; a small telescope shows a few dozen bright stars on a dim background.","info":"A young open cluster, about 25 million years old, roughly 4,100 light-years away, with some 60 stars. Together with M37 and M38 it makes up the trio of open clusters in Auriga.","myth":"Hodierna observed it before 1654 and Messier included it in his catalogue in 1764 as M36. It lies in the constellation Auriga, the Charioteer."}},"m37":{"es":{"desc":"El cúmulo más rico de Auriga (mag. aprox. 5,6): una nube granular de estrellas débiles con una anaranjada en el centro; bonito en prismáticos y más aún en telescopio.","info":"Cúmulo abierto con más de 1 500 estrellas, a aprox. 4 500 años luz, de unos 500 millones de años. Se ve rico y compacto, con muchas estrellas débiles que se funden en una neblina luminosa.","myth":"Hodierna lo observó antes de 1654 y Messier lo catalogó en 1764 como M37. Está en la constelación de Auriga."},"en":{"desc":"The richest cluster in Auriga (mag. about 5.6): a granular cloud of faint stars with an orange one near its centre; lovely in binoculars and more so in a telescope.","info":"An open cluster of over 1,500 stars, about 4,500 light-years away, roughly 500 million years old. It looks rich and compact, with many faint stars blending into a hazy glow.","myth":"Hodierna observed it before 1654 and Messier catalogued it in 1764 as M37. It lies in the constellation Auriga."}},"m38":{"es":{"desc":"Cúmulo abierto (mag. aprox. 6,4) en Auriga, con forma que algunos comparan con una cruz o la letra pi; con telescopio pequeño se ven decenas de estrellas.","info":"Cúmulo abierto con un centenar de estrellas, a aprox. 4 200 años luz, de unos 200 millones de años. Está cerca de su vecino más pequeño, NGC 1907, en el mismo campo de telescopio.","myth":"Hodierna lo observó antes de 1654 y Messier lo incluyó en su catálogo en 1764 como M38. Está en la constelación de Auriga."},"en":{"desc":"An open cluster (mag. about 6.4) in Auriga, with a pattern some compare to a cross or the Greek letter pi; a small telescope shows dozens of stars.","info":"An open cluster of about a hundred stars, around 4,200 light-years away, roughly 200 million years old. It sits close to its smaller neighbour NGC 1907 in the same telescope field.","myth":"Hodierna observed it before 1654 and Messier included it in his catalogue in 1764 as M38. It lies in the constellation Auriga."}},"m39":{"es":{"desc":"Cúmulo abierto grande y laxo (mag. aprox. 4,6) en el Cisne, visible a simple vista en cielos oscuros; ideal con prismáticos o telescopio a bajos aumentos.","info":"Cúmulo abierto con unas 30 estrellas brillantes, a aprox. 800 años luz, de unos 300 millones de años. Ocupa un campo mayor que la Luna llena y es de los más cercanos del catálogo Messier.","myth":"Fue incluido por Messier en su catálogo en 1764 como M39. Se encuentra en la constelación del Cisne, cerca de la Vía Láctea."},"en":{"desc":"A large, loose open cluster (mag. about 4.6) in Cygnus, visible to the naked eye under dark skies; ideal in binoculars or a telescope at low power.","info":"An open cluster of about 30 bright stars, roughly 800 light-years away and around 300 million years old. It spans a field larger than the full Moon and is among the nearest in the Messier catalogue.","myth":"Messier included it in his catalogue in 1764 as M39. It lies in the constellation Cygnus, near the Milky Way."}},"m40":{"es":{"desc":"No es un cúmulo, sino una estrella doble (mag. aprox. 8,4) en la Osa Mayor: dos estrellas casi iguales separadas por unos 50 segundos de arco, fácil de ver en telescopio pequeño.","info":"Winnecke 4 es una pareja de estrellas de brillo similar, a aprox. 510 años luz, sin relación física clara establecida. Su inclusión como cúmulo en el catálogo se debe a una confusión histórica.","myth":"Messier la incluyó en 1764 al buscar una nebulosa señalada por Hevelio y no hallar más que dos estrellas. Friedrich Winnecke la midió en 1863, de ahí su nombre. Se encuentra en la constelación de la Osa Mayor."},"en":{"desc":"Not a cluster but a double star (mag. about 8.4) in Ursa Major: two nearly equal stars about 50 arcseconds apart, easy in a small telescope.","info":"Winnecke 4 is a pair of stars of similar brightness, about 510 light-years away, with no clearly established physical link. Its place in the catalogue comes from a historical mix-up.","myth":"Messier added it in 1764 while looking for a nebula reported by Hevelius and finding only two stars. Friedrich Winnecke measured it in 1863, hence its name. It lies in Ursa Major."}},"m41":{"es":{"desc":"Cúmulo abierto brillante (mag. aprox. 4,5) unos 4 grados al sur de Sirio; visible a simple vista en cielos oscuros y precioso con prismáticos.","info":"Cúmulo abierto con unas 100 estrellas, a aprox. 2 300 años luz, de unos 200 millones de años. Ocupa un área algo mayor que la Luna llena y contiene gigantes rojas visibles con prismáticos.","myth":"Se piensa que Aristóteles pudo mencionarlo hacia el 325 a. C.; Hodierna lo observó en el siglo XVII y Messier lo incluyó en su catálogo en 1764. Está en la constelación del Can Mayor."},"en":{"desc":"A bright open cluster (mag. about 4.5) about 4 degrees south of Sirius; visible to the naked eye under dark skies and gorgeous in binoculars.","info":"An open cluster of about 100 stars, roughly 2,300 light-years away, around 200 million years old. It covers an area somewhat larger than the full Moon and contains red giants visible in binoculars.","myth":"Aristotle may have mentioned it around 325 BC; Hodierna observed it in the 17th century and Messier included it in his catalogue in 1764. It lies in the constellation Canis Major."}},"m46":{"es":{"desc":"Cúmulo abierto rico (mag. aprox. 6,1) en la Popa; con telescopio pequeño se ven cientos de estrellas débiles y, en un borde, una pequeña nebulosa planetaria.","info":"Cúmulo abierto con unas 500 estrellas, a aprox. 5 400 años luz, de unos 300 millones de años. La nebulosa planetaria NGC 2438 aparece superpuesta, pero es probable que no pertenezca al cúmulo.","myth":"Messier lo descubrió en 1771 y lo incluyó en su catálogo como M46. Está en la constelación de la Popa, cerca de M47."},"en":{"desc":"A rich open cluster (mag. about 6.1) in Puppis; a small telescope shows hundreds of faint stars and, near one edge, a small planetary nebula.","info":"An open cluster of about 500 stars, around 5,400 light-years away and roughly 300 million years old. The planetary nebula NGC 2438 appears superimposed on it, but it is probably not a member.","myth":"Messier discovered it in 1771 and listed it in his catalogue as M46. It lies in the constellation Puppis, close to M47."}},"m47":{"es":{"desc":"Cúmulo abierto brillante y disperso (mag. aprox. 4,4) en la Popa, visible a simple vista en cielos oscuros; con prismáticos se ven unas decenas de estrellas.","info":"Cúmulo abierto con unas 50 estrellas, a aprox. 1 600 años luz, de unos 80 millones de años. Está junto a M46, mucho más rico y lejano, y ambos caben en un campo de telescopio de bajos aumentos.","myth":"Hodierna lo observó antes de 1654; Messier lo catalogó en 1771 como M47, aunque erró en la posición. Se encuentra en la constelación de la Popa."},"en":{"desc":"A bright, scattered open cluster (mag. about 4.4) in Puppis, visible to the naked eye under dark skies; binoculars show a few dozen stars.","info":"An open cluster of about 50 stars, roughly 1,600 light-years away and around 80 million years old. It sits beside M46, which is much richer and farther away, and both fit in a low-power telescope field.","myth":"Hodierna observed it before 1654; Messier catalogued it in 1771 as M47, though he gave an erroneous position. It lies in the constellation Puppis."}},"m48":{"es":{"desc":"Cúmulo abierto grande y tenue (mag. aprox. 5,8) en la Hidra; con prismáticos o telescopio pequeño, un enjambre de estrellas de brillo medio.","info":"Cúmulo abierto con unas 80 estrellas, a aprox. 2 500 años luz, de unos 300 millones de años. Ocupa un campo mayor que la Luna llena y se ve mejor con bajos aumentos.","myth":"Messier lo catalogó en 1771 con una posición errónea, por lo que durante mucho tiempo se dudó de qué objeto era. Se identificó con certeza en el siglo XX. Está en la constelación de la Hidra."},"en":{"desc":"A large, faint open cluster (mag. about 5.8) in Hydra; binoculars or a small telescope show a swarm of medium-bright stars.","info":"An open cluster of about 80 stars, roughly 2,500 light-years away, around 300 million years old. It spans a field larger than the full Moon and is best at low power.","myth":"Messier catalogued it in 1771 with an incorrect position, so for a long time it was unclear which object it was. It was firmly identified in the 20th century. It lies in the constellation Hydra."}},"m50":{"es":{"desc":"Cúmulo abierto (mag. aprox. 5,9) en el Unicornio; con prismáticos se ve como una mancha brillante y con telescopio pequeño recuerda a un corazón.","info":"Cúmulo abierto con unas 200 estrellas, a aprox. 3 200 años luz, de unos 130 millones de años. Se encuentra en una zona rica de la Vía Láctea invernal, cerca de Sirio.","myth":"Messier lo incluyó en su catálogo en 1772 como M50. Está en la constelación del Unicornio. Se le llama a veces el Cúmulo del Corazón."},"en":{"desc":"An open cluster (mag. about 5.9) in Monoceros; binoculars show a bright patch and a small telescope suggests a heart shape.","info":"An open cluster of about 200 stars, roughly 3,200 light-years away, around 130 million years old. It lies in a rich region of the winter Milky Way, near Sirius.","myth":"Messier added it to his catalogue in 1772 as M50. It lies in the constellation Monoceros. It is sometimes called the Heart-Shaped Cluster."}},"m52":{"es":{"desc":"Cúmulo abierto (mag. aprox. 6,9) en Casiopea; con telescopio pequeño se ven decenas de estrellas débiles, con una más brillante anaranjada en el borde.","info":"Cúmulo abierto con unas 100 estrellas, a aprox. 5 000 años luz, de unos 35 millones de años. Se encuentra cerca de la Nebulosa de la Burbuja, en el mismo campo de telescopio.","myth":"Messier lo incluyó en su catálogo en 1774 como M52. Se encuentra en la constelación de Casiopea."},"en":{"desc":"An open cluster (mag. about 6.9) in Cassiopeia; a small telescope shows dozens of faint stars, with one brighter orange star at the edge.","info":"An open cluster of about 100 stars, roughly 5,000 light-years away, around 35 million years old. It lies near the Bubble Nebula, in the same telescope field.","myth":"Messier added it to his catalogue in 1774 as M52. It lies in the constellation Cassiopeia."}},"m53":{"es":{"desc":"Cúmulo globular compacto y débil (mag. aprox. 7,6) en la Cabellera de Berenice; con telescopio pequeño es una mancha difusa y con más apertura se resuelve en estrellas.","info":"Cúmulo globular a aprox. 58 000 años luz, bastante lejano y antiguo. Está cerca de la estrella Alfa Comae Berenices y a poca distancia de su vecino NGC 5053.","myth":"Fue descubierto por Johann Elert Bode en 1775 y Messier lo observó poco después, incluyéndolo en su catálogo como M53. Está en la constelación de la Cabellera de Berenice."},"en":{"desc":"A compact, faint globular cluster (mag. about 7.6) in Coma Berenices; a small telescope shows a diffuse patch and larger apertures resolve it into stars.","info":"A globular cluster about 58,000 light-years away, fairly distant and ancient. It lies near the star Alpha Comae Berenices and close to its neighbour NGC 5053.","myth":"Johann Elert Bode discovered it in 1775 and Messier observed it soon after, adding it to his catalogue as M53. It lies in the constellation Coma Berenices."}},"m54":{"es":{"desc":"Cúmulo globular pequeño y débil (mag. aprox. 7,6) en Sagitario; en telescopio pequeño es una mancha estelar, difícil de distinguir de una estrella borrosa.","info":"Cúmulo globular a aprox. 87 000 años luz, uno de los más lejanos del catálogo Messier. Pertenece a la Galaxia Enana de Sagitario, descubierta en 1994, y no a la Vía Láctea propiamente dicha.","myth":"Messier lo descubrió en 1778 y lo incluyó en su catálogo como M54. Se encuentra en la constelación de Sagitario."},"en":{"desc":"A small, faint globular cluster (mag. about 7.6) in Sagittarius; in a small telescope it looks like a stellar blur, hard to tell from a fuzzy star.","info":"A globular cluster about 87,000 light-years away, one of the most distant in the Messier catalogue. It belongs to the Sagittarius Dwarf Galaxy, discovered in 1994, rather than to the Milky Way proper.","myth":"Messier discovered it in 1778 and listed it in his catalogue as M54. It lies in the constellation Sagittarius."}},"m55":{"es":{"desc":"Cúmulo globular grande y poco concentrado (mag. aprox. 6,3) en Sagitario; con telescopio pequeño ya se resuelven estrellas, aunque queda bajo en el cielo desde España.","info":"Cúmulo globular a aprox. 17 600 años luz, de núcleo poco denso. Es uno de los más grandes y brillantes del cielo, y se ve más fácil resolver sus estrellas que en otros globulares.","myth":"Nicolas-Louis de Lacaille lo descubrió en 1751-52 desde El Cabo, y Messier lo incluyó en su catálogo en 1778 como M55. Está en la constelación de Sagitario."},"en":{"desc":"A large, loosely packed globular cluster (mag. about 6.3) in Sagittarius; a small telescope already resolves stars, though it sits low in the sky from mid-northern latitudes.","info":"A globular cluster about 17,600 light-years away with a loose core. It is one of the largest and brightest in the sky, and its stars are easier to resolve than in many other globulars.","myth":"Nicolas-Louis de Lacaille discovered it in 1751-52 from the Cape of Good Hope, and Messier listed it in his catalogue in 1778 as M55. It lies in the constellation Sagittarius."}},"m56":{"es":{"desc":"Cúmulo globular pequeño y débil (mag. aprox. 8,3) en Lira, entre Albireo y Sheliak; con telescopio pequeño es una mancha redonda y tenue.","info":"Cúmulo globular a aprox. 32 900 años luz, de brillo modesto. Aparece sobre un campo rico de la Vía Láctea y requiere cielos oscuros y algo de apertura para resolver estrellas.","myth":"Messier lo descubrió en 1779 y lo incluyó en su catálogo como M56. Está en la constelación de la Lira."},"en":{"desc":"A small, faint globular cluster (mag. about 8.3) in Lyra, between Albireo and Sheliak; a small telescope shows a round, dim patch.","info":"A globular cluster about 32,900 light-years away, of modest brightness. It lies against a rich Milky Way field and needs dark skies and some aperture to resolve stars.","myth":"Messier discovered it in 1779 and listed it in his catalogue as M56. It lies in the constellation Lyra."}},"m62":{"es":{"desc":"Cúmulo globular (mag. aprox. 6,5) en Ofiuco, con forma asimétrica; con telescopio pequeño se ve como una mancha brillante y alargada.","info":"Cúmulo globular a aprox. 22 500 años luz, uno de los más cercanos al centro de la Vía Láctea. Su forma es irregular y contiene muchas estrellas variables.","myth":"Messier lo descubrió en 1771 y lo incluyó en su catálogo como M62. Se encuentra en la constelación de Ofiuco, cerca del Escorpión."},"en":{"desc":"A globular cluster (mag. about 6.5) in Ophiuchus with an asymmetrical shape; in a small telescope it appears as a bright, elongated patch.","info":"A globular cluster about 22,500 light-years away, one of those closest to the centre of the Milky Way. Its shape is irregular and it contains many variable stars.","myth":"Messier discovered it in 1771 and listed it in his catalogue as M62. It lies in the constellation Ophiuchus, near Scorpius."}},"m67":{"es":{"desc":"Cúmulo abierto (mag. aprox. 6,9) en Cáncer; con telescopio pequeño se ven decenas de estrellas, y con más apertura, varios cientos.","info":"Cúmulo abierto con unas 500 estrellas, a aprox. 2 700 años luz, de unos 4 000 millones de años, por lo que es de los más antiguos que se conocen. Es un cúmulo muy estudiado para estimar la edad de las estrellas.","myth":"Fue descubierto por Johann Gottfried Köhler en 1779 y Messier lo incluyó en su catálogo en 1780 como M67. Está en la constelación de Cáncer, al sur del Pesebre."},"en":{"desc":"An open cluster (mag. about 6.9) in Cancer; a small telescope shows dozens of stars, and more aperture reveals several hundred.","info":"An open cluster of about 500 stars, roughly 2,700 light-years away and around 4 billion years old, making it one of the oldest known. It is heavily studied for calibrating stellar ages.","myth":"Johann Gottfried Koehler discovered it in 1779 and Messier listed it in his catalogue in 1780 as M67. It lies in the constellation Cancer, south of the Beehive."}},"m68":{"es":{"desc":"Cúmulo globular débil (mag. aprox. 7,8) en la Hidra; con telescopio pequeño es una mancha difusa y requiere más apertura para resolver estrellas.","info":"Cúmulo globular a aprox. 33 600 años luz, muy antiguo y con relativamente pocos metales. Está bastante al sur y es más fácil de ver desde el hemisferio sur.","myth":"Messier lo incluyó en su catálogo en 1780 como M68. Está en la constelación de la Hidra."},"en":{"desc":"A faint globular cluster (mag. about 7.8) in Hydra; a small telescope shows a diffuse patch and more aperture is needed to resolve stars.","info":"A globular cluster about 33,600 light-years away, very old and relatively metal-poor. It lies well to the south and is easier to see from the southern hemisphere.","myth":"Messier listed it in his catalogue in 1780 as M68. It lies in the constellation Hydra."}},"m69":{"es":{"desc":"Cúmulo globular pequeño y débil (mag. aprox. 7,7) en Sagitario; en telescopio pequeño es un punto difuso, bajo en el cielo desde latitudes medias del norte.","info":"Cúmulo globular a aprox. 29 700 años luz, cerca del centro de la Vía Láctea, muy compacto y relativamente rico en metales. Se aprecia mejor con más apertura.","myth":"Nicolas-Louis de Lacaille lo descubrió en 1751-52 y Messier lo incluyó en su catálogo en 1780 como M69. Está en la constelación de Sagitario."},"en":{"desc":"A small, faint globular cluster (mag. about 7.7) in Sagittarius; in a small telescope a diffuse dot, low in the sky from mid-northern latitudes.","info":"A globular cluster about 29,700 light-years away, near the centre of the Milky Way, very compact and relatively metal-rich. It shows best with more aperture.","myth":"Nicolas-Louis de Lacaille discovered it in 1751-52 and Messier listed it in his catalogue in 1780 as M69. It lies in the constellation Sagittarius."}},"m70":{"es":{"desc":"Cúmulo globular pequeño y compacto (mag. aprox. 7,8) en Sagitario, cerca de M69; en telescopio pequeño es una mancha redonda y débil.","info":"Cúmulo globular a aprox. 29 400 años luz, de núcleo compacto. Comparte campo con M69, a poco más de 2 grados, y a veces se observan juntos.","myth":"Messier lo descubrió en 1780 y lo incluyó en su catálogo como M70. Está en la constelación de Sagitario."},"en":{"desc":"A small, compact globular cluster (mag. about 7.8) in Sagittarius, near M69; in a small telescope a round, faint patch.","info":"A globular cluster about 29,400 light-years away with a compact core. It sits just over 2 degrees from M69, and the two are sometimes observed together.","myth":"Messier discovered it in 1780 and listed it in his catalogue as M70. It lies in the constellation Sagittarius."}},"m71":{"es":{"desc":"Cúmulo globular pequeño (mag. aprox. 8,2) en la Flecha, de aspecto tan suelto que parecía un cúmulo abierto denso; con telescopio pequeño se resuelve bien.","info":"Cúmulo globular a aprox. 12 000 años luz, poco concentrado, durante mucho tiempo clasificado como cúmulo abierto. Hoy se considera un globular de baja densidad.","myth":"Philippe Loys de Chéseaux lo descubrió hacia 1745-46 y Messier lo incluyó en su catálogo en 1780 como M71. Está en la constelación de la Flecha."},"en":{"desc":"A small globular cluster (mag. about 8.2) in Sagitta, so loose-looking it resembled a dense open cluster; a small telescope resolves it well.","info":"A globular cluster about 12,000 light-years away, loosely concentrated, for a long time classified as an open cluster. Today it is regarded as a low-density globular.","myth":"Philippe Loys de Chéseaux discovered it around 1745-46 and Messier listed it in his catalogue in 1780 as M71. It lies in the constellation Sagitta."}},"m72":{"es":{"desc":"Cúmulo globular muy débil (mag. aprox. 9,3) en Acuario; en telescopio pequeño apenas se ve como una mancha pálida, y se resuelve con más apertura.","info":"Cúmulo globular a aprox. 53 000 años luz, de los más débiles y lejanos del catálogo Messier. Se encuentra en una zona del cielo con pocas estrellas brillantes, lo que dificulta localizarlo.","myth":"Pierre Méchain lo descubrió en 1780 y Messier lo observó después, incluyéndolo en su catálogo como M72. Está en la constelación de Acuario."},"en":{"desc":"A very faint globular cluster (mag. about 9.3) in Aquarius; in a small telescope it is barely a pale smudge, resolved only with more aperture.","info":"A globular cluster about 53,000 light-years away, one of the faintest and most distant in the Messier catalogue. It lies in a region with few bright stars, making it hard to locate.","myth":"Pierre Méchain discovered it in 1780 and Messier observed it afterwards, adding it to his catalogue as M72. It lies in the constellation Aquarius."}},"m75":{"es":{"desc":"Cúmulo globular compacto y débil (mag. aprox. 8,6) en Sagitario; en telescopio pequeño casi parece una estrella borrosa, con núcleo muy brillante.","info":"Cúmulo globular a aprox. 67 500 años luz, muy concentrado y de los más lejanos del catálogo Messier. Se encuentra en una región con pocas estrellas brillantes, lejos de la Tetera.","myth":"Pierre Méchain lo descubrió en 1780 y Messier lo incluyó en su catálogo como M75. Se encuentra en la constelación de Sagitario."},"en":{"desc":"A compact, faint globular cluster (mag. about 8.6) in Sagittarius; in a small telescope it nearly looks like a fuzzy star, with a very bright core.","info":"A globular cluster about 67,500 light-years away, highly concentrated and among the most distant in the Messier catalogue. It lies in a region with few bright stars, away from the Teapot.","myth":"Pierre Méchain discovered it in 1780 and Messier included it in his catalogue as M75. It lies in the constellation Sagittarius."}},"m79":{"es":{"desc":"Cúmulo globular (mag. aprox. 7,7) en la Liebre; con telescopio pequeño es una mancha redonda y brillante, uno de los pocos globulares del cielo invernal.","info":"Cúmulo globular a aprox. 41 000 años luz, bastante concentrado y lejano. Es de los pocos globulares visibles en el cielo del hemisferio norte durante el invierno.","myth":"Pierre Méchain lo descubrió en 1780 y Messier lo incluyó en su catálogo como M79. Está en la constelación de la Liebre, bajo Orión."},"en":{"desc":"A globular cluster (mag. about 7.7) in Lepus; a small telescope shows a round, bright patch, one of the few globulars of the winter sky.","info":"A globular cluster about 41,000 light-years away, fairly concentrated and distant. It is one of the few globulars visible in the northern hemisphere's winter sky.","myth":"Pierre Méchain discovered it in 1780 and Messier listed it in his catalogue as M79. It lies in the constellation Lepus, below Orion."}},"m80":{"es":{"desc":"Cúmulo globular denso (mag. aprox. 7,3) en Escorpio, entre Antares y Graffias; en telescopio pequeño es una bolita brillante muy concentrada.","info":"Cúmulo globular a aprox. 32 600 años luz, de los más densos de la Vía Láctea: decenas de miles de estrellas apretadas en un volumen pequeño. En 1860 apareció en él una nova observada desde la Tierra.","myth":"Messier lo descubrió en 1781 y lo incluyó en su catálogo como M80. Se encuentra en la constelación de Escorpio."},"en":{"desc":"A dense globular cluster (mag. about 7.3) in Scorpius, between Antares and Graffias; in a small telescope a bright, tightly packed little ball.","info":"A globular cluster about 32,600 light-years away, one of the densest in the Milky Way: tens of thousands of stars packed in a small volume. A nova was seen in it in 1860.","myth":"Messier discovered it in 1781 and listed it in his catalogue as M80. It lies in the constellation Scorpius."}},"m92":{"es":{"desc":"Cúmulo globular brillante (mag. aprox. 6,4) en Hércules, menos famoso que M13 pero igual de bello; con telescopio pequeño ya muestra estrellas en el borde.","info":"Cúmulo globular a aprox. 26 700 años luz, muy antiguo, de entre 11 000 y 14 000 millones de años. Es uno de los globulares más viejos de la Vía Láctea y contiene pocos metales.","myth":"Johann Elert Bode lo descubrió en 1777 y Messier lo incluyó en su catálogo en 1781 como M92. Se encuentra en la constelación de Hércules, cerca de M13."},"en":{"desc":"A bright globular cluster (mag. about 6.4) in Hercules, less famous than M13 but just as beautiful; a small telescope already shows stars at its edge.","info":"A globular cluster about 26,700 light-years away, very old at roughly 11 to 14 billion years. It is one of the oldest globulars in the Milky Way and is metal-poor.","myth":"Johann Elert Bode discovered it in 1777 and Messier listed it in his catalogue in 1781 as M92. It lies in the constellation Hercules, near M13."}},"m93":{"es":{"desc":"Cúmulo abierto compacto (mag. aprox. 6,2) en la Popa; con telescopio pequeño se ven decenas de estrellas con forma de punta de flecha.","info":"Cúmulo abierto con unas 80 estrellas, a aprox. 3 600 años luz, de unos 100 millones de años. Se encuentra en una región rica de la Vía Láctea invernal, al sur de M47.","myth":"Messier lo descubrió en 1781 y lo incluyó en su catálogo como M93. Está en la constelación de la Popa."},"en":{"desc":"A compact open cluster (mag. about 6.2) in Puppis; a small telescope shows dozens of stars in an arrowhead shape.","info":"An open cluster of about 80 stars, about 3,600 light-years away and roughly 100 million years old. It lies in a rich region of the winter Milky Way, south of M47.","myth":"Messier discovered it in 1781 and listed it in his catalogue as M93. It lies in the constellation Puppis."}},"m103":{"es":{"desc":"Cúmulo abierto pequeño (mag. aprox. 7,4) en Casiopea, cerca de Delta Cassiopeiae; con telescopio pequeño se ven unas pocas decenas de estrellas en forma de triángulo.","info":"Cúmulo abierto con unas 40 estrellas visibles, a aprox. 8 500 años luz, de unos 25 millones de años. Es uno de los objetos más lejanos entre los cúmulos abiertos del catálogo Messier.","myth":"Pierre Méchain lo descubrió en 1781 y fue añadido más tarde al catálogo de Messier como M103, siendo de sus últimos objetos. Está en la constelación de Casiopea."},"en":{"desc":"A small open cluster (mag. about 7.4) in Cassiopeia, near Delta Cassiopeiae; a small telescope shows a few dozen stars in a triangular pattern.","info":"An open cluster of about 40 visible stars, about 8,500 light-years away, roughly 25 million years old. It is one of the most distant open clusters in the Messier catalogue.","myth":"Pierre Méchain discovered it in 1781 and it was later added to Messier's catalogue as M103, among its last entries. It lies in the constellation Cassiopeia."}},"m107":{"es":{"desc":"Cúmulo globular débil (mag. aprox. 7,9) en Ofiuco; con telescopio pequeño es una mancha difusa y tenue, y con más apertura se resuelven estrellas.","info":"Cúmulo globular a aprox. 20 900 años luz, relativamente poco denso. Es uno de los últimos objetos incorporados al catálogo Messier, y fue añadido tardíamente a la lista.","myth":"Pierre Méchain lo descubrió en 1782; Messier no lo incluyó en su lista original, y se añadió al catálogo en el siglo XX como M107. Está en la constelación de Ofiuco."},"en":{"desc":"A faint globular cluster (mag. about 7.9) in Ophiuchus; a small telescope shows a diffuse, dim patch, and more aperture resolves stars.","info":"A globular cluster about 20,900 light-years away, relatively loose. It is one of the last objects added to the Messier catalogue, included late on the list.","myth":"Pierre Méchain discovered it in 1782; it was not in Messier's original list and was added to the catalogue in the 20th century as M107. It lies in the constellation Ophiuchus."}}};
